INSERT INTO `chat_message` VALUES (146, '58751516619b4d36b9d4483c324474fa', 'b6256e5d8765483f840d9a133396d5a0rag-eval', 'ASSISTANT', '资产编号 AU-GW-001 的资产名称为**北区边缘网关**，责任团队为**边缘平台组**。', NULL, NULL, 'qwen3.6-plus', '[{\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771200\", \"documentId\": \"5\", \"rerankScore\": 5.330458641052246, \"chunkContent\": \"资产编号：AU-GW-001; 资产名称：北区边缘网关; 生产区：A区; 子区域：A1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-18; 下次维护时间：2026-09-02 02:00; 维护任务：固件校验; 维护时长（分钟）：45; 关键等级：关键; 备注：负责A区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.80042315}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771202\", \"documentId\": \"5\", \"rerankScore\": 1.6930681467056274, \"chunkContent\": \"资产编号：AU-GW-003; 资产名称：装配区边缘网关; 生产区：C区; 子区域：C1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-20; 下次维护时间：2026-09-16 02:00; 维护任务：时钟校验; 维护时长（分钟）：30; 关键等级：关键; 备注：负责C区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.788249}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771201\", \"documentId\": \"5\", \"rerankScore\": 1.2487331628799438, \"chunkContent\": \"资产编号：AU-GW-002; 资产名称：南区边缘网关; 生产区：B区; 子区域：B1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-19; 下次维护时间：2026-09-09 02:00; 维护任务：缓存检查; 维护时长（分钟）：30; 关键等级：关键; 备注：负责B区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7888893}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 0.6803197264671326, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.129789}]', '2026-09-03 22:31:02', '2026-09-03 22:31:13', 0, 1);
