INSERT INTO `chat_message` VALUES (162, 'a294776a6af841229953f060c9ff3c64', '9ab17166472544d7b50255352fd2e89frag-eval', 'ASSISTANT', '生产数据主库的维护任务是**备份恢复抽查**。', NULL, NULL, 'qwen3.6-plus', '[{\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771225\", \"documentId\": \"5\", \"rerankScore\": 3.9773526191711426, \"chunkContent\": \"资产编号：AU-DB-091; 资产名称：生产数据主库; 生产区：A区; 子区域：A2; 设备型号：DB-16; 责任团队：数据平台组; 运行状态：运行; 最近巡检日期：2026-08-25; 下次维护时间：2026-09-02 02:00; 维护任务：备份恢复抽查; 维护时长（分钟）：45; 关键等级：关键; 备注：保存生产聚合数据\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8845742}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771226\", \"documentId\": \"5\", \"rerankScore\": 3.130493640899658, \"chunkContent\": \"资产编号：AU-DB-092; 资产名称：生产数据备库; 生产区：B区; 子区域：B1; 设备型号：DB-16; 责任团队：数据平台组; 运行状态：待机; 最近巡检日期：2026-08-25; 下次维护时间：2026-09-02 02:50; 维护任务：复制延迟检查; 维护时长（分钟）：25; 关键等级：关键; 备注：主库灾备\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.86787426}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580427\", \"documentId\": \"1\", \"rerankScore\": 0.7441287040710449, \"chunkContent\": \"## 平台依赖与降级运行\\n设备采集依赖工业网络和时间服务，事件处理依赖队列、规则计算和生产数据库，质量报表依赖质量校验与归档存储。判断故障范围时应先确认公共依赖；多个不同型号设备同时异常，通常优先检查网络、时间服务或平台节点，而不是逐台重启设备。\\n当规则计算主节点不可用时，可切换到备用节点，但切换前必须确认规则包版本和校验和一致。归档存储容量预警不会立即中断采集，应先限制非关键导出并清理到期归档。生产数据库主库异常时，是否切换备库由数据平台组和当班经理共同决定。\\n降级运行期间必须明确保留能力和暂停能力。核心告警、安全联锁和网关心跳属于必须保留能力；非关键报表、历史查询和批量导出可以暂停。降级开始和结束时间都要记录在事件时间线中。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.909662}]', '2026-09-03 22:37:19', '2026-09-03 22:37:32', 0, 1);
