INSERT INTO `chat_message` VALUES (172, '84110c24941e41a0b44cd1c1fcfc8112', '99cbc97cc6be47da97fcdd553e53b6c9rag-eval', 'ASSISTANT', 'AU-HMI-111（加工线操作终端）的关键等级为**重要**。\n\n其用途是作为**加工线操作终端**，供授权操作员进行相关操作。', NULL, NULL, 'qwen3.6-plus', '[{\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847810965506\", \"documentId\": \"5\", \"rerankScore\": 4.288077354431152, \"chunkContent\": \"资产编号：AU-HMI-111; 资产名称：加工线操作终端; 生产区：B区; 子区域：B1; 设备型号：HM-12; 责任团队：自动化组; 运行状态：运行; 最近巡检日期：2026-08-27; 下次维护时间：2026-10-07 02:00; 维护任务：账号权限复核; 维护时长（分钟）：25; 关键等级：重要; 备注：仅授权操作员使用\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77465445}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977230\", \"documentId\": \"6\", \"rerankScore\": 1.71183180809021, \"chunkContent\": \"﻿事件编号：INC-260815; 发生时间（CST）：2026-08-24 09:48; 严重级别：P3; 资产编号：AU-HMI-111; 错误码：A-07; 解决时长（分钟）：35; 根本原因：账号权限缓存未刷新; 处置摘要：刷新权限缓存并重新登录; 响应目标是否达标：是; 复盘状态：无需复盘\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7602267}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771211\", \"documentId\": \"5\", \"rerankScore\": 0.7554835081100464, \"chunkContent\": \"资产编号：AU-SW-011; 资产名称：十一号工业交换机; 生产区：A区; 子区域：A1; 设备型号：IS-24; 责任团队：网络保障组; 运行状态：运行; 最近巡检日期：2026-08-16; 下次维护时间：2026-09-02 02:00; 维护任务：端口巡检; 维护时长（分钟）：25; 关键等级：关键; 备注：连接北区网关\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.73569405}]', '2026-09-03 22:41:13', '2026-09-03 22:41:26', 0, 1);
