INSERT INTO `chat_message` VALUES (192, '9a6c7ee23a7d40cb9ec5847653d5f809', '979d11eb6de94b55a6e8a3a260a1f176rag-eval', 'ASSISTANT', 'INC-260826 回退配置的根本原因是**配置校验和不一致**。为解决该问题，采取了回退配置并重新发布的处置措施。', NULL, NULL, 'qwen3.6-plus', '[{\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977241\", \"documentId\": \"6\", \"rerankScore\": 4.288125514984131, \"chunkContent\": \"﻿事件编号：INC-260826; 发生时间（CST）：2026-08-30 05:55; 严重级别：P2; 资产编号：AU-PLC-072; 错误码：C-15; 解决时长（分钟）：84; 根本原因：配置校验和不一致; 处置摘要：回退配置并重新发布; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8437589}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977243\", \"documentId\": \"6\", \"rerankScore\": 1.0497773885726929, \"chunkContent\": \"﻿事件编号：INC-260828; 发生时间（CST）：2026-08-31 00:48; 严重级别：P2; 资产编号：AU-SV-021; 错误码：G-08; 解决时长（分钟）：69; 根本原因：规则包加载不完整; 处置摘要：恢复上版规则包并重载; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8196871}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977238\", \"documentId\": \"6\", \"rerankScore\": 0.7589608430862427, \"chunkContent\": \"﻿事件编号：INC-260823; 发生时间（CST）：2026-08-28 13:29; 严重级别：P3; 资产编号：AU-CM-003; 错误码：V-06; 解决时长（分钟）：61; 根本原因：校准板位置偏移; 处置摘要：固定校准板并重新标定; 响应目标是否达标：是; 复盘状态：无需复盘\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8091754}]', '2026-09-03 22:50:24', '2026-09-03 22:50:32', 0, 1);
