INSERT INTO `chat_message` VALUES (1099, 'c9c9e1cbf03249b48535b438c088fe63', '3a8bfcc5be90407cae487102399952a3rag-eval', 'USER', 'AU-SN-014 的下次维护任务是什么？', 'AU-SN-014 下次维护任务', NULL, NULL, NULL, '2026-09-11 02:22:15', '2026-09-11 02:22:22', 0, 1);
INSERT INTO `chat_message` VALUES (1100, 'da4157c262664bee831e319802a8ee9b', '3a8bfcc5be90407cae487102399952a3rag-eval', 'ASSISTANT', 'AU-SN-014 的下次维护任务是**温度校准**。', NULL, NULL, 'qwen3.7-flash', '[{\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771203\", \"documentId\": \"5\", \"rerankScore\": 5.1811418533325195, \"chunkContent\": \"资产编号：AU-SN-014; 资产名称：十四号温度传感器; 生产区：B区; 子区域：B2; 设备型号：TS-9; 责任团队：设施保障组; 运行状态：运行; 最近巡检日期：2026-08-19; 下次维护时间：2026-09-02 02:50; 维护任务：温度校准; 维护时长（分钟）：20; 关键等级：重要; 备注：环境关键测点\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"parentChunkId\": null, \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.82979524}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 1.6112943887710571, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"parentChunkId\": null, \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.36406}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 1.3703296184539795, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"parentChunkId\": null, \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 7.2985787}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977219\", \"documentId\": \"6\", \"rerankScore\": 0.1941339522600174, \"chunkContent\": \"﻿事件编号：INC-260804; 发生时间（CST）：2026-08-16 08:40; 严重级别：P2; 资产编号：AU-SN-014; 错误码：S-03; 解决时长（分钟）：27; 根本原因：传感器校准偏移; 处置摘要：重新校准并观察二十分钟; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"parentChunkId\": null, \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 7.709821}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771218\", \"documentId\": \"5\", \"rerankScore\": 0.1334163099527359, \"chunkContent\": \"资产编号：AU-UPS-051; 资产名称：不间断电源一号; 生产区：A区; 子区域：A2; 设备型号：UP-60; 责任团队：设施保障组; 运行状态：运行; 最近巡检日期：2026-08-14; 下次维护时间：2026-09-30 02:00; 维护任务：电池放电测试; 维护时长（分钟）：60; 关键等级：关键; 备注：支持平台机柜\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"parentChunkId\": null, \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8129976}]', '2026-09-11 02:22:15', '2026-09-11 02:22:22', 0, 1);
