INSERT INTO `chat_message` VALUES (1117, 'a7b093e7e8ef43c6876a867b8618493b', '785bf6389b48471ca493ac09022e12f0rag-eval', 'USER', '负责B区采集的网关是哪台？', 'B区采集网关信息', NULL, NULL, NULL, '2026-09-11 02:25:49', '2026-09-11 02:26:23', 0, 1);
INSERT INTO `chat_message` VALUES (1118, '584aadde02d14ac5a8db58007e77cf1b', '785bf6389b48471ca493ac09022e12f0rag-eval', 'ASSISTANT', '负责B区采集的网关是资产编号为 **AU-GW-002** 的设备，其资产名称为 **南区边缘网关**。\n\n该设备的具体信息如下：\n*   **生产区**：B区（子区域 B1）\n*   **设备型号**：HG-220\n*   **责任团队**：边缘平台组\n*   **运行状态**：运行\n*   **关键等级**：关键', NULL, NULL, 'qwen3.7-flash', '[{\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771201\", \"documentId\": \"5\", \"rerankScore\": 2.3913493156433105, \"chunkContent\": \"资产编号：AU-GW-002; 资产名称：南区边缘网关; 生产区：B区; 子区域：B1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-19; 下次维护时间：2026-09-09 02:00; 维护任务：缓存检查; 维护时长（分钟）：30; 关键等级：关键; 备注：负责B区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"parentChunkId\": null, \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.82181525}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580417\", \"documentId\": \"1\", \"rerankScore\": 0.3740030229091644, \"chunkContent\": \"## 基本信息\\n曙光智造园区（Aurora Smart Manufacturing Campus）的内部代号为 **Aurora-7**，园区位于虚构城市“海岚市”。园区共有 A、B、C 三个生产区，统一使用 **HG-220** 边缘网关采集设备数据。\", \"documentTitle\": \"01_曙光智造园区概览\", \"parentChunkId\": null, \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77693677}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771200\", \"documentId\": \"5\", \"rerankScore\": -1.062618851661682, \"chunkContent\": \"资产编号：AU-GW-001; 资产名称：北区边缘网关; 生产区：A区; 子区域：A1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-18; 下次维护时间：2026-09-02 02:00; 维护任务：固件校验; 维护时长（分钟）：45; 关键等级：关键; 备注：负责A区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"parentChunkId\": null, \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.815747}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771202\", \"documentId\": \"5\", \"rerankScore\": -1.6088483333587646, \"chunkContent\": \"资产编号：AU-GW-003; 资产名称：装配区边缘网关; 生产区：C区; 子区域：C1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-20; 下次维护时间：2026-09-16 02:00; 维护任务：时钟校验; 维护时长（分钟）：30; 关键等级：关键; 备注：负责C区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"parentChunkId\": null, \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79888463}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580420\", \"documentId\": \"1\", \"rerankScore\": -1.632237434387207, \"chunkContent\": \"## 园区区域与系统组成\\n园区按生产职责划分为三个区域。A 区负责来料检测与能源分配，B 区负责精密加工与环境控制，C 区负责装配、视觉质检和成品暂存。区域下设 A1、A2、B1、B2、C1、C2 六个子区域，子区域编号只用于定位，不改变事件级别。\\n每个子区域至少部署一台环境传感器，关键产线通过 HG-220 边缘网关接入。网关每分钟上报一次心跳，每五分钟汇总一次设备状态。连续丢失三次心跳定义为通信异常，但处置前必须先排除交换机维护、链路抖动和时间同步问题。\\n园区平台由设备采集、事件队列、规则计算、质量校验和报表归档五项能力组成。设备采集负责接收现场数据；事件队列负责削峰；规则计算负责生成告警；质量校验负责识别缺失值和异常值；报表归档负责保存经审批的统计结果。\", \"documentTitle\": \"01_曙光智造园区概览\", \"parentChunkId\": null, \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7873036}]', '2026-09-11 02:25:49', '2026-09-11 02:26:23', 0, 1);
