INSERT INTO `eval_run` VALUES (7, '20260911-014300-7afe0a4b', 'classpath:eval/datasets/eval-test-all.jsonl', '{\"topK\": 5, \"concurrency\": 1, \"enableLlmJudge\": false, \"reviewMrrThreshold\": 0.3, \"reviewScoreThreshold\": 0.6, \"reviewRecallAtKThreshold\": 0.3}', '{\"config\": {\"topK\": 5, \"concurrency\": 1, \"enableLlmJudge\": false, \"reviewMrrThreshold\": 0.3, \"reviewScoreThreshold\": 0.6, \"reviewRecallAtKThreshold\": 0.3}, \"context\": {\"contextRecall\": 0.0, \"contextPrecision\": 0.0, \"contextRecallCount\": 0, \"contextPrecisionCount\": 0}, \"createdAt\": \"2026-09-11T01:43:00.8958042\", \"retrieval\": {\"mrr\": 0.8945000000000001, \"hitAtK\": 0.98, \"recallAtK\": 0.9466666666666664, \"avgLatencyMs\": 30476, \"p50LatencyMs\": 36998, \"p95LatencyMs\": 44982}, \"generation\": {\"relevancy\": 0.0, \"faithfulness\": 0.0, \"relevancyCount\": 0, \"answerCorrectness\": 0.0, \"faithfulnessCount\": 0, \"answerCorrectnessCount\": 0}, \"totalCases\": 100, \"datasetPath\": \"classpath:eval/datasets/eval-test-all.jsonl\", \"failedCaseIds\": [], \"reviewCaseIds\": [\"aurora-md-018\", \"aurora-txt-006\", \"aurora-docx-007\", \"aurora-pdf-017\", \"aurora-xlsx-002\", \"aurora-csv-012\"], \"evaluatedCases\": 100, \"generationEvaluatedCases\": 0}', 100, 100, 0, 'COMPLETED', '2026-09-11 02:33:49', '2026-09-11 02:33:49', 0, 0);
INSERT INTO `eval_run_case` VALUES (101, '20260903-211840-b62c97b8', 'aurora-md-001', '曙光智造园区的内部代号是什么？', '曙光智造园区的内部代号是 **Aurora-7**。', '曙光智造园区内部代号', '[\"353283299259580417\", \"353283812000661504\", \"353285809898651650\"]', '[\"1\", \"2\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580417\", \"documentId\": \"1\", \"rerankScore\": 7.810397624969482, \"chunkContent\": \"## 基本信息\\n曙光智造园区（Aurora Smart Manufacturing Campus）的内部代号为 **Aurora-7**，园区位于虚构城市“海岚市”。园区共有 A、B、C 三个生产区，统一使用 **HG-220** 边缘网关采集设备数据。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8875729}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 2.951829671859741, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.86375207}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 0.6968001127243042, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7760159}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且明确地给出了曙光智造园区的内部代号，完全切题，无任何冗余或无关内容。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文（片段1）中的明确信息，准确指出了曙光智造园区的内部代号为Aurora-7，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1）明确指出曙光智造园区的内部代号为Aurora-7，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"仅片段1直接回答了内部代号问题，片段2和片段3主要为运行手册和故障排查指南，包含大量无关噪声，大部分片段及文本篇幅与问题无关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息无遗漏，仅增加了Markdown加粗格式，不影响语义表达。\"}', 16818, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (102, '20260903-211840-b62c97b8', 'aurora-md-002', '园区包含哪些生产区？', '园区包含 A、B、C 三个生产区，具体职责如下：\n\n*   **A 区**：负责来料检测与能源分配。\n*   **B 区**：负责精密加工与环境控制。\n*   **C 区**：负责装配、视觉质检和成品暂存。', '园区生产区列表', '[\"353283299259580420\", \"353283299259580417\"]', '[\"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580420\", \"documentId\": \"1\", \"rerankScore\": 2.52228045463562, \"chunkContent\": \"## 园区区域与系统组成\\n园区按生产职责划分为三个区域。A 区负责来料检测与能源分配，B 区负责精密加工与环境控制，C 区负责装配、视觉质检和成品暂存。区域下设 A1、A2、B1、B2、C1、C2 六个子区域，子区域编号只用于定位，不改变事件级别。\\n每个子区域至少部署一台环境传感器，关键产线通过 HG-220 边缘网关接入。网关每分钟上报一次心跳，每五分钟汇总一次设备状态。连续丢失三次心跳定义为通信异常，但处置前必须先排除交换机维护、链路抖动和时间同步问题。\\n园区平台由设备采集、事件队列、规则计算、质量校验和报表归档五项能力组成。设备采集负责接收现场数据；事件队列负责削峰；规则计算负责生成告警；质量校验负责识别缺失值和异常值；报表归档负责保存经审批的统计结果。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7960943}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580417\", \"documentId\": \"1\", \"rerankScore\": 1.59458327293396, \"chunkContent\": \"## 基本信息\\n曙光智造园区（Aurora Smart Manufacturing Campus）的内部代号为 **Aurora-7**，园区位于虚构城市“海岚市”。园区共有 A、B、C 三个生产区，统一使用 **HG-220** 边缘网关采集设备数据。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78869677}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型准确回答了园区包含A、B、C三个生产区，直接回应了问题核心。但额外补充了用户未询问的各区域具体职责，略有冗余。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确列出了A、B、C三个生产区及其对应的具体职责，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中的片段1和片段2均明确指出了园区包含A、B、C三个生产区，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"两个检索片段均明确回答了园区包含A、B、C三个生产区，核心信息高度相关。但片段中关于子区域传感器部署、边缘网关心跳机制以及园区平台系统组成的描述与“包含哪些生产区”这一问题无直接关联，属于弱相关或冗余信息。整体来看大部分内容相关，存在少量冗余。\", \"answerCorrectnessReason\": \"模型回答准确指出了园区包含A、B、C三个生产区，与标准答案核心语义完全一致，关键信息无遗漏，补充的职责细节属于合理扩展且未产生冲突。\"}', 29430, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (103, '20260903-211840-b62c97b8', 'aurora-md-003', '园区统一使用哪种边缘网关？', '园区统一使用 **HG-220** 边缘网关。', '园区统一边缘网关型号', '[\"353283299259580417\", \"353285847806771202\", \"353285847806771201\", \"353285847806771200\"]', '[\"1\", \"5\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580417\", \"documentId\": \"1\", \"rerankScore\": 3.098137378692627, \"chunkContent\": \"## 基本信息\\n曙光智造园区（Aurora Smart Manufacturing Campus）的内部代号为 **Aurora-7**，园区位于虚构城市“海岚市”。园区共有 A、B、C 三个生产区，统一使用 **HG-220** 边缘网关采集设备数据。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78820026}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771202\", \"documentId\": \"5\", \"rerankScore\": 0.8247838020324707, \"chunkContent\": \"资产编号：AU-GW-003; 资产名称：装配区边缘网关; 生产区：C区; 子区域：C1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-20; 下次维护时间：2026-09-16 02:00; 维护任务：时钟校验; 维护时长（分钟）：30; 关键等级：关键; 备注：负责C区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.80725217}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771201\", \"documentId\": \"5\", \"rerankScore\": 0.7399847507476807, \"chunkContent\": \"资产编号：AU-GW-002; 资产名称：南区边缘网关; 生产区：B区; 子区域：B1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-19; 下次维护时间：2026-09-09 02:00; 维护任务：缓存检查; 维护时长（分钟）：30; 关键等级：关键; 备注：负责B区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81429553}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771200\", \"documentId\": \"5\", \"rerankScore\": 0.7308092713356018, \"chunkContent\": \"资产编号：AU-GW-001; 资产名称：北区边缘网关; 生产区：A区; 子区域：A1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-18; 下次维护时间：2026-09-02 02:00; 维护任务：固件校验; 维护时长（分钟）：45; 关键等级：关键; 备注：负责A区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.82407534}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地指出了园区统一使用的边缘网关型号（HG-220），完全切题，没有冗余或遗漏信息。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文（特别是片段1明确指出园区统一使用HG-220边缘网关），准确回答了问题，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段1明确指出园区统一使用HG-220边缘网关，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"所有片段均与问题高度相关。片段1直接指明园区统一使用HG-220边缘网关，片段2、3、4分别列出了各生产区网关的详细资产信息，其设备型号均为HG-220，进一步印证了统一使用的事实，无无关噪声片段。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，仅对型号增加了Markdown加粗格式，关键信息无任何遗漏或错误。\"}', 10032, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (104, '20260903-211840-b62c97b8', 'aurora-md-004', '园区正常温度范围是多少？', '抱歉，关于园区正常温度范围，当前知识库中没有相关资料。', '园区正常温度范围', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": null, \"relevancyReason\": \"模型表示知识库中无相关资料，未能提供园区正常温度范围的具体信息，未实际回答用户问题。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型准确识别了信息缺失并如实回答无相关资料，未产生任何捏造或幻觉，完全符合无上下文时的正确拒答表现。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答表示知识库中无相关资料，未能提供标准答案中的具体温度范围（18°C至26°C），完全未回答问题，语义完全不一致。\"}', 29629, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (105, '20260903-211840-b62c97b8', 'aurora-md-005', '园区正常相对湿度范围是多少？', '抱歉，关于园区正常相对湿度范围，当前知识库中没有相关资料。', '园区正常相对湿度范围', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": null, \"relevancyReason\": \"模型表示知识库中无相关资料，未能提供园区正常相对湿度的具体数值范围，未实际回答用户问题。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型如实指出无相关资料，未捏造任何信息，回答完全符合上下文情况。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答表示知识库中没有相关资料，未能提供标准答案中具体的相对湿度范围（35%至65%），属于拒答，与标准答案完全不一致。\"}', 23623, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (106, '20260903-211840-b62c97b8', 'aurora-md-006', '网关本地缓存达到多少时发出预警？', '网关本地缓存使用率达到 **25%** 时会发出预警。', '网关本地缓存预警阈值', '[\"353283299259580421\", \"353283299259580418\"]', '[\"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 4.947673797607422, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8465362}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580418\", \"documentId\": \"1\", \"rerankScore\": 3.460612535476685, \"chunkContent\": \"## 环境标准\\n- 正常温度范围：18°C 至 26°C。\\n- 正常相对湿度范围：35% 至 65%。\\n- 网关本地缓存使用率达到 **25%** 时应发出预警。\\n- 每周维护窗口：星期三 02:00 至 03:30（CST）。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8579296}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且明确地给出了网关本地缓存发出预警的具体阈值（25%），完全切题，准确回应了问题核心，且无任何冗余或无关内容。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确指出了网关本地缓存使用率达到25%时发出预警，不存在捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1和片段2）均明确指出网关本地缓存使用率达到25%时发出预警，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"两个片段均包含了回答问题的关键信息（缓存使用率达到25%），但上下文中充斥着大量无关的其他告警阈值、环境标准及运维流程等噪声信息，相关信息点占比仅约20%，大部分内容与问题无关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息（25%）准确无遗漏，仅增加了加粗格式和语气词\'会\'，不影响核心含义。\"}', 22796, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (107, '20260903-211840-b62c97b8', 'aurora-md-007', '网关本地缓存达到多少时暂停非关键采集任务？', '网关本地缓存使用率达到 **40%** 时，会暂停非关键采集任务。', '网关本地缓存暂停非关键采集任务阈值', '[\"353283299259580421\", \"353283812000661505\"]', '[\"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 5.265221118927002, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.83759534}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 1.9342225790023804, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.841848}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、明确地给出了具体数值（40%），完全切题，准确回应了问题核心，且没有任何冗余或无关内容。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确指出了网关本地缓存使用率达到40%时暂停非关键采集任务，无捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1和片段2）明确指出网关本地缓存使用率达到40%时暂停非关键采集任务，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"两个片段均包含了回答问题的关键信息（缓存达到40%时暂停），但上下文中夹杂了大量关于心跳、温湿度、事件队列和维护窗口等与问题无关的噪声内容，相关文本占比约为20%-30%。\", \"answerCorrectnessReason\": \"语义完全一致，关键信息无遗漏，仅增加了强调格式和助词，不影响核心含义。\"}', 8364, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (108, '20260903-211840-b62c97b8', 'aurora-md-008', '园区固定维护窗口是什么时间？', '园区的固定维护窗口时间为**每周三 02:00 至 03:30 CST**。\n\n在此期间，窗口开始前十五分钟需暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。', '园区固定维护窗口时间', '[\"353283812000661504\", \"353283299259580423\"]', '[\"2\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 3.990023136138916, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81652397}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": 3.007726669311523, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81738365}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接且准确地回答了固定维护窗口的具体时间，但补充了用户未询问的任务暂停和抽样校验等操作细节，略有冗余。\", \"contextPrecision\": 0.4, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确指出了固定维护窗口的时间（每周三 02:00 至 03:30 CST），并正确补充了相关的操作要求（提前十五分钟暂停非关键批任务，结束后由 Quality 团队抽样校验），无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1和片段2）明确指出了固定维护窗口的时间为每周三 02:00 至 03:30（CST），完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"两个检索片段均包含了维护窗口的准确时间，但片段内部存在大量如开班检查、环境处置、交接要求和紧急变更等无关信息，噪声较多，相关文本占比不足一半。\", \"answerCorrectnessReason\": \"模型回答准确包含了标准答案的全部关键信息：每周三 02:00 至 03:30 CST，语义完全一致。额外补充的维护窗口前后操作细节不影响核心答案的正确性。\"}', 10009, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (109, '20260903-211840-b62c97b8', 'aurora-md-009', 'P1 事件的首次响应目标是多少？', 'P1 事件的首次响应目标是 **15 分钟**。', 'P1事件首次响应时间标准', '[\"353283299259580422\", \"353283299259580419\", \"353283299259580429\", \"353283812000661506\"]', '[\"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 3.128629684448242, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.83811057}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580419\", \"documentId\": \"1\", \"rerankScore\": 2.6003265380859375, \"chunkContent\": \"## 服务等级\\n| 级别 | 首次响应目标 | 示例 |\\n|---|---:|---|\\n| P1 | 15 分钟 | 全园区停产或安全联锁失效 |\\n| P2 | 2 小时 | 单个生产区核心能力降级 |\\n| P3 | 1 个工作日 | 非关键报表或体验问题 |\\n紧急停机演练使用的虚构口令为 **ORBIT-7429**。该口令仅用于本测试数据，不对应任何真实系统。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81586266}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580429\", \"documentId\": \"1\", \"rerankScore\": 2.1693687438964844, \"chunkContent\": \"## 评测事实边界\\n本数据集中的时间、阈值、资产和流程构成封闭测试事实。不同文档出现同一规则时，应以条件更具体的条款回答。例如“P2 首次响应目标为两小时”和“P2 超过两小时未恢复升级为 P1”描述的是不同管理节点，回答时必须保留“首次响应”或“未恢复”的条件。\\n资产编号和错误码是专有标识，不应翻译或改写。团队英文代号仅用于保持跨文档一致性，不代表需要使用英文回答。文档没有给出具体责任人的场景，应回答责任团队或当班经理，不得编造姓名和联系方式。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7997415}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 2.029660940170288, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.68677}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地回答了用户关于P1事件首次响应目标的问题，没有冗余或无关内容，完全切题。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文片段2中的服务等级表格，准确指出了P1事件的首次响应目标为15分钟，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段2的服务等级表格中明确列出了P1级别的首次响应目标为15分钟，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"片段2直接回答了P1事件的首次响应目标，片段1和4提及了P1事件的响应概念与通报时效等相关背景，片段3为无关的评测说明。整体约有一半片段相关，噪声较多。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息无遗漏，仅对关键数值增加了Markdown加粗格式，不影响核心含义。\"}', 15593, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (110, '20260903-211840-b62c97b8', 'aurora-md-010', 'P2 事件的首次响应目标是多少？', '抱歉，关于P2 事件的首次响应目标，当前知识库中没有相关资料。', 'P2事件首次响应SLA标准', '[\"353283299259580429\", \"353283299259580422\"]', '[\"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580429\", \"documentId\": \"1\", \"rerankScore\": 0.9536277055740356, \"chunkContent\": \"## 评测事实边界\\n本数据集中的时间、阈值、资产和流程构成封闭测试事实。不同文档出现同一规则时，应以条件更具体的条款回答。例如“P2 首次响应目标为两小时”和“P2 超过两小时未恢复升级为 P1”描述的是不同管理节点，回答时必须保留“首次响应”或“未恢复”的条件。\\n资产编号和错误码是专有标识，不应翻译或改写。团队英文代号仅用于保持跨文档一致性，不代表需要使用英文回答。文档没有给出具体责任人的场景，应回答责任团队或当班经理，不得编造姓名和联系方式。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79393804}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 0.7421063184738159, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.82366025}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型表示知识库中无相关资料，未能提供P2事件首次响应目标的具体数值，未直接回答用户问题。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"上下文中仅在举例说明时提及“P2首次响应目标为两小时”，并明确强调首次响应目标与升级时限（两小时）不得混用，未直接提供P2首次响应目标的确切规则定义。模型如实回答无相关资料，未捏造或错误推断，完全符合上下文事实。\", \"contextRecallReason\": \"检索上下文的片段1中明确举例提到了‘P2 首次响应目标为两小时’，完全覆盖了标准答案中的关键信息。\", \"contextPrecisionReason\": \"两个片段均与问题高度相关。片段1通过示例直接提供了P2首次响应目标的具体数值线索，片段2则明确澄清了首次响应目标与升级时限的概念区别，两者均为回答该问题提供了关键且无噪声的上下文信息。\", \"answerCorrectnessReason\": \"模型回答表示知识库中无相关资料，未能提供标准答案中\'2小时\'这一关键信息，完全未回答问题。\"}', 13777, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (111, '20260903-211840-b62c97b8', 'aurora-md-011', '什么情况下三个生产区同时异常应按 P1 处理？', '根据事件分级规则，以下情况涉及三个生产区同时异常时，应按 **P1** 处理：\n\n1.  **同一原因影响三个生产区**：若故障由同一原因导致，且同时影响了三个生产区，直接按 P1 事件处理。\n2.  **三个生产区同时失去采集能力**：当三个生产区同时出现数据采集能力丧失的情况时，适用 P1 级别。\n\n此外，若初始定为 P2 的事件（如单个生产区核心能力降级等）在确认后超过两小时仍未恢复，也会升级为 P1。', '三个生产区同时异常按P1处理的条件', '[\"353283299259580422\", \"353285809898651652\", \"353285809898651650\", \"353283812000661507\"]', '[\"1\", \"4\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 4.407862663269043, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8537414}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 3.273512125015259, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8019357}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.273512125015259, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.958076}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": 0.7970792055130005, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.82459694}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答准确列出了三个生产区同时异常按P1处理的两种核心情况，直接且完整地回应了问题。但最后补充的P2升级P1的条件（如单个生产区核心能力降级）与问题中‘三个生产区同时异常’的前提无关，存在轻微冗余，故略微扣分。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 0.7, \"faithfulnessReason\": \"模型回答完全基于检索上下文。提到的\'同一原因影响三个生产区\'、\'三个生产区同时失去采集能力\'以及\'P2超过两小时未恢复升级为P1\'均在上下文（片段1、2、3）中有明确依据，无捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1）中明确提到‘P1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力’，完全覆盖了标准答案中的关键信息。\", \"contextPrecisionReason\": \"片段1高度相关，直接回答了问题；片段2和3包含部分相关答案（如同一原因影响三个生产区、E-17三个区域同时发生），但夹杂了大量无关的具体故障排查细节，且片段3与片段2完全重复；片段4基本与问题无关。整体噪声较多，相关文本占比约为一半。\", \"answerCorrectnessReason\": \"模型回答准确包含了标准答案的核心信息（三个生产区同时失去采集能力），但额外增加了‘同一原因影响’和‘P2超时升级’等标准答案中未提及的情况，存在信息冗余和潜在的幻觉。核心点正确，但细节有差异。\"}', 26680, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (112, '20260903-211840-b62c97b8', 'aurora-md-012', 'P2 超过多久未恢复要升级为 P1？', 'P2 故障超过 **两小时** 未恢复时，需升级为 P1。', 'P2故障升级P1超时时间标准', '[\"353285809898651650\", \"353283299259580422\", \"353283812000661504\"]', '[\"4\", \"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.8607614040374756, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.042784}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 2.7660741806030273, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8166374}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 1.9525941610336304, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.010441}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地回答了用户关于P2升级为P1的时间阈值问题，内容完全切题，无冗余或遗漏。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 0.8, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确指出P2故障超过两小时未恢复时需升级为P1，没有任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（特别是片段2）中明确指出了‘P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1’，与标准答案完全一致，覆盖了所有关键信息。\", \"contextPrecisionReason\": \"三个检索片段均包含了回答问题的核心信息（P2超过两小时未恢复升级为P1），但每个片段内部均夹杂了大量与问题无关的具体故障排查步骤、日常运维规范等冗余噪声，相关文本在整体上下文中占比较低。\", \"answerCorrectnessReason\": \"模型回答正确指出了核心时间条件\'两小时\'，但遗漏了标准答案中\'从确认故障开始计算\'这一时间起点的细节。整体核心正确，细节略有遗漏。\"}', 32699, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (113, '20260903-211840-b62c97b8', 'aurora-md-013', '事件队列触发 E-42 的阈值是多少？', '事件队列触发 E-42 告警的阈值是记录数超过 **50,000** 条。', '事件队列触发E-42阈值', '[\"353283299259580421\", \"353285809898651651\", \"353285809898651650\", \"353285880643977231\", \"353285880643977217\"]', '[\"1\", \"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 4.014589786529541, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.83204144}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 2.7504513263702393, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8628784}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.7504513263702393, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.543587}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977231\", \"documentId\": \"6\", \"rerankScore\": 1.3758598566055298, \"chunkContent\": \"﻿事件编号：INC-260816; 发生时间（CST）：2026-08-25 12:26; 严重级别：P2; 资产编号：AU-GW-002; 错误码：E-42; 解决时长（分钟）：49; 根本原因：事件消费进程停滞; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.83847696}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977217\", \"documentId\": \"6\", \"rerankScore\": 1.2848423719406128, \"chunkContent\": \"﻿事件编号：INC-260802; 发生时间（CST）：2026-08-07 14:20; 严重级别：P3; 资产编号：AU-CM-003; 错误码：E-42; 解决时长（分钟）：55; 根本原因：历史事件未及时归档; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8351712}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地回答了用户关于事件队列触发E-42阈值的问题，明确指出阈值为记录数超过50,000条，无冗余信息，完全切题。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文（片段1明确指出\'事件队列记录数超过 50,000 条时触发 E-42\'，片段2和3也提及\'超过五万条\'），准确回答了问题，不存在捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中片段1明确提到‘事件队列记录数超过 50,000 条时触发 E-42’，片段2和片段3也提及‘E-42 表示事件队列记录数超过五万条’，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"片段1、2、3包含了事件队列触发E-42的阈值信息（50,000条），但片段2和3包含了大量其他无关故障的排查内容且两者完全重复；片段4和片段5仅为E-42的历史工单记录，并未提及触发阈值，属于噪声。整体相关片段占比约为一半。\", \"answerCorrectnessReason\": \"语义完全一致，关键信息（记录数超过50,000条）准确无遗漏，增加的“告警”一词和排版格式不影响核心含义。\"}', 22706, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (114, '20260903-211840-b62c97b8', 'aurora-md-014', 'E-42 的恢复标准是什么？', 'E-42 的恢复标准是事件队列记录数低于 5,000 条。', 'E-42恢复标准', '[\"353283299259580421\", \"353285809898651651\"]', '[\"1\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 4.094696521759033, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.670353}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 1.7446985244750977, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79059666}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地给出了E-42的恢复标准，完全切题，无冗余或遗漏信息。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答直接引用了检索上下文片段1中关于E-42恢复标准的明确表述（\'恢复标准为低于 5,000 条\'），完全基于上下文得出，不存在捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确提到了E-42的恢复标准为事件队列记录数低于5,000条（或降到五千条以下），完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"检索上下文中包含大量与问题无关的噪声信息（如E-17、R-09、S-03等其他故障排查指南及通用流程），仅在片段1的一句话和片段2的第四章中提及了E-42的恢复与验证标准，相关文本占整体篇幅的比例很低。\", \"answerCorrectnessReason\": \"语义完全一致，\'事件队列记录数\'与\'事件队列深度\'同义，\'低于5,000条\'与\'降到5,000条以下\'含义相同，关键信息无遗漏。\"}', 25095, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (115, '20260903-211840-b62c97b8', 'aurora-md-015', '设备时钟偏差超过多少会触发 E-17？', '设备时钟偏差超过 **90 秒**会触发 E-17 告警。', '设备时钟偏差触发E-17阈值', '[\"353285809898651650\", \"353283299259580421\", \"353285880643977216\"]', '[\"4\", \"1\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.8553249835968018, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8497678}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 3.593842029571533, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8244462}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 0.7483082413673401, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8601502}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地给出了触发 E-17 的设备时钟偏差阈值（90秒），完全切题，没有无关或冗余内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文（片段1和片段2均明确指出设备时钟偏差超过90秒/九十秒会触发E-17），信息准确，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文中明确提到‘设备时钟偏差超过 90 秒时触发 E-17’以及‘E-17 表示设备时钟偏差超过九十秒’，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"片段1中仅第三章直接解答了E-17的触发阈值，其余章节（如E-42、R-09等其他故障排查）均为无关噪声；片段2中仅一条阈值相关，其余为噪声；片段3为E-17相关案例。整体上下文中约有一半内容与问题相关，存在较多无关的其他故障码和指标噪声。\", \"answerCorrectnessReason\": \"语义完全一致，关键信息（90秒、E-17）无遗漏，模型回答补充了\'告警\'一词，表述更自然且不影响核心含义。\"}', 23604, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (116, '20260903-211840-b62c97b8', 'aurora-md-016', '紧急变更最长应在多久内补齐记录？', '紧急变更最长应在**二十四小时**内补齐变更记录和回退验证。', '紧急变更记录补齐时限', '[\"353283299259580423\"]', '[\"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": 2.04427719116211, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7859063}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确地给出了\'二十四小时\'这一核心时间要求，完全切题，没有无关或冗余内容。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文中的‘并在二十四小时内补齐变更记录和回退验证’，准确回答了问题，不存在捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文明确提到“紧急变更...并在二十四小时内补齐变更记录和回退验证”，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"唯一的检索片段明确包含了紧急变更需在二十四小时内补齐记录的规定，直接且准确地回答了用户问题，所有片段均高度相关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，均明确指出紧急变更应在二十四小时内补齐变更记录和回退验证，关键信息无遗漏。\"}', 11032, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (117, '20260903-211840-b62c97b8', 'aurora-md-017', '临时配置最长可以保留多久？', '抱歉，关于临时配置最长可以保留多久，当前知识库中没有相关资料。', '临时配置最长保留时间', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": null, \"relevancyReason\": \"模型表示知识库中无相关资料并拒答，未能提供关于临时配置保留时长的任何具体信息，未实际回答用户问题。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型如实回答无相关资料，未捏造任何信息，完全符合上下文情况。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答表示未找到相关资料，完全未能提供标准答案中\'最长不超过七天\'和\'必须写明失效时间\'的关键信息，属于拒答或无信息输出。\"}', 8774, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (118, '20260903-211840-b62c97b8', 'aurora-md-018', '超过多少行的数据导出需要双人审批？', '超过 10,000 行的数据导出需要双人审批。', '数据导出双人审批行数阈值', '[\"353283917827145741\", \"353283917827145733\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 1.993428111076355, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7828362}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145733\", \"documentId\": \"3\", \"rerankScore\": 1.0378776788711548, \"chunkContent\": \"## **数据导出与共享**\\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.84465003}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确且完整地回答了用户关于数据导出双人审批行数限制的问题，给出了具体数值，没有任何冗余或无关内容。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 0.8, \"faithfulnessReason\": \"模型回答完全基于检索上下文。片段1和片段2均明确指出超过10,000行（一万行）的数据导出需要双人审批，回答准确无误，无捏造或矛盾内容。\", \"contextRecallReason\": \"检索上下文（片段1）完全覆盖了标准答案中的所有关键信息，明确指出了超过10,000行的数据导出需要Data Steward和值班经理双人审批。\", \"contextPrecisionReason\": \"两个片段均准确包含了回答问题的核心信息（超过1万行/10,000行需双人审批）。片段2完全围绕数据导出，高度相关；片段1虽包含答案，但夹杂了角色权限、数据保留和会话要求等无关噪声。整体大部分内容相关，存在少量冗余。\", \"answerCorrectnessReason\": \"模型回答准确提供了核心的行数阈值（10,000行），完美切中问题，但相比标准答案遗漏了具体的审批角色（Data Steward 和值班经理）这一细节信息。\"}', 12148, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (119, '20260903-211840-b62c97b8', 'aurora-txt-001', '每日开班检查从什么时间开始？', '每日开班检查从 **07:45 CST** 开始。', '每日开班检查开始时间', '[\"353283812000661504\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 3.632851839065552, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.75575167}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地给出了每日开班检查的开始时间，完全切题，无任何冗余或无关内容。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答的\'07:45 CST\'完全基于检索上下文中\'每日开班\'和\'开班前置检查\'部分的明确表述，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确提到\'操作员在 07:45 CST 检查\'以及\'07:45 开始检查时\'，完全覆盖了标准答案中每日开班检查从 07:45 CST 开始的关键信息。\", \"contextPrecisionReason\": \"上下文共6个编号片段，仅片段1（每日开班）和片段6（开班前置检查）提及07:45的检查时间，与问题相关；其余4个片段（环境处置、维护窗口、升级、交接）均为无关噪声。相关片段占比约33%，大部分片段与问题无关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息无遗漏，仅增加了Markdown加粗格式，不影响核心含义。\"}', 8573, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (120, '20260903-211840-b62c97b8', 'aurora-txt-002', '开班时需要依次记录哪些信息？', '抱歉，关于开班时需要依次记录哪些信息，当前知识库中没有相关资料。', '开班信息记录内容及顺序', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": null, \"relevancyReason\": \"模型表示知识库中无相关资料并直接拒答，未能提供用户所需的开班记录信息，未实际回答用户问题。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型如实反馈无相关资料，未捏造任何信息，完全符合上下文情况。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答表示知识库中无相关资料，未能提供标准答案中要求的任何具体记录信息，属于完全未回答，与标准答案语义完全不一致。\"}', 11779, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (121, '20260903-211840-b62c97b8', 'aurora-txt-003', 'HG-220 连续丢失三次心跳时能否直接重启？', '**不能直接重启。**\n\n当 HG-220 连续丢失三次心跳时，严禁直接重启网关。正确的处置流程如下：\n\n1.  **初步检查**：先确认该区域交换机是否处于批准的维护窗口，并从平台查看最后一次成功上报时间。\n2.  **联系团队**：若链路正常，应联系 Edge Platform 团队核对采集进程。\n3.  **禁止操作**：未经 Edge Platform 团队确认，不得重启网关，也不得清空网关本地缓存。\n4.  **恢复验证**：故障恢复后，需连续观察十五分钟，确保至少收到十五次正常心跳，方可关闭通信告警。', 'HG-220 心跳丢失重启策略', '[\"353283812000661504\", \"353283812000661505\", \"353283299259580421\"]', '[\"2\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 3.0944817066192627, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.223179}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 2.709446907043457, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7991407}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 0.6625271439552307, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8043288}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且明确地回答了核心问题（\'不能直接重启\'），并提供了完整的相关处置流程。补充的初步检查、联系团队、禁止操作和恢复验证步骤均与心跳丢失场景直接相关，属于操作类问题的必要上下文，无冗余或跑题内容。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确得出不能直接重启的结论，且列出的四步处置流程与上下文片段2中的规定完全一致，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文完全覆盖了标准答案的所有关键信息。片段1和片段2均明确指出连续丢失三次心跳时不得直接重启网关，且片段2详细说明了需要先检查维护窗口和链路情况，并联系 Edge Platform 团队。\", \"contextPrecisionReason\": \"三个片段均包含回答问题的核心内容（不得直接重启），但各片段内大部分章节（如温湿度处置、维护窗口、缓存巡检等）与问题无关，相关段落占比约20%，噪声较多。\", \"answerCorrectnessReason\": \"模型回答明确指出不能直接重启，并详细列出了检查维护窗口、确认链路情况以及联系 Edge Platform 团队等步骤，完全涵盖了标准答案的所有关键信息，语义完全一致且无遗漏。\"}', 18617, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (122, '20260903-211840-b62c97b8', 'aurora-txt-004', '心跳恢复后应观察多久？', '心跳恢复（自主循环恢复，ROSC）后，患者仍处于极不稳定的状态，需要进入重症监护室（ICU）进行严密监测。观察时间并非固定的单一时长，而是一个持续的过程，通常分为以下几个关键阶段：\n\n1.  **急性期密切监测（最初24-72小时）**\n    这是最关键的时期。绝大多数再停搏、血流动力学不稳定或神经系统恶化的情况发生在这一阶段。因此，患者通常需要至少**24至72小时**的连续重症监护，包括对心率、血压、血氧、体温及神经功能的实时监测。\n\n2.  **目标温度管理期间（如有实施）**\n    如果患者接受了目标温度管理（TTM，即亚低温治疗），通常在恢复自主循环后尽快启动，并维持24小时左右，随后缓慢复温。整个控温和复温过程可能需要**数天时间**，期间需持续观察。\n\n3.  **神经系统预后评估（72小时后）**\n    为了准确评估脑损伤程度和神经功能预后，通常建议在停止镇静药物且体温恢复正常后，至少观察**72小时**以上。过早判断预后可能导致误判。\n\n4.  **长期观察与康复**\n    即使度过了急性期，患者仍可能面临心律失常、心肌损伤或多器官功能障碍的风险。因此，出院前需进行全面的心脏评估（如超声心动图、冠脉造影等），并根据具体病因决定后续的随访计划。\n\n**总结：**\n心跳恢复后，**至少需要24-72小时的重症监护观察**，以确保生命体征稳定并评估神经功能。具体的观察时长和后续治疗方案应由医疗团队根据患者的具体病因、身体状况及恢复情况个体化决定。', '心跳恢复后观察时间', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 0.0, \"contextRecall\": null, \"relevancyReason\": \"模型回答直接且完整地回答了用户问题，明确给出了心跳恢复后至少24-72小时的核心观察时间，并详细补充了不同阶段（如温度管理、神经评估、长期康复）的观察需求，内容高度切题，无无关信息。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型回答中的所有医学细节和时间节点均无法由上下文支撑，属于完全脱离上下文的捏造。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答将问题理解为临床心肺复苏后患者的长期ICU重症监护（24-72小时），而标准答案指的是特定场景下确认心跳恢复的短期观察（连续15分钟，至少15次正常心跳）。两者场景完全错位，核心关键信息（15分钟、15次心跳）完全遗漏且语义不一致。\"}', 35472, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (123, '20260903-211840-b62c97b8', 'aurora-txt-005', '传感器校准过期时应如何处理环境异常数据？', '当传感器校准过期时，处理环境异常数据的步骤如下：\n\n1.  **标记数据**：先将相关数据标记为“待确认”。\n2.  **通知复核**：通知 Facilities 团队进行复核。\n3.  **避免误操作**：不要直接依据该数值执行停线操作。', '传感器校准过期环境异常数据处理方法', '[\"353283812000661505\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 2.200997829437256, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 20.073254}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地针对用户问题提供了处理环境异常数据的具体步骤，内容切题、准确且无无关冗余信息。\", \"contextPrecision\": 0.25, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文中的“温度和湿度异常处置”部分，准确提取了传感器校准过期时的三个处理步骤（标记数据为“待确认”、通知 Facilities 团队复核、不直接依据该数值停线），无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文明确提到‘校准过期时先将数据标记为待确认，通知 Facilities 团队复核，不直接依据该数值停线’，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"上下文共包含4个片段，仅片段2（温度和湿度异常处置）详细说明了传感器校准过期时环境异常数据的处理方法，其余3个片段（网关心跳、缓存队列、维护窗口）均与问题无关，相关片段占比约为25%。\", \"answerCorrectnessReason\": \"模型回答完整包含了标准答案中的所有关键信息（标记数据为待确认、通知Facilities团队复核、不能直接停线），语义完全一致，仅采用了分点表述的格式。\"}', 37611, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (124, '20260903-211840-b62c97b8', 'aurora-txt-006', '环境指标恢复后还要观察多久？', '抱歉，关于环境指标恢复后具体需要观察多久，当前知识库中没有相关资料。', '环境指标恢复后观察时长', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": null, \"relevancyReason\": \"模型未能回答用户问题，直接以知识库无相关资料为由拒答，未提供任何关于观察时长的实质性信息。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型准确指出无相关资料，未产生任何捏造或幻觉，回答完全符合实际情况。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答表示知识库中无相关资料，未能提供标准答案中明确的\'二十分钟\'这一关键信息，属于完全未回答，语义不一致。\"}', 28798, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (125, '20260903-211840-b62c97b8', 'aurora-txt-007', '维护窗口开始前需要核对哪些项目？', '在维护窗口开始前，需要核对以下项目：\n\n1. **审批单**：确认变更已获得批准。\n2. **影响范围**：明确变更涉及的业务或系统范围。\n3. **回退包**：确保回退方案及所需资源已准备就绪。\n4. **联系人**：确认相关责任人和紧急联系渠道。\n5. **操作人**：核实执行变更的具体人员。\n\n此外，需在窗口开始前十五分钟（即 01:45 前）完成上述确认工作，并暂停非关键批任务。', '维护窗口开始前核对项目', '[\"353283299259580423\", \"353283812000661505\"]', '[\"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": 2.9170384407043457, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8316152}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 1.2998489141464231, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78975725}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地列出了维护窗口开始前需要核对的具体项目（审批单、影响范围、回退包、联系人、操作人），并补充了相关的时间要求和前置操作，完全切题，准确回应了问题核心，无冗余或无关内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"模型回答中列出的所有核对项目（审批单、影响范围、回退包、联系人、操作人）以及时间节点（01:45前/窗口开始前十五分钟）均能在检索上下文（片段1和片段2）中找到明确依据，回答完全由上下文支撑，无捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"片段2第10节\'维护窗口操作清单\'中明确提到\'01:45 前确认审批单、影响范围、回退包和联系人\'，完整覆盖了标准答案中的四个关键信息项：审批单、影响范围、回退包和联系人。\", \"contextPrecisionReason\": \"两个片段均包含维护窗口开始前需核对的项目（如审批单、回退包、操作人、影响范围等），但也包含大量无关内容（如紧急变更原则、网关心跳异常、温湿度异常处置、缓存巡检等），噪声较多，相关文本占比约一半。\", \"answerCorrectnessReason\": \"模型回答完整覆盖了标准答案中的四个关键项目（审批单、影响范围、回退包、联系人），关键信息无遗漏。额外补充的“操作人”及时间等细节属于合理扩展，核心正确但细节略有差异。\"}', 12631, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (126, '20260903-211840-b62c97b8', 'aurora-txt-008', '维护过程中能否同时修改两个生产区的关键配置？', '抱歉，关于维护过程中能否同时修改两个生产区的关键配置，当前知识库中没有相关资料。', '维护期间同时修改两个生产区关键配置规则', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": null, \"relevancyReason\": \"模型表示知识库中无相关资料并直接拒答，未能提供关于能否同时修改配置的实质性答案，未解决用户疑问。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型如实回答知识库中无相关资料，未进行任何捏造或猜测，完全符合上下文情况。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"标准答案明确给出了\'不能\'的结论，而模型回答表示知识库中无相关资料，未能回答该问题，属于拒答，与标准答案语义完全不一致。\"}', 35518, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (127, '20260903-211840-b62c97b8', 'aurora-txt-009', '如果03:20仍未完成核心验证，应怎么做？', '若 03:20 仍未完成核心验证，应执行回退操作，不得擅自延长维护窗口。', '03:20未完成核心验证应对措施', '[\"353283812000661505\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 3.3645126819610596, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 15.424199}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地回应了用户问题，明确指出了在指定时间未完成核心验证时应采取的具体措施（执行回退操作、不延长维护窗口），无冗余内容，完全切题。\", \"contextPrecision\": 0.25, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文中的‘维护窗口操作清单’部分，准确无误地提取了03:20仍未完成核心验证时的处置措施，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段10中明确提到\'若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口\'，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"检索上下文包含4个独立的操作规程片段（网关心跳、温湿度、缓存队列、维护窗口），其中仅有\'维护窗口操作清单\'片段回答了03:20未完成核心验证的应对措施，其余3个片段均为无关噪声，相关比例约为25%。\", \"answerCorrectnessReason\": \"语义完全一致，模型回答完整包含了标准答案的所有关键信息（执行回退、不得擅自延长维护窗口），仅增加了“操作”二字及重复了问题前提，核心含义无任何差异或遗漏。\"}', 12325, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (128, '20260903-211840-b62c97b8', 'aurora-txt-010', '配置变更后必须检查哪四项结果？', '配置变更完成后，必须检查以下四项结果：\n\n1. **网关心跳**\n2. **事件队列**\n3. **规则计算**\n4. **质量抽样**\n\n任一项检查结果失败均视为验证不通过。', '配置变更后检查项', '[\"353283812000661506\", \"353283917827145734\"]', '[\"2\", \"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 4.011806488037109, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8194679}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": 1.9533183574676511, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81161475}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地列出了配置变更后必须检查的四项结果，条理清晰，没有包含任何无关内容，完全切题。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文[片段1]的内容，准确提取了网关心跳、事件队列、规则计算和质量抽样四项结果，并且关于验证不通过的描述也与原文完全一致，无任何捏造、夸大或矛盾之处。\", \"contextRecallReason\": \"检索上下文完整包含了标准答案中提到的四项检查结果（网关心跳、事件队列、规则计算和质量抽样），信息完全覆盖。\", \"contextPrecisionReason\": \"片段1中的第11节直接回答了配置变更后需要检查的四项结果，但片段1的其余部分（12至15节）以及整个片段2（审计记录要求）均与用户问题无关，噪声较多，相关片段占比较低。\", \"answerCorrectnessReason\": \"模型回答准确列出了标准答案中要求的四项检查结果（网关心跳、事件队列、规则计算、质量抽样），语义完全一致，关键信息无遗漏，补充说明不影响核心语义。\"}', 13729, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (129, '20260903-211840-b62c97b8', 'aurora-txt-011', '连续两次回退失败后如何处置？', '连续两次回退失败时，应停止操作，隔离受影响设备，并升级给当班经理。', '连续两次回退失败处理方法', '[\"353283812000661506\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 2.926143169403076, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 18.347303}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地针对用户问题给出了具体的处置步骤（停止操作、隔离设备、升级给当班经理），内容高度相关，无冗余或无关信息，完全切题。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文中的\'连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理\'得出，表述准确，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文完全覆盖了标准答案中的所有关键信息，明确指出连续两次回退失败时应停止操作、隔离受影响设备并升级给当班经理。\", \"contextPrecisionReason\": \"检索上下文仅在\'11. 变更验证与回退\'部分包含问题答案，后续的12至15部分（事件通知、工单记录、交接模板、日终检查）均为无关噪声，相关文本占比约20%。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，准确包含了停止操作、隔离受影响设备以及升级给当班经理这三个关键处置步骤，无任何遗漏或错误。\"}', 35084, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (130, '20260903-211840-b62c97b8', 'aurora-txt-012', 'P1 确认后多久内通知当班经理和 Blue Heron？', 'P1 事件确认后，需在**五分钟内**通知当班经理和 Blue Heron。', 'P1确认后通知当班经理和Blue Heron的时效要求', '[\"353283812000661506\", \"353283812000661504\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 2.8506991863250732, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7941145}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 1.293260097503662, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 23.873915}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确且完整地回答了用户的问题，明确指出了时间为\'五分钟内\'，没有任何冗余或无关内容。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文[片段1]中‘P1 事件确认后五分钟内通知当班经理和 Blue Heron’的描述，准确无误，无捏造或矛盾内容。\", \"contextRecallReason\": \"检索上下文片段1中明确提到‘P1 事件确认后五分钟内通知当班经理和 Blue Heron’，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"片段1共5个小节，仅第12节直接回答了问题（P1确认后五分钟内通知当班经理和Blue Heron），其余4节（变更验证、工单记录、交接模板、日终检查）均无关。片段2共6个小节，仅第4节部分相关（提及P1与Blue Heron的通知关系），其余5节（开班、环境处置、维护窗口、交接、开班前置检查）均无关。总计约11个小节中仅1-2个相关，相关占比约15%-20%，噪声较多，但关键答案确实存在。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，准确回答了\'五分钟内\'这一关键时间信息，且通知对象完全匹配，无任何遗漏或错误。\"}', 16180, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (131, '20260903-211840-b62c97b8', 'aurora-txt-013', 'P2 事件应多久更新一次进展？', 'P2 事件应每三十分钟更新一次进展。', 'P2事件进展更新频率', '[\"353283812000661506\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 0.88388592004776, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7336789}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确且完整地回答了用户关于P2事件进展更新频率的问题，没有任何冗余或无关内容。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文中\'12. 事件通知与升级\'的描述，准确指出P2事件应每三十分钟更新一次进展，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文明确提到\'P2 事件由责任团队处理，每三十分钟更新一次进展\'，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"检索上下文中仅第12节直接回答了P2事件进展更新频率，第14节弱相关，其余大部分内容（如变更验证、工单记录、日终检查）均与问题无关，噪声较多。\", \"answerCorrectnessReason\": \"模型回答与标准答案完全一致，语义和关键信息均无遗漏。\"}', 24842, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (132, '20260903-211840-b62c97b8', 'aurora-txt-014', 'P3 同类事件满足什么条件要发起问题复盘？', 'P3 同类事件在**七天内出现三次**时，应发起问题复盘。', 'P3同类事件问题复盘发起条件', '[\"353283812000661506\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 1.545706033706665, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.053936}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地给出了P3同类事件发起问题复盘的具体条件（七天内出现三次），完全切题，无冗余或遗漏内容。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文片段1中第12条的规定（\'同类事件七天内出现三次时应发起问题复盘\'），准确提取了条件，无捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文在\'事件通知与升级\'部分明确指出\'P3 事件...同类事件七天内出现三次时应发起问题复盘\'，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"上下文共包含5个主要段落（11至15），其中仅段落12明确回答了P3同类事件发起问题复盘的条件（七天内出现三次），其余4个段落（变更验证、工单记录、交接模板、日终检查）均与用户问题无关，相关片段占比约20%，噪声较多。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息（P3同类事件、七天内、出现三次、发起问题复盘）均无遗漏，仅存在加粗格式和微小的语序差异，不影响核心含义。\"}', 27054, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (133, '20260903-211840-b62c97b8', 'aurora-txt-015', '工单必须记录哪些核心字段？', '抱歉，关于工单必须记录的核心字段，当前知识库中没有相关资料。', '工单核心必填字段', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": null, \"relevancyReason\": \"模型直接拒答，表示知识库中无相关资料，未能提供工单必须记录的核心字段信息，没有回答用户问题。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型正确识别并如实回答无相关资料，未产生任何捏造或幻觉，完全符合无捏造的标准。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答表示知识库中无相关资料，未提供任何核心字段信息，与标准答案完全不一致。\"}', 11338, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (134, '20260903-211840-b62c97b8', 'aurora-txt-016', '交接中的临时配置必须标注什么？', '交接中的临时配置必须标注**负责人**和**失效时间**。', '交接临时配置标注要求', '[\"353283812000661506\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 2.596773147583008, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79475236}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地回应了用户问题，指出了交接中临时配置需要标注的核心要素（负责人和失效时间），没有冗余或无关内容，完全切题。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文第14节\'交接模板\'中的明确表述（\'临时配置必须标注负责人和失效时间\'），准确回答了问题，不存在捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确提到\'临时配置必须标注负责人和失效时间\'，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"5个片段中，仅片段14（交接模板）直接回答了问题——\'临时配置必须标注负责人和失效时间\'，高度相关；片段15（日终检查）提及\'检查临时配置是否即将到期\'，弱相关；片段11、12、13分别讲变更验证、事件通知、工单记录，与问题无关。相关片段占比约2/5，属于噪声较多的情况。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，准确提取了\'负责人\'和\'失效时间\'两个关键信息，仅增加了Markdown加粗格式，不影响核心含义。\"}', 28539, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (135, '20260903-211840-b62c97b8', 'aurora-txt-017', '事件队列在归档前能否清空？', '**不能。**\n\n在事件归档前严禁清空队列。相关操作规范明确指出：\n\n1.  **通用安全原则**：禁止在未归档前清空队列。\n2.  **E-42 事件队列积压处置**：明确禁止直接清空队列。正确的处理流程是先归档超过三十天并已完成质量校验的记录，归档成功后再重启 Queue Worker，并验证队列深度降至五千条以下。\n3.  **网关心跳异常处置**：未经 Edge Platform 团队确认，不得清空网关本地缓存。', '事件队列归档前清空机制', '[\"353285809898651651\", \"353283812000661505\"]', '[\"4\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 1.6439974308013916, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79275256}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 0.942693531513214, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.076571}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且明确地回答了用户问题（不能），并详细列出了相关的操作规范和正确处理流程作为依据，完全切题，准确回应了问题核心，无无关或冗余内容。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确引用了通用安全原则和E-42事件队列积压处置中关于禁止在未归档前清空队列的规定，无捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段1中明确规定了“禁止在未归档前清空队列”，完全覆盖了标准答案中“不能”以及“明确禁止在未归档前清空事件队列”的关键信息。\", \"contextPrecisionReason\": \"检索上下文是一份综合性的故障排查指南，包含了大量与问题无关的故障处理流程（如时钟偏差、机器人联锁、温度传感器、网络丢包等）。仅有“安全原则”、“E-42 事件队列积压”和“缓存与队列巡检”部分直接涉及事件队列及归档前清空的相关规则，相关片段占比约20%-30%，大部分内容为无关噪声。\", \"answerCorrectnessReason\": \"模型回答明确给出了“不能”的结论，并指出操作规范（即运行手册）禁止在未归档前清空事件队列，与标准答案核心语义完全一致，且提供了更详细的规范条款作为支撑，无信息遗漏或冲突。\"}', 31745, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (136, '20260903-211840-b62c97b8', 'aurora-txt-018', 'P1 事件恢复后多久确定复盘负责人？', 'P1 事件在恢复后**二十四小时内**确定复盘负责人。', 'P1事件恢复后复盘负责人确定时效', '[\"353283812000661507\", \"353283812000661506\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": 2.769543409347534, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7913629}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 1.5358216762542725, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 18.145012}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地指出了P1事件恢复后确定复盘负责人的时间（二十四小时内），完全切题，无任何冗余或遗漏内容。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文[片段1]中的明确规定（\'P1 事件在恢复后二十四小时内确定复盘负责人\'），准确无误，不存在捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1的第17条）中明确提到\'P1 事件在恢复后二十四小时内确定复盘负责人\'，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"检索上下文中仅片段1的“17. 证据与复盘”直接回答了问题（恢复后二十四小时内），片段2的“15. 日终检查”仅弱相关提及复盘负责人，其余绝大部分条款（如异常操作、平台依赖、降级运行、变更验证等）均与问题无关，噪声比例较高。\", \"answerCorrectnessReason\": \"语义完全一致，关键信息无遗漏，仅存在微小的表述和格式差异（如添加\'在\'字和加粗），不影响核心含义。\"}', 12786, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (137, '20260903-211840-b62c97b8', 'aurora-docx-001', 'Operator 角色可以执行哪些操作？', '抱歉，关于 Operator 角色可以执行的具体操作，当前知识库中没有相关资料。', 'Operator角色可执行操作说明', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.0, \"faithfulness\": 1.0, \"contextRecall\": null, \"relevancyReason\": \"模型以知识库无相关资料为由拒答，未能提供Operator角色可执行的具体操作，未直接回答用户问题。\", \"contextPrecision\": null, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"检索上下文为空，模型正确指出无相关资料并如实拒答，未捏造任何信息，完全符合上下文情况。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答表示未找到相关资料，完全没有提及标准答案中Operator角色的任何操作权限（查看状态、创建工单、不能修改阈值），属于完全未回答。\"}', 10727, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (138, '20260903-211840-b62c97b8', 'aurora-docx-002', 'Engineer 在什么条件下可以修改设备配置？', 'Engineer 修改设备配置需满足以下条件：\n\n1.  **时间窗口**：必须在已批准的维护窗口内进行。\n2.  **身份验证**：执行配置修改前必须重新验证身份。\n3.  **变更复核**：关键变更需由另一名工程师进行复核。', 'Engineer修改设备配置条件', '[\"353283917827145741\", \"353283917827145730\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 2.6739563941955566, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7573348}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145730\", \"documentId\": \"3\", \"rerankScore\": 1.8556060791015625, \"chunkContent\": \"## **角色权限矩阵**\\n操作员可查看实时状态、确认告警和创建工单，不得修改告警阈值、设备配置或数据保留策略。工程师可在已批准的维护窗口内修改设备配置，但操作前必须重新验证身份，并由另一名工程师复核关键变更。审计员只有只读权限，可检查权限、审批和操作证据。数据管理员负责大批量导出审批和保留策略执行，不得代替资源负责人批准设备变更。\\n任何人不得使用他人账号执行操作，也不得为方便值班建立共享账号。发现共享账号后应立即停用，保留审计记录，并由所属团队重新申请实名权限。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.349673}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地回应了用户问题，清晰列出了Engineer修改设备配置所需满足的具体条件，无冗余或无关内容，完全切题。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 0.5, \"faithfulnessReason\": \"模型回答中的三个条件（已批准的维护窗口、重新验证身份、另一名工程师复核关键变更）均完全基于检索上下文（片段1和片段2）得出，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1和片段2）中明确指出 Engineer（工程师）可以在已批准的维护窗口内修改设备配置，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"两个检索片段均直接且准确地回答了 Engineer 修改设备配置的条件（包括已批准的维护窗口、重新验证身份和另一名工程师复核），但片段内也包含较多关于其他角色权限及数据保留策略的冗余文本。\", \"answerCorrectnessReason\": \"模型回答正确包含了核心条件（已批准的维护窗口），但额外增加了标准答案中未提及的\'身份验证\'和\'变更复核\'条件，存在信息幻觉，且与标准答案中\'只能\'的排他性语义相冲突。\"}', 32257, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (139, '20260903-211840-b62c97b8', 'aurora-docx-003', 'Auditor 可以导出多久范围内的审计记录？', 'Auditor 可以导出最近 **90 天**的审计记录。', 'Auditor审计记录导出时间范围', '[\"353283917827145741\", \"353283917827145733\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 1.772342562675476, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79307353}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145733\", \"documentId\": \"3\", \"rerankScore\": 0.8021724224090576, \"chunkContent\": \"## **数据导出与共享**\\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7879888}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且明确地给出了审计记录导出的时间范围（90天），完全切题，无冗余内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"模型回答完全基于检索上下文片段1中‘Auditor 只有只读权限，可以导出最近 90 天的审计记录’的明确表述，准确无误，无捏造或矛盾内容。\", \"contextRecallReason\": \"检索上下文（片段1）中明确提到“Auditor 只有只读权限，可以导出最近 90 天的审计记录”，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"片段1包含了Auditor导出审计记录时间范围（最近90天）的直接答案，但也包含大量其他角色权限和系统规则的噪声；片段2主要讲述通用的数据导出审批与共享规则，未提及Auditor的具体导出时间范围，属于无关噪声。整体来看约一半的片段相关，噪声较多。\", \"answerCorrectnessReason\": \"模型回答准确回答了问题的核心信息（最近90天），仅遗漏了标准答案中关于权限的补充说明（只有只读权限），核心语义高度一致。\"}', 9711, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (140, '20260903-211840-b62c97b8', 'aurora-docx-004', '原始传感器数据保留多久？', '原始传感器数据保留 30 天。', '原始传感器数据保留时间', '[\"353283917827145741\", \"353283299259580424\"]', '[\"3\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 4.0948615074157715, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79292846}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": 1.0343904495239258, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8105468}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确且完整地回答了用户关于原始传感器数据保留时间的问题，没有任何冗余或无关内容，完全切题。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文片段1中的明确表述（\'原始传感器数据保留 30 天\'），无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段1中明确指出‘原始传感器数据保留 30 天’，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"仅片段1中的“数据保留”小节直接回答了问题，片段1的其他小节及整个片段2均涉及角色权限、导出审批、会话要求和数据质量等无关内容，大部分内容与问题无关，噪声较多。\", \"answerCorrectnessReason\": \"模型回答与标准答案完全一致，语义和关键信息无任何遗漏或差异。\"}', 9768, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (141, '20260903-211840-b62c97b8', 'aurora-docx-005', '小时聚合数据保留多久？', '小时聚合数据保留 18 个月。', '小时聚合数据保留时间', '[\"353283917827145741\", \"353283812000661508\"]', '[\"3\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 3.912236452102661, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77994275}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": 1.1976330280303955, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.8699}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、完整且准确地回应了用户关于小时聚合数据保留时间的问题，没有任何无关或冗余内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文片段1中的明确表述（\'小时聚合数据保留 18 个月\'），准确无误，不存在捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段1中明确提到了‘小时聚合数据保留 18 个月’，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"片段1中的“数据保留”部分直接回答了小时聚合数据的保留时间，高度相关；但片段1的其他部分（角色权限、会话要求等）以及整个片段2（事件管理、临时措施等）均与问题无关，仅在片段2的导出操作中提及了该名词而未涉及保留时间。整体来看，相关片段与噪声片段比例约为一半。\", \"answerCorrectnessReason\": \"模型回答与标准答案完全一致，语义和关键信息均无任何遗漏或差异。\"}', 9167, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (142, '20260903-211840-b62c97b8', 'aurora-docx-006', '审计日志保留多久？', '审计日志的保留期限为 **365天**（即一年）。在此期间，任何人不得删除、覆盖或修改原始记录。', '审计日志保留时长', '[\"353283917827145734\", \"353283917827145741\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": 4.349411487579346, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8160955}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 2.9587271213531494, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7894665}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地给出了审计日志的保留期限（365天），补充的防篡改要求属于高度相关的背景信息，完全切题且无冗余。\", \"contextPrecision\": 0.4, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答中的365天保留期限以及不得删除、覆盖或修改原始记录的规定均在上下文片段1和片段2中有明确依据，\'即一年\'为合理的常识解释，完全由上下文支撑，无捏造内容。\", \"contextRecallReason\": \"检索上下文在片段1和片段2中均明确指出了“审计日志保留 365 天”（或“三百六十五天”），完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"两个片段中各有约一句直接回答了审计日志保留时长（365天），属于高度相关内容；片段1中审计记录内容描述和片段2中Auditor角色提及属于弱相关；但两个片段中大量内容（权限复核、角色权限详情、导出审批、会话要求等）与问题无关，噪声占比较高。整体相关比例约40%。\", \"answerCorrectnessReason\": \"模型回答准确包含了标准答案的核心信息\'365天\'，并补充了相关的管理要求，语义完全一致且关键信息无遗漏。\"}', 7057, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (143, '20260903-211840-b62c97b8', 'aurora-docx-007', '大批量数据导出需要哪些人审批？', '大批量数据导出（超过一万行）需要**数据管理员**和**值班经理**进行双人审批。', '大批量数据导出审批人员', '[\"353283917827145730\", \"353283917827145733\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145730\", \"documentId\": \"3\", \"rerankScore\": 2.084747791290283, \"chunkContent\": \"## **角色权限矩阵**\\n操作员可查看实时状态、确认告警和创建工单，不得修改告警阈值、设备配置或数据保留策略。工程师可在已批准的维护窗口内修改设备配置，但操作前必须重新验证身份，并由另一名工程师复核关键变更。审计员只有只读权限，可检查权限、审批和操作证据。数据管理员负责大批量导出审批和保留策略执行，不得代替资源负责人批准设备变更。\\n任何人不得使用他人账号执行操作，也不得为方便值班建立共享账号。发现共享账号后应立即停用，保留审计记录，并由所属团队重新申请实名权限。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.74796873}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145733\", \"documentId\": \"3\", \"rerankScore\": 1.685832381248474, \"chunkContent\": \"## **数据导出与共享**\\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.86932206}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地指出了大批量数据导出所需的审批人员（数据管理员和值班经理），并准确回应了问题核心，无无关或冗余内容。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确指出了大批量数据导出（超过一万行）需要数据管理员和值班经理双人审批，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文明确提到‘超过一万行的数据导出需要数据管理员和值班经理双人审批’，其中‘数据管理员’对应‘Data Steward’，‘一万行’对应‘10,000行’，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"两个片段均直接包含了回答问题所需的关键信息（数据管理员和值班经理负责审批），但片段1中关于其他角色权限、共享账号的规定，以及片段2中关于导出申请细节、文件保存与删除的规定属于弱相关或冗余信息。整体大部分相关，少量冗余。\", \"answerCorrectnessReason\": \"语义完全一致，模型将\'Data Steward\'准确翻译为\'数据管理员\'，且触发条件（超过一万行/10,000行）、审批人（数据管理员/Data Steward和值班经理）及审批方式（双人审批）等关键信息均无遗漏。\"}', 10022, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (144, '20260903-211840-b62c97b8', 'aurora-docx-008', '工单中禁止粘贴哪些敏感内容？', '在工单中禁止粘贴以下敏感内容：\n\n*   **真实密码**\n*   **访问令牌**\n*   **个人身份信息**', '工单禁止粘贴敏感内容', '[\"353283917827145735\", \"353283917827145741\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145735\", \"documentId\": \"3\", \"rerankScore\": 0.633994996547699, \"chunkContent\": \"## **敏感信息事件处置**\\n发现真实密码或令牌进入工单后，应立即限制工单访问、通知安全管理员、撤销相关凭据并记录处置过程。发现个人身份信息时，应停止继续传播，确认下载和转发范围，并按数据事件流程评估影响。\\n处置完成不代表事件关闭。安全管理员应验证旧凭据已失效、替换凭据已安全分发、缓存和导出副本已清理，并在工单中保留不含敏感值的验证结论。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.80122447}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 0.6105232238769531, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 19.231651}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地列出了工单中禁止粘贴的敏感内容（真实密码、访问令牌、个人身份信息），完全切题，无冗余或遗漏。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文（片段2）中的明确规定，准确列出了禁止在工单中粘贴的三项敏感内容（真实密码、访问令牌、个人身份信息），无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段2中明确包含原句\'禁止在工单中粘贴真实密码、访问令牌或个人身份信息\'，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"两个片段均与问题高度相关。片段2直接明确规定了禁止在工单中粘贴真实密码、访问令牌或个人身份信息；片段1则详细说明了这些敏感信息进入工单后的事件处置流程，提供了完整的相关上下文，无无关噪声。\", \"answerCorrectnessReason\": \"模型回答与标准答案的关键信息完全一致，均准确列出了禁止粘贴的三项敏感内容（真实密码、访问令牌、个人身份信息），仅排版形式不同，语义无差异。\"}', 17389, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (145, '20260903-211840-b62c97b8', 'aurora-docx-009', '会话连续多久无操作后自动失效？', '会话在连续 **20 分钟** 无操作后会自动失效。', '会话无操作超时时间', '[\"353283917827145732\", \"353283917827145741\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145732\", \"documentId\": \"3\", \"rerankScore\": 0.9467755556106568, \"chunkContent\": \"## **认证与会话安全**\\n连续二十分钟无操作后会话自动失效。工程师执行配置修改、导出敏感数据或切换设备控制状态前必须重新验证身份。连续五次认证失败时账号锁定三十分钟，并通知安全管理员检查来源。\\n维护终端离开受控区域后不得保持登录状态。操作完成后应主动退出，不能只关闭浏览器窗口。浏览器不得保存园区系统密码，下载的临时文件应在任务完成后按审批要求清理。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8048209}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 0.8723539113998413, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7475316}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地给出了会话无操作自动失效的具体时间，完全切题，无任何冗余信息。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答准确提取了检索上下文中的信息，明确指出会话在连续20分钟无操作后自动失效，完全由上下文支撑，无任何捏造、夸大或矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1和片段2）均明确指出了会话连续20分钟（或二十分钟）无操作后自动失效，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"两个片段均包含直接回答问题的关键信息（连续20分钟无操作后会话自动失效），但存在大量噪声：片段1中账号锁定、终端管理、浏览器密码保存等内容与问题弱相关；片段2中角色权限、数据保留策略、导出审批规则等章节与问题完全无关，仅末尾「会话要求」部分相关。整体约一半内容相关，噪声较多。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，准确回答了\'20分钟\'这一关键信息，无遗漏或错误。\"}', 32368, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (146, '20260903-211840-b62c97b8', 'aurora-docx-010', 'Engineer 修改配置前还需要什么身份步骤？', 'Engineer 在修改配置前必须**重新验证身份**。\n\n这是因为系统规定连续二十分钟无操作后会话自动失效，而在执行配置修改等敏感操作前，必须确保身份经过重新验证以保障安全。', 'Engineer修改配置前身份验证步骤', '[\"353283917827145732\", \"353283917827145741\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145732\", \"documentId\": \"3\", \"rerankScore\": 2.2062065601348877, \"chunkContent\": \"## **认证与会话安全**\\n连续二十分钟无操作后会话自动失效。工程师执行配置修改、导出敏感数据或切换设备控制状态前必须重新验证身份。连续五次认证失败时账号锁定三十分钟，并通知安全管理员检查来源。\\n维护终端离开受控区域后不得保持登录状态。操作完成后应主动退出，不能只关闭浏览器窗口。浏览器不得保存园区系统密码，下载的临时文件应在任务完成后按审批要求清理。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7706044}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 1.4317572116851809, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7528038}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地指出了Engineer在修改配置前需要\'重新验证身份\'的核心步骤，并补充了合理的上下文解释（如会话失效机制和安全要求），完全切题，没有无关内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答准确指出了Engineer修改配置前必须重新验证身份，且补充的会话失效规定和安全目的均直接来源于检索上下文，无任何捏造、夸大或矛盾的内容。\", \"contextRecallReason\": \"标准答案的关键信息为「Engineer 执行配置修改前必须重新验证身份」。检索上下文片段1明确提到「工程师执行配置修改...前必须重新验证身份」，片段2更是直接写明「Engineer 执行配置修改前必须重新验证身份」，与标准答案完全一致，关键信息全部覆盖。\", \"contextPrecisionReason\": \"两个片段均直接包含了Engineer/工程师修改配置前必须重新验证身份的核心答案，但也混杂了大量关于其他角色权限、数据保留策略、终端安全和导出审批等与问题无关的噪声信息，相关片段占比约为一半。\", \"answerCorrectnessReason\": \"模型回答准确指出了\'重新验证身份\'这一核心步骤，与标准答案语义完全一致。补充的原因解释合理且未产生冲突，关键信息无遗漏。\"}', 25904, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (147, '20260903-211840-b62c97b8', 'aurora-docx-011', '园区数据分为哪四级？', '园区数据分为以下四级：\n\n1. **公开测试**：可用于培训和评测，必须明确标注为虚构，不得使用真实人员姓名、电话号码、账号、密码或令牌。\n2. **内部**：仅限园区授权人员使用。\n3. **敏感**：包括设备配置、详细拓扑和未公开事件记录。\n4. **受限**：包括真实密码、访问令牌和个人身份信息。此类数据不得进入知识库、工单正文或普通导出文件。', '园区数据四级分类', '[\"353283917827145728\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145728\", \"documentId\": \"3\", \"rerankScore\": 5.051570892333984, \"chunkContent\": \"# **补充条款**  \\n## **数据分类与处理要求**\\n园区数据分为公开测试、内部、敏感和受限四级。公开测试数据可用于培训和评测；内部数据仅限园区授权人员使用；敏感数据包括设备配置、详细拓扑和未公开事件记录；受限数据包括真实密码、访问令牌和个人身份信息。受限数据不得进入知识库、工单正文或普通导出文件。\\n文档上传前，责任人必须确认数据级别、保留期限和允许使用范围。无法确定级别时按更高一级保护。测试数据必须明确标注为虚构，不得使用真实人员姓名、电话号码、账号、密码或令牌。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8111778}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地列出了园区数据的四个级别，并对每个级别进行了清晰的解释，完全切题，没有冗余或无关内容。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确列出了园区数据的四个级别及其对应的详细说明和处理要求，将上下文中的\'测试数据\'合理归入\'公开测试\'级别，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确提到了‘园区数据分为公开测试、内部、敏感和受限四级’，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"检索上下文中的唯一片段直接且准确地回答了用户关于园区数据分为哪四级的问题，明确列出了公开测试、内部、敏感和受限四个级别及其定义与处理要求，无任何无关噪声。\", \"answerCorrectnessReason\": \"模型回答准确列出了标准答案中的四级数据名称（公开测试、内部、敏感、受限），核心信息完全一致且无遗漏，同时补充了各级数据的详细说明，语义完全一致。\"}', 31661, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (148, '20260903-211840-b62c97b8', 'aurora-docx-012', '谁可以批准临时权限例外？', '临时权限例外必须由**资源负责人**和**安全管理员**共同批准。\n\n在紧急情况下（如处理 P1 事件），可先授予最小必要权限，但需在四小时内补齐审批流程。', '临时权限例外审批人员', '[\"353283917827145731\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145731\", \"documentId\": \"3\", \"rerankScore\": 3.74212908744812, \"chunkContent\": \"## **临时权限与例外**\\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.87557006}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地指出了批准临时权限例外的具体责任人（资源负责人和安全管理员），并合理补充了紧急情况下的审批流程，完全切题，准确回应了问题核心。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确指出了批准临时权限例外的角色（资源负责人和安全管理员），并补充了紧急情况下的审批要求，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文明确指出临时权限例外必须由资源负责人和安全管理员共同批准，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"片段1直接且准确地回答了谁可以批准临时权限例外的问题，所有上下文均与问题高度相关，无无关噪声。\", \"answerCorrectnessReason\": \"模型回答准确指出了由资源负责人和安全管理员共同批准，与标准答案的核心语义完全一致。补充的紧急情况处理细节未与标准答案冲突，属于合理的上下文扩展。\"}', 9856, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (149, '20260903-211840-b62c97b8', 'aurora-docx-013', '临时权限最长有效期是多少？', '临时权限的最长有效期为**七天**。\n\n到期后权限会自动失效。如果确需延长，必须重新进行审批，不得直接修改原申请的到期时间。', '临时权限最长有效期', '[\"353283917827145731\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145731\", \"documentId\": \"3\", \"rerankScore\": 5.314712047576904, \"chunkContent\": \"## **临时权限与例外**\\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8693725}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地指出了临时权限的最长有效期为七天，并补充了到期失效及延长的相关规定，内容完全切题且完整，没有无关内容。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确回答了临时权限的最长有效期为七天，并正确补充了到期失效和延长的相关规定，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确提到\'临时权限最长有效期为七天\'，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"片段1直接且明确地回答了临时权限的最长有效期（七天），所有内容均与问题高度相关，无冗余或噪声。\", \"answerCorrectnessReason\": \"模型回答准确指出了最长有效期为七天，与标准答案的核心语义完全一致。额外补充的失效和延期规则属于合理的上下文扩展，未引入任何错误或矛盾，关键信息无遗漏。\"}', 9562, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (150, '20260903-211840-b62c97b8', 'aurora-docx-014', '审计记录至少应包含哪些信息？', '审计记录至少应包含以下六项核心信息：\n\n*   **操作人**\n*   **时间**\n*   **对象**\n*   **动作**\n*   **结果**\n*   **来源地址**\n\n此外，针对配置变更类的操作，还需额外记录变更前后差异、审批单号和验证结果。', '审计记录必备信息要求', '[\"353283917827145734\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": 3.751059055328369, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78087324}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接且完整地列出了审计记录应包含的核心要素（操作人、时间、对象、动作、结果、来源地址），准确回应了问题核心，补充的特定场景信息也属于合理扩展，无冗余或无关内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确列出了审计记录至少应包含的六项核心信息（操作人、时间、对象、动作、结果、来源地址）以及配置变更的额外记录要求（变更前后差异、审批单号、验证结果），无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文完全覆盖了标准答案中的所有关键信息，明确列出了操作人、时间、对象、动作、结果和来源地址，与标准答案表述完全一致。\", \"contextPrecisionReason\": \"片段1的前半部分明确回答了审计记录应包含的具体信息，与问题高度相关；但后半部分关于权限复核的内容与问题无关，属于噪声，整体相关比例约为一半。\", \"answerCorrectnessReason\": \"模型回答完整包含了标准答案中要求的所有六项核心信息（操作人、时间、对象、动作、结果和来源地址），语义完全一致，关键信息无遗漏。额外补充的扩展信息不影响核心答案的正确性。\"}', 16367, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (151, '20260903-211840-b62c97b8', 'aurora-docx-015', '权限复核的固定频率是什么？', '权限复核的固定频率为每半年一次。\n\n若系统权限模型、数据保留期限或导出流程发生重大变化，则应提前进行复核。', '权限复核固定频率', '[\"353283917827145736\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145736\", \"documentId\": \"3\", \"rerankScore\": 0.8653241395950317, \"chunkContent\": \"## **策略例行检查**\\n本策略每半年复核一次，系统权限模型、数据保留期限或导出流程发生重大变化时应提前复核。策略变更发布前需完成影响分析、操作培训和历史数据处理确认。所有补充条款均为虚构评测数据，不对应真实系统。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.84869313}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 0.0, \"relevancyReason\": \"模型回答直接且准确地指出了权限复核的固定频率为每半年一次，补充的特殊情况触发条件也属于合理的相关信息，完全切题且无冗余。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确提取了权限复核的固定频率（每半年一次）以及需要提前复核的具体条件，不存在任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文仅提及策略每半年复核一次，完全未覆盖标准答案中\'系统负责人\'和\'每季度执行一次\'的关键信息，且频率信息与标准答案冲突。\", \"contextPrecisionReason\": \"片段1明确指出了策略的例行复核频率为每半年一次，直接回答了用户关于权限复核固定频率的问题，无无关噪声。\", \"answerCorrectnessReason\": \"模型回答的固定频率（每半年一次）与标准答案（每季度一次）明显冲突，核心事实错误。\"}', 27598, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (152, '20260903-211840-b62c97b8', 'aurora-docx-016', '发现真实令牌进入工单后应如何处理？', '发现真实令牌进入工单后，应采取以下处置措施：\n\n1.  **立即响应**：限制工单访问权限，通知安全管理员，并撤销相关凭据。\n2.  **记录过程**：详细记录整个处置过程。\n3.  **后续验证与清理**：\n    *   安全管理员需验证旧凭据已失效。\n    *   确保替换后的新凭据已安全分发。\n    *   清理所有缓存和导出副本。\n    *   在工单中保留不含敏感值的验证结论。\n\n需要注意的是，处置完成并不代表事件关闭，必须经过上述验证和清理步骤。', '真实令牌进入工单处理流程', '[\"353283917827145735\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145735\", \"documentId\": \"3\", \"rerankScore\": 4.836976528167725, \"chunkContent\": \"## **敏感信息事件处置**\\n发现真实密码或令牌进入工单后，应立即限制工单访问、通知安全管理员、撤销相关凭据并记录处置过程。发现个人身份信息时，应停止继续传播，确认下载和转发范围，并按数据事件流程评估影响。\\n处置完成不代表事件关闭。安全管理员应验证旧凭据已失效、替换凭据已安全分发、缓存和导出副本已清理，并在工单中保留不含敏感值的验证结论。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79195094}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地回答了用户关于发现真实令牌进入工单后的处理流程，提供了清晰、合理的处置步骤（立即响应、记录过程、后续验证与清理），内容高度切题且无冗余。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确提取了限制访问、通知管理员、撤销凭据、记录过程以及后续的验证与清理等所有处置步骤，逻辑清晰，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文完全覆盖了标准答案中的所有关键信息，明确提到了限制工单访问、通知安全管理员、撤销相关凭据（包含令牌）并记录处置过程。\", \"contextPrecisionReason\": \"片段1直接且详细地回答了发现真实令牌进入工单后的处理流程，包括限制访问、通知管理员、撤销凭据及后续验证等步骤，所有内容均与问题高度相关，无无关噪声。\", \"answerCorrectnessReason\": \"模型回答完整覆盖了标准答案中的限制工单访问、通知安全管理员、撤销令牌和记录处置过程等所有关键信息，语义完全一致且无遗漏，额外补充的后续步骤属于合理延伸。\"}', 19123, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (153, '20260903-211840-b62c97b8', 'aurora-pdf-001', '处理故障前应先确认哪些基本信息？', '在处理故障前，应先确认以下基本信息，以确保排查方向准确且高效：\n\n1. **故障现象**：明确具体出现了什么问题，包括错误代码、报警信息、异常声音或表现等。\n2. **发生时间**：确认故障首次出现的时间点，以及是持续存在还是间歇性发生。\n3. **影响范围**：判断故障是单个设备/用户受影响，还是大面积或系统性问题。\n4. **近期变更**：了解在故障发生前是否进行过系统更新、配置修改、硬件更换或网络调整等操作。\n5. **环境信息**：确认相关的操作系统版本、软件版本、硬件型号、网络拓扑等基础环境参数。\n6. **复现步骤**：如果可能，确认是否能够稳定复现该故障，以及复现的具体操作流程。\n\n收集这些信息有助于快速定位问题根源，避免盲目操作导致故障扩大。', '故障处理前需确认的基本信息', '[]', '[]', '[]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 0.0, \"contextRecall\": null, \"relevancyReason\": \"模型回答完全切题，准确且全面地列出了处理故障前需要确认的核心基本信息（如故障现象、发生时间、影响范围、近期变更等），结构清晰，无冗余或无关内容，完美回应了问题核心。\", \"contextPrecision\": null, \"answerCorrectness\": 0.5, \"faithfulnessReason\": \"检索上下文为空，模型回答的所有内容均无法从提供的上下文中得到支撑，在RAG评估标准下属于脱离上下文的捏造。\", \"contextRecallReason\": null, \"contextPrecisionReason\": null, \"answerCorrectnessReason\": \"模型回答覆盖了标准答案中的“影响区域（范围）”、“错误码（代码）”和“告警开始时间（发生时间）”，但遗漏了“资产编号”和“当前维护状态”这两个关键信息。此外，模型回答偏向通用的IT故障排查流程，与标准答案针对特定运维告警场景的精确要求存在一定差异，属于部分正确。\"}', 33452, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (154, '20260903-211840-b62c97b8', 'aurora-pdf-002', 'E-17 表示什么问题？', 'E-17 表示**设备时钟偏差故障**，具体指设备时钟偏差超过了九十秒。\n\n该故障通常由以下原因引起：\n*   时间服务器不可达；\n*   备用时间源切换失败；\n*   网络访问控制变更；\n*   采集进程长期未同步。\n\n由于时间偏差会导致事件排序错误和产生重复数据，因此处理时必须先校正时间，然后再恢复数据采集。', 'E-17错误代码含义', '[\"353285809898651651\", \"353285809898651650\", \"353285880643977216\", \"353285880643977237\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 3.618065357208252, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.81852674}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.618065357208252, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.410484}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 2.3930373191833496, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8035658}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977237\", \"documentId\": \"6\", \"rerankScore\": 1.947841763496399, \"chunkContent\": \"﻿事件编号：INC-260822; 发生时间（CST）：2026-08-28 04:06; 严重级别：P2; 资产编号：AU-GW-003; 错误码：E-17; 解决时长（分钟）：41; 根本原因：时间服务器切换失败; 处置摘要：切换备用时间源并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81413376}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.6666666666666666}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地指出了E-17表示设备时钟偏差故障，并补充了具体偏差范围、常见原因及处理建议，完全切题且内容完整，没有无关内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确提取了E-17故障的含义（设备时钟偏差超过九十秒）、常见原因、造成的影响以及处理原则，没有任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文明确指出“E-17 表示设备时钟偏差超过九十秒”，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"片段1和2包含E-17的详细定义，但混有大量其他故障码和通用流程等无关噪声；片段3和4为完全相关的E-17事件案例。整体相关比例约一半，噪声较多。\", \"answerCorrectnessReason\": \"模型回答准确包含了标准答案的核心信息（设备时钟偏差超过90秒/九十秒），语义完全一致。额外补充的故障原因和处理建议属于合理的扩展信息，未与标准答案产生冲突或遗漏关键信息。\"}', 26899, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (155, '20260903-211840-b62c97b8', 'aurora-pdf-003', 'E-17 的首要处置动作是什么？', 'E-17 故障表示设备时钟偏差超过九十秒，其首要处置动作是**检查园区时间服务是否可达，并确认其他设备是否同时异常**。\n\n在确认时间源正常后，后续步骤包括查看设备当前时间与同步状态、执行 NTP 同步，最后重启 Edge Collector 采集进程。需要注意的是，处置过程中严禁重启 HG-220 网关，以免扩大采集中断。', 'E-17首要处置动作', '[\"353285809898651650\", \"353285880643977216\", \"353285880643977237\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.244800567626953, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.76364386}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 1.2014832496643066, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.413168}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977237\", \"documentId\": \"6\", \"rerankScore\": 1.0500476360321045, \"chunkContent\": \"﻿事件编号：INC-260822; 发生时间（CST）：2026-08-28 04:06; 严重级别：P2; 资产编号：AU-GW-003; 错误码：E-17; 解决时长（分钟）：41; 根本原因：时间服务器切换失败; 处置摘要：切换备用时间源并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.302438}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"准确且直接地回答了首要处置动作，但补充了后续处置步骤和注意事项等非问题直接询问的内容，略有冗余。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"回答完全基于上下文，准确提取了E-17故障的含义、首要处置动作（步骤一）、后续步骤以及禁止操作，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文明确列出了E-17的处置步骤，包括检查时间服务是否可达（确认时间源可用）、执行NTP同步以及重启Edge Collector采集进程，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"片段1详细说明了E-17的处置步骤，直接回答了首要处置动作，但其中包含了大量其他故障（如E-42、R-09等）的无关内容，存在一定冗余；片段2和片段3提供了E-17的历史处置案例记录，均与问题相关。整体大部分内容相关，少量冗余。\", \"answerCorrectnessReason\": \"模型回答包含了标准答案的所有关键步骤（确认时间源可用/检查时间服务可达、执行NTP同步、重启Edge Collector采集进程），逻辑顺序完全一致。虽然模型对步骤进行了‘首要’与‘后续’的细分，并补充了额外细节，但核心语义一致，关键信息无遗漏。\"}', 26716, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (156, '20260903-211840-b62c97b8', 'aurora-pdf-004', '处理 E-17 时为什么禁止重启 HG-220？', '在处理 E-17（时钟偏差）故障时，禁止重启 HG-220 网关主要基于以下两点原因：\n\n1.  **无法解决根本问题**：重启网关不能替代时间校正操作，无法修复导致时钟偏差的根本原因（如时间服务器不可达或同步失败）。\n2.  **扩大故障影响**：重启操作会导致采集中断范围扩大，加剧数据缺失或服务不可用的情况。\n\n正确的处置方式应是先执行 NTP 同步校正时间，随后重启 Edge Collector 采集进程以重新建立带正确时间戳的连接。', '处理E-17时禁止重启HG-220原因', '[\"353285809898651651\", \"353285809898651650\", \"353285880643977237\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 3.1689248085021973, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8064648}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.1689248085021973, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.824525}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977237\", \"documentId\": \"6\", \"rerankScore\": 0.8173758387565613, \"chunkContent\": \"﻿事件编号：INC-260822; 发生时间（CST）：2026-08-28 04:06; 严重级别：P2; 资产编号：AU-GW-003; 错误码：E-17; 解决时长（分钟）：41; 根本原因：时间服务器切换失败; 处置摘要：切换备用时间源并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7963403}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、完整地回应了用户问题，明确给出了禁止重启 HG-220 的两点原因（无法解决根本问题、扩大故障影响），并补充了正确的处置方式，内容切题且无冗余。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文。上下文明确指出‘不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正’，模型准确提取了这两点原因（扩大故障影响、无法解决根本问题），并正确补充了上下文中的正确处置步骤（执行NTP同步后重启Edge Collector采集进程），无捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文明确指出了E-17是时钟偏差（同步）问题，并在处置步骤中明确说明不得重启HG-220网关的原因是‘重启会扩大采集中断，且不能替代时间校正’，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"片段1和片段2中明确包含了处理E-17时禁止重启HG-220的原因（重启会扩大采集中断且不能替代时间校正），与问题高度相关；片段3仅为E-17的事件记录，未提及HG-220及禁止重启的原因，属于弱相关或噪声。大部分片段相关，少量冗余，因此评分为0.8。\", \"answerCorrectnessReason\": \"模型回答完全覆盖了标准答案中的所有关键点（E-17为时钟同步/偏差问题、重启会扩大采集中断、不能替代时间校正），语义完全一致，且额外补充的正确处置方式属于合理扩展，无冲突或遗漏。\"}', 30269, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (157, '20260903-211840-b62c97b8', 'aurora-pdf-005', 'E-17 处置完成后如何验证？', 'E-17（时钟偏差故障）处置完成后的验证需同时满足以下三项标准：\n\n1.  **时钟偏差达标**：设备时钟偏差需低于三十秒。\n2.  **数据质量正常**：新采集的记录时间连续且顺序正确。\n3.  **观察期无复发**：连续观察十五分钟，无新的 E-17 告警产生。\n\n若同步后偏差仍超过九十秒，应保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。', 'E-17处置完成后验证方法', '[\"353285809898651651\", \"353283299259580421\"]', '[\"4\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 3.0332322120666504, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7744765}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 1.1530405282974243, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.736062}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地提供了E-17处置完成后的三项具体验证标准，准确回应了问题核心，无无关内容。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文中的\'E-17 时钟偏差故障\'验证标准部分，准确列出了三项验证标准以及偏差仍超过九十秒时的后续处理步骤，无捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确指出了E-17的验证标准，包含‘设备时钟偏差低于三十秒’以及‘连续观察十五分钟无新的 E-17 告警’，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"检索上下文中仅片段1的“E-17 时钟偏差故障”小节和片段2中提及E-17的一句话与问题直接相关，其余大量关于其他故障（如E-42、R-09、S-03等）的处置流程及通用原则均为无关噪声，相关文本占整体比例较小（约20%）。\", \"answerCorrectnessReason\": \"模型回答完全覆盖了标准答案中的两个核心验证条件（时钟偏差低于30秒、连续观察15分钟无新告警），关键信息无遗漏且语义一致。虽然补充了数据质量检查和后续异常处理等额外信息，但不影响核心答案的正确性。\"}', 28072, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (158, '20260903-211840-b62c97b8', 'aurora-pdf-006', 'E-42 表示什么问题？', 'E-42 表示**事件队列积压**故障，具体含义是事件队列中的记录数超过了五万条。\n\n这种情况通常由以下原因引起：\n*   消费进程停滞\n*   下游存储变慢\n*   历史记录未归档\n*   规则计算异常重试\n\n队列积压会导致告警延迟。需要注意的是，严禁通过直接清空队列来恢复系统，而应采取归档旧记录、检查进程状态等规范步骤进行处理。', 'E-42错误代码含义', '[\"353285809898651651\", \"353285809898651650\", \"353285880643977217\", \"353285880643977231\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 2.4632718563079834, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8214251}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.4632718563079834, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 6.601178}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977217\", \"documentId\": \"6\", \"rerankScore\": 2.0206851959228516, \"chunkContent\": \"﻿事件编号：INC-260802; 发生时间（CST）：2026-08-07 14:20; 严重级别：P3; 资产编号：AU-CM-003; 错误码：E-42; 解决时长（分钟）：55; 根本原因：历史事件未及时归档; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.85038006}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977231\", \"documentId\": \"6\", \"rerankScore\": 1.9215385913848877, \"chunkContent\": \"﻿事件编号：INC-260816; 发生时间（CST）：2026-08-25 12:26; 严重级别：P2; 资产编号：AU-GW-002; 错误码：E-42; 解决时长（分钟）：49; 根本原因：事件消费进程停滞; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8509481}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接且准确地回答了E-42表示事件队列积压故障，并提供了具体的含义、原因、影响及处理建议，内容完全切题且完整，没有无关内容。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确提取了E-42的含义（事件队列记录数超过五万条）、常见原因、导致的影响（延迟告警）以及处置原则（禁止直接清空队列，需归档和检查进程），没有任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确指出“E-42 表示事件队列记录数超过五万条”，与标准答案“事件队列记录数超过 50,000 条”的关键信息完全一致，实现了全覆盖。\", \"contextPrecisionReason\": \"所有4个片段均包含与E-42相关的信息（片段1和2提供了E-42的定义与处置指南，片段3和4提供了E-42的实际故障案例）。但片段1和2中包含了大量其他故障码（如E-17、R-09等）及通用排查流程等冗余内容，存在较多噪声，因此扣除部分分数。\", \"answerCorrectnessReason\": \"模型回答准确指出了 E-42 表示事件队列记录数超过五万条，与标准答案的核心信息完全一致。虽然补充了原因和处理建议等额外信息，但不影响核心语义的一致性，关键信息无遗漏。\"}', 30832, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (159, '20260903-211840-b62c97b8', 'aurora-pdf-007', 'E-42 归档记录的时间条件是什么？', 'E-42 归档记录的时间条件是：记录必须**超过三十天**且**已完成质量校验**。\n\n此外，严禁归档三十天以内的活跃事件。', 'E-42归档记录时间条件', '[\"353285809898651651\", \"353283812000661505\"]', '[\"4\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 0.8631436228752136, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79778755}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 0.7087113261222839, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.400738}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型准确回答了时间条件（超过三十天），但混入了非时间条件（已完成质量校验），略有冗余。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确提取了E-42归档记录的时间条件（超过三十天且已完成质量校验），并补充了禁止归档三十天以内活跃事件的规定，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1的E-42处置步骤中）明确指出了‘只归档超过三十天并已完成质量校验的记录’，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"检索上下文中仅片段1的“E-42 事件队列积压”章节和片段2的“缓存与队列巡检”小节明确提及了E-42及归档记录需超过三十天的时间条件。其余大部分内容（如E-17、R-09、S-03等其他故障排查、通用流程、维护窗口等）均与问题无关，噪声较多，相关片段占比约为20%。\", \"answerCorrectnessReason\": \"模型回答准确涵盖了标准答案中的两个核心条件（超过30天和已完成质量校验），其补充说明与标准答案中\'只归档\'的排他性逻辑一致，语义完全一致，无关键信息遗漏或错误。\"}', 25328, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (160, '20260903-211840-b62c97b8', 'aurora-pdf-008', 'E-42 处置后队列深度应降到多少？', 'E-42 处置后，队列深度应降到 **5000 条以下**。', 'E-42处置后队列深度标准值', '[\"353285809898651651\", \"353283812000661505\", \"353283299259580421\"]', '[\"4\", \"2\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 2.3389172554016113, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.83882064}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 1.519073724746704, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7788229}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 1.2590428590774536, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.539257}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确地给出了E-42处置后队列深度的具体目标数值，完全切题，无任何冗余或无关内容。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文。上下文中多次明确提到E-42的验证标准和恢复标准为‘队列深度降到五千条以下’或‘低于5,000条’，模型回答‘5000条以下’准确无误，无任何捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"检索上下文中多处明确提到 E-42 处置后的验证标准或恢复标准为队列深度降到 5,000 条（或五千条）以下，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"所有三个检索片段均明确包含了E-42处置后队列深度应降至5000条（或五千条）以下的关键信息，没有完全无关的噪声片段，相关片段占比为100%。\", \"answerCorrectnessReason\": \"语义完全一致，关键信息无遗漏，仅数字格式（千位分隔符）和排版（加粗）略有不同，不影响实际含义。\"}', 31733, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (161, '20260903-211840-b62c97b8', 'aurora-pdf-009', 'R-09 表示什么故障？', 'R-09 表示**机器人安全联锁状态异常**。\n\n该故障可能由以下原因引起：\n*   安全门触点松动\n*   输入信号抖动\n*   线路故障\n*   联锁控制器状态不一致\n\n出现 R-09 告警时，必须优先按安全事件处理，立即停止机器人自动运行并隔离设备，严禁短接安全触点、屏蔽联锁信号或远程强制运行。', 'R-09故障代码含义', '[\"353285809898651650\", \"353285809898651652\", \"353285880643977235\", \"353285880643977218\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.487668037414551, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.112854}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 3.487668037414551, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7777511}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977235\", \"documentId\": \"6\", \"rerankScore\": 2.4287912845611572, \"chunkContent\": \"﻿事件编号：INC-260820; 发生时间（CST）：2026-08-27 10:33; 严重级别：P2; 资产编号：AU-RB-008; 错误码：R-09; 解决时长（分钟）：22; 根本原因：安全门触点松动; 处置摘要：紧固触点后复位联锁; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7826258}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977218\", \"documentId\": \"6\", \"rerankScore\": 2.367234230041504, \"chunkContent\": \"﻿事件编号：INC-260803; 发生时间（CST）：2026-08-11 21:05; 严重级别：P1; 资产编号：AU-RB-007; 错误码：R-09; 解决时长（分钟）：12; 根本原因：联锁输入短时抖动; 处置摘要：检查线路后复位安全联锁; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7809309}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接且明确地回答了R-09代表的故障含义，并合理补充了相关的故障原因与处理建议，内容紧扣故障诊断主题，无无关冗余信息，完全切题且回答完整。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确提取了R-09故障的含义、可能原因及处置原则，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确指出‘R-09 表示机器人安全联锁状态异常’，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"所有4个片段均包含与R-09相关的信息（片段1和2包含R-09的明确定义，片段3和4为R-09的实际故障案例）。但片段1和2中包含了大量其他故障码（如E-17、E-42等）的排查指南和通用流程，且片段1与片段2内容完全重复，存在较多的冗余和无关噪声。\", \"answerCorrectnessReason\": \"模型回答的核心内容与标准答案完全一致，准确指出了R-09表示机器人安全联锁状态异常。补充的故障原因和处理建议属于合理的额外扩展信息，未改变或遗漏核心语义。\"}', 26114, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (162, '20260903-211840-b62c97b8', 'aurora-pdf-010', 'R-09 处置前为何要隔离机器人？', 'R-09 故障表示机器人安全联锁状态异常。在处置前隔离机器人的主要目的是**防止误动作**，以保障人身和生产安全。\n\n根据安全原则，任何 R-09 告警都必须优先按安全事件处理，第一步操作即为立即停止机器人自动运行并隔离设备。', 'R-09处置前隔离机器人原因', '[\"353285809898651652\", \"353285809898651650\"]', '[\"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 2.6105949878692627, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7914332}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.6105949878692627, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.3585205}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地回答了用户问题，明确指出隔离机器人的主要目的是防止误动作以保障人身和生产安全，并合理补充了相关的安全原则，内容高度切题且无冗余。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文得出。上下文中明确指出R-09处置步骤的第一步是‘立即停止机器人自动运行并隔离设备，防止误动作’，且安全原则强调‘先保障人身和生产安全’以及‘任何R-09都必须先按安全事件处理’。模型准确提取并整合了这些信息，无捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中在\'R-09 机器人安全联锁异常\'的处置步骤里明确提到\'隔离设备，防止误动作\'，完全覆盖了标准答案中的关键信息。\", \"contextPrecisionReason\": \"检索上下文为完整的故障排查指南，仅第五节\'R-09\'部分包含问题答案（隔离设备以防止误动作），其余关于其他故障代码及通用流程的内容均为无关噪声，且两个片段内容完全重复，导致大部分文本与问题无关。\", \"answerCorrectnessReason\": \"模型回答明确指出了隔离机器人的主要目的是防止误动作，与标准答案的核心语义完全一致，关键信息无遗漏，补充的背景信息也未产生冲突。\"}', 27042, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (163, '20260903-211840-b62c97b8', 'aurora-pdf-011', 'S-03 表示什么故障？', 'S-03 表示**温度传感器校准偏移**故障，具体含义是温度传感器的校准偏移量超出了允许范围。\n\n该故障的常见原因包括：\n*   校准到期\n*   探头污染\n*   安装位置变化\n*   参考仪表异常\n\n需要注意的是，未经复核的异常读数不得直接作为停线依据。', 'S-03故障代码含义', '[\"353285809898651650\", \"353285809898651652\", \"353285880643977219\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.3108065128326416, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.112854}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 3.3108065128326416, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7551626}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977219\", \"documentId\": \"6\", \"rerankScore\": 2.344501256942749, \"chunkContent\": \"﻿事件编号：INC-260804; 发生时间（CST）：2026-08-16 08:40; 严重级别：P2; 资产编号：AU-SN-014; 错误码：S-03; 解决时长（分钟）：27; 根本原因：传感器校准偏移; 处置摘要：重新校准并观察二十分钟; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78735715}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接且准确地回答了S-03表示的故障名称及具体含义，完全切中问题核心。但额外补充的常见原因和注意事项超出了用户直接询问的范围，属于轻微冗余，因此略微扣分。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确提取了S-03故障的含义、常见原因及注意事项，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文（片段1和片段2的第六部分）明确指出‘S-03 表示温度传感器校准偏移超出允许范围’，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"三个片段均包含与 S-03 相关的信息（片段1和2包含 S-03 的定义与处置流程，片段3为 S-03 的具体事件记录），但片段1和2为完整的指南文档，其中包含大量其他故障码（如 E-17、E-42、R-09 等）及通用流程等无关内容，存在较多冗余噪声。\", \"answerCorrectnessReason\": \"模型回答完全包含了标准答案的核心信息（温度传感器校准偏移超出允许范围），语义完全一致。补充的常见原因和注意事项属于合理扩展，关键信息无遗漏且无错误。\"}', 23359, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (164, '20260903-211840-b62c97b8', 'aurora-pdf-012', 'S-03 校准后要观察多久？', 'S-03 校准后需要连续观察**二十分钟**。\n\n在此期间，需确认传感器读数回到正常范围（18至26摄氏度）或与参考仪表的差值回到允许范围，且数据无突跳、不再产生 S-03 告警，方可视为验证通过。', 'S-03校准后观察时间', '[\"353285880643977219\", \"353285809898651652\"]', '[\"6\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977219\", \"documentId\": \"6\", \"rerankScore\": 3.1457889080047607, \"chunkContent\": \"﻿事件编号：INC-260804; 发生时间（CST）：2026-08-16 08:40; 严重级别：P2; 资产编号：AU-SN-014; 错误码：S-03; 解决时长（分钟）：27; 根本原因：传感器校准偏移; 处置摘要：重新校准并观察二十分钟; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81493473}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 2.953083038330078, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.4047785}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地回答了观察时间（二十分钟），并合理补充了观察期间需要确认的具体指标和验证标准，内容完整、切题，无无关或冗余信息。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文，准确指出S-03校准后需要连续观察二十分钟，并正确补充了上下文中的验证标准（读数范围、数据无突跳、不再产生告警），无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中的片段1和片段2（第六部分）均明确指出了S-03重新校准后需要连续观察二十分钟，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"片段1完全相关，提供了S-03校准后的观察时间；片段2中第六节详细解答了S-03的验证标准和观察时间，但同时也包含了大量其他无关故障码（如E-17、E-42、R-09等）的排查指南，冗余噪声较多，整体相关内容占比约为一半。\", \"answerCorrectnessReason\": \"模型回答准确指出了核心信息\'连续观察二十分钟\'，与标准答案语义完全一致。补充的观察确认条件属于合理细节扩展，未产生矛盾，关键信息无遗漏。\"}', 28691, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (165, '20260903-211840-b62c97b8', 'aurora-pdf-013', 'N-11 表示什么故障？', 'N-11 表示**工业交换机链路丢包率持续超标**。\n\n该故障的常见原因包括：\n*   光模块温度过高\n*   接口松动\n*   上联拥塞\n*   维护期间链路切换', 'N-11故障代码含义', '[\"353285880643977221\", \"353285880643977233\", \"353285809898651652\", \"353285809898651650\"]', '[\"6\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977221\", \"documentId\": \"6\", \"rerankScore\": 1.9145625829696655, \"chunkContent\": \"﻿事件编号：INC-260806; 发生时间（CST）：2026-08-19 13:35; 严重级别：P2; 资产编号：AU-SW-012; 错误码：N-11; 解决时长（分钟）：64; 根本原因：上联端口丢包; 处置摘要：切换备用链路并更换模块; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78017896}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977233\", \"documentId\": \"6\", \"rerankScore\": 1.860856771469116, \"chunkContent\": \"﻿事件编号：INC-260818; 发生时间（CST）：2026-08-26 01:22; 严重级别：P2; 资产编号：AU-SW-011; 错误码：N-11; 解决时长（分钟）：58; 根本原因：光模块温度过高; 处置摘要：更换光模块并观察链路; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78293246}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 1.7976887226104736, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7843278}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 1.7976887226104736, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.112854}]', '{\"mrr\": 0.3333333333333333, \"hitAtK\": true, \"recallAtK\": 0.3333333333333333}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且明确地指出了 N-11 代表的故障类型，并合理补充了常见原因，内容完全切题，无冗余或无关信息，准确回应了问题核心。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确提取了N-11故障的含义（工业交换机链路丢包率持续超标）以及常见原因（光模块温度过高、接口松动、上联拥塞、维护期间链路切换），无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确提到‘N-11 表示工业交换机链路丢包率持续超标’，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"所有片段均包含与“N-11”故障直接相关的信息，包括具体事件案例（片段1、2）和故障排查指南中的明确定义与处置步骤（片段3、4），无无关噪声。\", \"answerCorrectnessReason\": \"模型回答完全包含了标准答案的核心信息，语义完全一致，关键信息无遗漏，且额外补充了故障的常见原因。\"}', 21950, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (166, '20260903-211840-b62c97b8', 'aurora-pdf-014', 'N-11 切换备用链路后应验证什么？', 'N-11 故障切换备用链路后，应验证以下内容：\n\n1. **网关心跳恢复**：确认网关通信状态正常。\n2. **链路丢包率回到基线范围**：确保网络传输质量恢复正常标准。\n3. **持续观察十五分钟**：在观察期内无异常，以确认故障已彻底解决。', 'N-11切换备用链路后验证项', '[\"353285809898651652\", \"353285880643977221\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 3.215597629547119, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78291655}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977221\", \"documentId\": \"6\", \"rerankScore\": 1.279452919960022, \"chunkContent\": \"﻿事件编号：INC-260806; 发生时间（CST）：2026-08-19 13:35; 严重级别：P2; 资产编号：AU-SW-012; 错误码：N-11; 解决时长（分钟）：64; 根本原因：上联端口丢包; 处置摘要：切换备用链路并更换模块; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8138998}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地回应了用户问题，清晰列出了切换备用链路后需要验证的具体内容（网关心跳、丢包率、持续观察时间），结构清晰，无冗余信息，完全切题。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文中「七、N-11 工业网络丢包」的验证标准（网关心跳恢复、链路丢包率回到基线范围、持续观察十五分钟），内容准确，无捏造、夸大或与上下文矛盾的情况。\", \"contextRecallReason\": \"检索上下文中关于\'N-11 工业网络丢包\'的验证标准明确指出\'网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟\'，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"片段1中仅“七、N-11 工业网络丢包”章节直接回答了验证标准的问题，其余大量章节（如E-17、E-42、R-09等）均为无关噪声；片段2为N-11的工单记录，属于弱相关背景信息。整体检索上下文中无关文本占比较大。\", \"answerCorrectnessReason\": \"模型回答完全覆盖了标准答案中的三个关键点（网关心跳恢复、丢包率回落、持续观察十五分钟），语义完全一致，关键信息无遗漏。\"}', 23590, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (167, '20260903-211840-b62c97b8', 'aurora-pdf-015', 'G-08 表示什么故障？', 'G-08 表示**规则包不一致**故障。\n\n具体含义及表现如下：\n*   **核心定义**：规则包的版本或加载结果出现不一致。\n*   **常见表现**：主备节点版本不同、校验和不一致，或部分规则加载失败。\n\n**处置与验证要点：**\n1.  **处置步骤**：应立即停止继续发布，记录当前版本和校验和，比较主备节点规则包。若新版本不完整，需恢复最近一次批准的版本并重新加载。**严禁**直接修改生产节点上的单个规则文件。\n2.  **验证标准**：主备节点的版本和校验和必须一致，规则加载日志无失败项，并完成抽样事件计算。只有在校验和与抽样计算均通过后，方可恢复发布。', 'G-08故障代码含义', '[\"353285809898651650\", \"353285880643977243\", \"353285880643977222\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.5798163414001465, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.112854}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977243\", \"documentId\": \"6\", \"rerankScore\": 2.4751453399658203, \"chunkContent\": \"﻿事件编号：INC-260828; 发生时间（CST）：2026-08-31 00:48; 严重级别：P2; 资产编号：AU-SV-021; 错误码：G-08; 解决时长（分钟）：69; 根本原因：规则包加载不完整; 处置摘要：恢复上版规则包并重载; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78808194}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977222\", \"documentId\": \"6\", \"rerankScore\": 2.422312021255493, \"chunkContent\": \"﻿事件编号：INC-260807; 发生时间（CST）：2026-08-20 02:18; 严重级别：P3; 资产编号：AU-SV-022; 错误码：G-08; 解决时长（分钟）：31; 根本原因：备用节点规则包版本落后; 处置摘要：同步规则包并执行校验; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.76122993}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接且准确地回答了G-08表示\'规则包不一致\'故障，但补充了较多用户未直接询问的处置步骤与验证标准，略有冗余。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于检索上下文中的“八、G-08 规则包不一致”部分，准确提取并概括了G-08故障的核心定义、常见表现、处置步骤和验证标准，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段1中明确说明‘G-08 表示规则包版本或加载结果不一致’，完全覆盖了标准答案中的所有关键信息。\", \"contextPrecisionReason\": \"所有检索片段均与用户问题高度相关。片段1明确给出了G-08故障的定义、含义及处置标准，片段2和片段3提供了G-08故障的实际发生案例与处置记录，不存在与问题无关的噪声片段。\", \"answerCorrectnessReason\": \"模型回答的核心定义与标准答案完全一致，准确指出了G-08表示规则包版本或加载结果不一致。虽然补充了常见表现和处置步骤等额外信息，但关键信息无遗漏且语义无冲突。\"}', 24272, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (168, '20260903-211840-b62c97b8', 'aurora-pdf-016', 'G-08 回退后必须执行什么验证？', 'G-08 回退后必须执行**规则包校验和**与**抽样事件计算**。只有这两项验证均通过，才能恢复发布。', 'G-08回退后验证流程', '[\"353285809898651653\"]', '[\"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": 3.651455879211426, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7654345}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且明确地指出了G-08回退后必须执行的具体验证项目（规则包校验和与抽样事件计算），完全切题，无任何冗余或无关内容。\", \"contextPrecision\": 0.1, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确指出了G-08回退后必须执行的验证步骤（规则包校验和抽样事件计算）以及恢复发布的前提条件，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中明确提到了\'回退后必须执行规则包校验和抽样事件计算\'，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"上下文共包含9个主要章节，仅有第八章（G-08 规则包不一致）与问题直接相关并提供了准确答案，其余8个章节均为其他故障排查指南等无关噪声。相关部分占比约11%，属于大部分片段与问题无关的情况。\", \"answerCorrectnessReason\": \"模型回答准确包含了标准答案中的两项关键验证：规则包校验和抽样事件计算，核心语义完全一致。模型额外补充了\'只有两项验证均通过才能恢复发布\'的信息，属于合理延伸且不与标准答案矛盾。整体语义一致，细节略有增加。\"}', 33206, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (169, '20260903-211840-b62c97b8', 'aurora-pdf-017', '故障恢复需要满足哪三个共同条件？', '抱歉，关于故障恢复需要满足哪三个共同条件，当前知识库中没有相关资料。\n\n提供的资料中明确指出系统恢复至少满足**四项**条件，而非三项：\n1. 受影响区域重新可见；\n2. 关键设备心跳连续正常；\n3. 事件队列没有持续增长；\n4. 抽样规则计算结果正确。', '故障恢复的三个共同条件', '[\"353283299259580428\"]', '[\"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580428\", \"documentId\": \"1\", \"rerankScore\": 0.8915812969207764, \"chunkContent\": \"## 恢复验收标准\\n系统恢复至少满足四项条件：受影响区域重新可见，关键设备心跳连续正常，事件队列没有持续增长，抽样规则计算结果正确。仅恢复页面访问不代表生产能力恢复。\\nP1 恢复由当班经理确认，并由 Quality 团队抽样验证；P2 恢复由责任团队确认，值班员复核关键指标；P3 可由处理人确认。恢复后仍需完成规定观察期，观察期内再次出现同类告警时沿用原事件，不重复创建新事件。\\n关闭事件前应撤销临时权限和临时配置，解除设备隔离，恢复暂停的批任务，并确认交接记录已更新。无法立即完成的长期纠正措施应转为问题记录，不能以事件已恢复为由删除后续任务。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8131926}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.8, \"faithfulness\": 1.0, \"contextRecall\": 0.2, \"relevancyReason\": \"模型纠正了用户问题中“三个条件”的错误前提，准确列出了资料中实际的四项恢复条件，回应了问题核心。但开头声称“没有相关资料”与后文提供的资料内容存在矛盾，略有冗余。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"模型准确识别出问题中的“三个条件”与上下文中的“四项条件”不符，并完全基于检索上下文列出了正确的四项系统恢复条件，回答完全由上下文支撑，无任何捏造或矛盾。\", \"contextRecallReason\": \"标准答案中的“指标回到阈值内”和“核心能力可用”在上下文中均未体现，仅有“规定观察期内无同类告警”在上下文中有相关表述，覆盖比例较低。\", \"contextPrecisionReason\": \"检索片段直接讨论了系统故障恢复需要满足的条件和验收标准，虽然具体数量（四项）与问题（三个）略有出入，但主题高度契合，无无关噪声。\", \"answerCorrectnessReason\": \"模型回答未能提供标准答案中的三个条件（指标回到阈值内、核心能力可用、规定观察期内无同类告警），反而给出了四个完全不同的条件，且明确表示知识库中无相关资料，与标准答案语义完全不一致。\"}', 29027, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (170, '20260903-211840-b62c97b8', 'aurora-pdf-018', 'P1 故障由哪个协调组统筹？', 'P1 故障由**蓝鹭应急协调组**统筹。', 'P1故障统筹协调组', '[\"353285809898651650\", \"353285809898651653\", \"353283299259580425\"]', '[\"4\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.46008563041687, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.393538}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": 3.46008563041687, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7643148}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580425\", \"documentId\": \"1\", \"rerankScore\": 1.430884599685669, \"chunkContent\": \"## 术语说明\\n- Edge Platform：负责边缘网关和采集服务的团队名称。\\n- Quality：负责质量抽样和结果确认的团队名称。\\n- Blue Heron：P1 事件使用的应急协调组代号。\\n- 恢复时间：从事件确认到核心能力恢复的持续时间。\\n- 观察时间：恢复后继续监控、确认指标稳定的时间。\\n- 隔离设备：为防止影响扩大而暂时停止接入平台的设备。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.74298257}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确且完整地回答了用户关于P1故障统筹协调组的问题，没有任何冗余或无关内容，完全切题。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确指出了P1故障由蓝鹭应急协调组统筹，与原文内容完全一致，无任何捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"检索上下文中明确提到“P1 故障由蓝鹭应急协调组统筹”，完全覆盖了标准答案中的关键信息。\", \"contextPrecisionReason\": \"所有片段均包含解答问题的关键信息（蓝鹭应急协调组/Blue Heron），但片段1和片段2中包含了大量与问题无关的具体故障排查指南（如E-17、E-42、R-09等），整体文本中噪声较多，相关内容占比约在20%到30%之间。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息无遗漏，仅增加了Markdown加粗格式，不影响核心含义。\"}', 28999, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (171, '20260903-211840-b62c97b8', 'aurora-pdf-019', 'P2 超过两小时未恢复时如何处理？', '当 P2 级别故障超过两小时仍未恢复时，需执行以下处理流程：\n\n1.  **事件升级**：将该事件升级为 P1 级别。\n2.  **统筹管理**：由蓝鹭应急协调组接手统筹处理。\n3.  **状态更新频率调整**：处理团队的状态更新频率从每三十分钟一次调整为每十五分钟一次。', 'P2故障超时未恢复处理流程', '[\"353285809898651650\", \"353283299259580422\", \"353283299259580429\"]', '[\"4\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.039400339126587, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 16.75849}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 1.750779628753662, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.474283}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580429\", \"documentId\": \"1\", \"rerankScore\": 0.6056198477745056, \"chunkContent\": \"## 评测事实边界\\n本数据集中的时间、阈值、资产和流程构成封闭测试事实。不同文档出现同一规则时，应以条件更具体的条款回答。例如“P2 首次响应目标为两小时”和“P2 超过两小时未恢复升级为 P1”描述的是不同管理节点，回答时必须保留“首次响应”或“未恢复”的条件。\\n资产编号和错误码是专有标识，不应翻译或改写。团队英文代号仅用于保持跨文档一致性，不代表需要使用英文回答。文档没有给出具体责任人的场景，应回答责任团队或当班经理，不得编造姓名和联系方式。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.521449}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地回应了用户问题，详细列出了P2故障超过两小时未恢复时的具体处理流程（事件升级、统筹管理、状态更新频率调整），内容高度切题，结构清晰且无冗余信息。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文得出。事件升级为P1以及由蓝鹭应急协调组统筹在上下文中有直接明确的表述；状态更新频率从每三十分钟一次调整为每十五分钟一次，是根据上下文中P2（三十分钟）和P1（十五分钟）的状态更新规则进行的准确且合理的逻辑推断，不存在捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文中多次明确提到“P2 超过两小时未恢复时升级为 P1”，完全覆盖了标准答案的所有关键信息。\", \"contextPrecisionReason\": \"片段2和片段3与问题高度相关，直接提供了P2超时未恢复的升级处理规则；但片段1中包含了大量与问题无关的具体设备故障排查指南（如E-17、E-42、R-09等），噪声较多，整体相关文本占比约为一半。\", \"answerCorrectnessReason\": \"模型回答完全覆盖了标准答案的核心信息（升级为P1），并额外补充了具体的统筹管理和状态更新流程，关键信息无遗漏且无冲突。\"}', 34291, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (172, '20260903-211840-b62c97b8', 'aurora-pdf-020', '排障记录至少需要保存哪些证据？', '排障记录至少需要保存以下五类证据：\n\n1. **时间线**\n2. **关键日志**\n3. **执行命令或操作**\n4. **配置差异**\n5. **验证结果**', '排障记录证据保存要求', '[\"353285809898651650\"]', '[\"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 1.3315657377243042, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.36425}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且完整地列出了排障记录需要保存的五类核心证据，结构清晰，完全切题，无任何冗余或无关内容。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文中“通用排查流程”第六步“留存证据”的明确规定，准确列出了时间线、关键日志、执行命令或操作、配置差异和验证结果这五类证据，无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文在‘二、通用排查流程’的第六步中明确列出了‘至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果’，与标准答案完全一致，覆盖了所有关键信息。\", \"contextPrecisionReason\": \"上下文中仅在“通用排查流程”的第六步直接回答了排障记录需保存的具体证据（时间线、关键日志等），其余绝大部分篇幅（如各类具体故障的排查步骤、适用范围、升级交接等）均与问题无关，噪声比例较高。\", \"answerCorrectnessReason\": \"模型回答完整包含了标准答案中的所有五个关键要素（时间线、关键日志、执行命令或操作、配置差异、验证结果），语义完全一致，无任何遗漏，仅排版格式不同。\"}', 29826, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (173, '20260903-211840-b62c97b8', 'aurora-xlsx-001', 'AU-GW-001 的资产名称和责任团队是什么？', '资产编号 AU-GW-001 的资产名称为**北区边缘网关**，责任团队为**边缘平台组**。', 'AU-GW-001资产名称与责任团队', '[\"353285847806771200\", \"353285847806771202\", \"353285847806771201\", \"353285880643977216\"]', '[\"5\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771200\", \"documentId\": \"5\", \"rerankScore\": 5.330458641052246, \"chunkContent\": \"资产编号：AU-GW-001; 资产名称：北区边缘网关; 生产区：A区; 子区域：A1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-18; 下次维护时间：2026-09-02 02:00; 维护任务：固件校验; 维护时长（分钟）：45; 关键等级：关键; 备注：负责A区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.80042315}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771202\", \"documentId\": \"5\", \"rerankScore\": 1.6930681467056274, \"chunkContent\": \"资产编号：AU-GW-003; 资产名称：装配区边缘网关; 生产区：C区; 子区域：C1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-20; 下次维护时间：2026-09-16 02:00; 维护任务：时钟校验; 维护时长（分钟）：30; 关键等级：关键; 备注：负责C区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.788249}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771201\", \"documentId\": \"5\", \"rerankScore\": 1.2487331628799438, \"chunkContent\": \"资产编号：AU-GW-002; 资产名称：南区边缘网关; 生产区：B区; 子区域：B1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-19; 下次维护时间：2026-09-09 02:00; 维护任务：缓存检查; 维护时长（分钟）：30; 关键等级：关键; 备注：负责B区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7888893}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 0.6803197264671326, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同