INSERT INTO `eval_run_case` VALUES (200, '20260903-211840-b62c97b8', 'aurora-csv-014', 'INC-260805 的响应目标是否达标？', 'INC-260805 的响应目标已达标。', 'INC-260805响应目标达标情况', '[\"353285880643977220\", \"353285880643977219\", \"353285880643977222\", \"353285880643977243\", \"353285880643977238\"]', '[\"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977220\", \"documentId\": \"6\", \"rerankScore\": 5.098690509796143, \"chunkContent\": \"﻿事件编号：INC-260805; 发生时间（CST）：2026-08-18 10:12; 严重级别：P3; 资产编号：AU-BC-081; 错误码：B-04; 解决时长（分钟）：46; 根本原因：条码表面反光; 处置摘要：调整补光角度并复测; 响应目标是否达标：是; 复盘状态：无需复盘\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.8760195}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977219\", \"documentId\": \"6\", \"rerankScore\": 3.6538801193237305, \"chunkContent\": \"﻿事件编号：INC-260804; 发生时间（CST）：2026-08-16 08:40; 严重级别：P2; 资产编号：AU-SN-014; 错误码：S-03; 解决时长（分钟）：27; 根本原因：传感器校准偏移; 处置摘要：重新校准并观察二十分钟; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7777244}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977222\", \"documentId\": \"6\", \"rerankScore\": 3.1138830184936523, \"chunkContent\": \"﻿事件编号：INC-260807; 发生时间（CST）：2026-08-20 02:18; 严重级别：P3; 资产编号：AU-SV-022; 错误码：G-08; 解决时长（分钟）：31; 根本原因：备用节点规则包版本落后; 处置摘要：同步规则包并执行校验; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.77671695}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977243\", \"documentId\": \"6\", \"rerankScore\": 2.9232192039489746, \"chunkContent\": \"﻿事件编号：INC-260828; 发生时间（CST）：2026-08-31 00:48; 严重级别：P2; 资产编号：AU-SV-021; 错误码：G-08; 解决时长（分钟）：69; 根本原因：规则包加载不完整; 处置摘要：恢复上版规则包并重载; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.78713775}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977238\", \"documentId\": \"6\", \"rerankScore\": 2.908137083053589, \"chunkContent\": \"﻿事件编号：INC-260823; 发生时间（CST）：2026-08-28 13:29; 严重级别：P3; 资产编号：AU-CM-003; 错误码：V-06; 解决时长（分钟）：61; 根本原因：校准板位置偏移; 处置摘要：固定校准板并重新标定; 响应目标是否达标：是; 复盘状态：无需复盘\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7744836}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接、准确地回答了用户关于INC-260805响应目标是否达标的问题，没有冗余信息，完全切题。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文片段1中关于INC-260805的记录，准确指出其响应目标已达标（是），无任何捏造、夸大或与上下文矛盾的内容。\", \"contextRecallReason\": \"检索上下文片段1明确包含了事件编号INC-260805及其\'响应目标是否达标：是\'的信息，完全覆盖了标准答案的关键信息。\", \"contextPrecisionReason\": \"5个片段中仅有片段1包含INC-260805的相关信息，其余4个片段均为其他事件编号的无关噪声，相关片段占比约20%。\", \"answerCorrectnessReason\": \"模型回答与标准答案的核心语义完全一致，均明确表示INC-260805的响应目标已达标，无关键信息遗漏。\"}', 10682, 1, NULL, '2026-09-03 22:54:24', '2026-09-03 22:54:24', 0, 0);
INSERT INTO `eval_run_case` VALUES (201, '20260908-235537-d56929be', 'aurora-md-001', '曙光智造园区的内部代号是什么？', '曙光智造园区的内部代号是 **Aurora-7**。', '曙光智造园区内部代号', '[\"353283299259580417\", \"353283812000661504\", \"353285809898651650\", \"353283299259580416\", \"353283917827145741\"]', '[\"1\", \"2\", \"4\", \"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580417\", \"documentId\": \"1\", \"rerankScore\": 7.810397624969482, \"chunkContent\": \"## 基本信息\\n曙光智造园区（Aurora Smart Manufacturing Campus）的内部代号为 **Aurora-7**，园区位于虚构城市“海岚市”。园区共有 A、B、C 三个生产区，统一使用 **HG-220** 边缘网关采集设备数据。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8875729}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 2.951829671859741, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.86375207}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 0.6968001127243042, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7760159}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580416\", \"documentId\": \"1\", \"rerankScore\": -0.3730701208114624, \"chunkContent\": \"# 曙光智造园区概览\\n> 文档版本：1.2\\n> 生效日期：2026-08-01\\n> 本文所有名称、编号和数据均为虚构测试数据。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8253316}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": -1.8176445960998535, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7696938}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接、完整地回应了曙光智造园区内部代号，无无关内容。\", \"contextPrecision\": 0.4, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答“Aurora-7”直接来自片段1，完全有上下文支撑，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确给出了曙光智造园区内部代号为 Aurora-7，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1直接回答内部代号为Aurora-7；片段2提及Aurora-7但主体为运行手册，属弱相关；片段3、4、5主要涉及故障排查、概览标题和访问策略，与内部代号问题无关或基本无关。5个片段中约2个相关，因此给0.4。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，准确给出内部代号 Aurora-7，仅格式不同。\"}', 16149, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (202, '20260908-235537-d56929be', 'aurora-md-002', '园区包含哪些生产区？', '园区包含 **A区**、**B区** 和 **C区** 三个生产区，具体职责划分如下：\n\n*   **A区**：负责来料检测与能源分配。\n*   **B区**：负责精密加工与环境控制。\n*   **C区**：负责装配、视觉质检和成品暂存。', '园区生产区构成', '[\"353283299259580420\", \"353283299259580417\"]', '[\"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580420\", \"documentId\": \"1\", \"rerankScore\": 3.792142868041992, \"chunkContent\": \"## 园区区域与系统组成\\n园区按生产职责划分为三个区域。A 区负责来料检测与能源分配，B 区负责精密加工与环境控制，C 区负责装配、视觉质检和成品暂存。区域下设 A1、A2、B1、B2、C1、C2 六个子区域，子区域编号只用于定位，不改变事件级别。\\n每个子区域至少部署一台环境传感器，关键产线通过 HG-220 边缘网关接入。网关每分钟上报一次心跳，每五分钟汇总一次设备状态。连续丢失三次心跳定义为通信异常，但处置前必须先排除交换机维护、链路抖动和时间同步问题。\\n园区平台由设备采集、事件队列、规则计算、质量校验和报表归档五项能力组成。设备采集负责接收现场数据；事件队列负责削峰；规则计算负责生成告警；质量校验负责识别缺失值和异常值；报表归档负责保存经审批的统计结果。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7928251}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580417\", \"documentId\": \"1\", \"rerankScore\": 0.6065449714660645, \"chunkContent\": \"## 基本信息\\n曙光智造园区（Aurora Smart Manufacturing Campus）的内部代号为 **Aurora-7**，园区位于虚构城市“海岚市”。园区共有 A、B、C 三个生产区，统一使用 **HG-220** 边缘网关采集设备数据。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7575716}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出A区、B区、C区三个生产区，完整回应问题；附加职责说明略冗余但基本相关。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完整列出了 A、B、C 三个生产区，并且职责划分与检索上下文完全一致，无捏造或夸大。\", \"contextRecallReason\": \"检索上下文片段2明确提到园区共有 A、B、C 三个生产区，片段1也分别描述了 A、B、C 区的职责，完整覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"两段均包含与问题直接相关的生产区信息，能回答园区包含A、B、C三个生产区；片段中的边缘网关、平台组成、通信异常等属于弱相关或冗余内容，但整体大部分相关。\", \"answerCorrectnessReason\": \"模型回答与标准答案在关键信息上完全一致，均指出园区包含 A、B、C 三个生产区；额外职责说明不影响语义一致性。\"}', 6512, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (203, '20260908-235537-d56929be', 'aurora-md-003', '园区统一使用哪种边缘网关？', '曙光智造园区统一使用 **HG-220** 边缘网关来采集设备数据。\n\n该型号网关部署在 A、B、C 三个生产区的关键产线上，负责每分钟上报心跳及每五分钟汇总一次设备状态，确保现场数据能够顺利接入园区平台。', '园区统一边缘网关选型', '[\"353283299259580417\", \"353285847806771202\", \"353285847806771200\", \"353285847806771201\", \"353283299259580420\"]', '[\"1\", \"5\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580417\", \"documentId\": \"1\", \"rerankScore\": 1.6884948015213013, \"chunkContent\": \"## 基本信息\\n曙光智造园区（Aurora Smart Manufacturing Campus）的内部代号为 **Aurora-7**，园区位于虚构城市“海岚市”。园区共有 A、B、C 三个生产区，统一使用 **HG-220** 边缘网关采集设备数据。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7699651}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771202\", \"documentId\": \"5\", \"rerankScore\": -1.0015486478805542, \"chunkContent\": \"资产编号：AU-GW-003; 资产名称：装配区边缘网关; 生产区：C区; 子区域：C1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-20; 下次维护时间：2026-09-16 02:00; 维护任务：时钟校验; 维护时长（分钟）：30; 关键等级：关键; 备注：负责C区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78168356}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771200\", \"documentId\": \"5\", \"rerankScore\": -1.4377373456954956, \"chunkContent\": \"资产编号：AU-GW-001; 资产名称：北区边缘网关; 生产区：A区; 子区域：A1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-18; 下次维护时间：2026-09-02 02:00; 维护任务：固件校验; 维护时长（分钟）：45; 关键等级：关键; 备注：负责A区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7990094}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771201\", \"documentId\": \"5\", \"rerankScore\": -1.7472692728042605, \"chunkContent\": \"资产编号：AU-GW-002; 资产名称：南区边缘网关; 生产区：B区; 子区域：B1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-19; 下次维护时间：2026-09-09 02:00; 维护任务：缓存检查; 维护时长（分钟）：30; 关键等级：关键; 备注：负责B区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7876667}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580420\", \"documentId\": \"1\", \"rerankScore\": -2.0933287143707275, \"chunkContent\": \"## 园区区域与系统组成\\n园区按生产职责划分为三个区域。A 区负责来料检测与能源分配，B 区负责精密加工与环境控制，C 区负责装配、视觉质检和成品暂存。区域下设 A1、A2、B1、B2、C1、C2 六个子区域，子区域编号只用于定位，不改变事件级别。\\n每个子区域至少部署一台环境传感器，关键产线通过 HG-220 边缘网关接入。网关每分钟上报一次心跳，每五分钟汇总一次设备状态。连续丢失三次心跳定义为通信异常，但处置前必须先排除交换机维护、链路抖动和时间同步问题。\\n园区平台由设备采集、事件队列、规则计算、质量校验和报表归档五项能力组成。设备采集负责接收现场数据；事件队列负责削峰；规则计算负责生成告警；质量校验负责识别缺失值和异常值；报表归档负责保存经审批的统计结果。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78348863}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 0.9, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确地给出了园区统一使用的边缘网关型号为HG-220，完全回应了问题核心，补充信息也与问题相关，无冗余或答非所问内容。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答核心结论‘统一使用HG-220边缘网关’及心跳上报、状态汇总等细节均可由上下文支撑。‘部署在A、B、C三个生产区的关键产线上’为基于上下文资产的合理推断，未直接明确，但无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文中片段1明确说明园区统一使用HG-220边缘网关，片段2、3、4及片段5也多处佐证设备型号为HG-220，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"全部片段均围绕园区边缘网关 HG-220，片段1直接说明统一使用，片段2-4提供各区域网关型号一致，片段5也提及关键产线通过 HG-220 接入，均与问题高度相关。\", \"answerCorrectnessReason\": \"模型回答明确指出统一使用 HG-220 边缘网关，与标准答案核心语义完全一致；额外补充信息未造成矛盾。\"}', 6846, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (204, '20260908-235537-d56929be', 'aurora-md-004', '园区正常温度范围是多少？', '曙光智造园区的正常温度范围是 **18°C 至 26°C**。\n\n当温度低于 18°C 或高于 26°C 时，属于环境异常，值班员应创建 P2 工单进行处理。', '园区正常温度范围', '[\"353283299259580418\", \"353283812000661504\", \"353285809898651651\"]', '[\"1\", \"2\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580418\", \"documentId\": \"1\", \"rerankScore\": -0.2935506999492645, \"chunkContent\": \"## 环境标准\\n- 正常温度范围：18°C 至 26°C。\\n- 正常相对湿度范围：35% 至 65%。\\n- 网关本地缓存使用率达到 **25%** 时应发出预警。\\n- 每周维护窗口：星期三 02:00 至 03:30（CST）。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.80542415}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": -0.4619026184082031, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.74445957}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": -2.469271421432495, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.932166}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.95, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型准确回答了园区正常温度范围为18°C至26°C，并补充了异常处理信息，与问题基本相关但略有冗余。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答中的温度范围来自片段1，低温/高温创建P2工单来自片段2；‘属于环境异常’为对上下文环境处置规则的合理概括，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确给出了正常温度范围为18°C至26°C，完全覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"三个片段均明确或等价指出园区正常温度范围为18°C至26°C。\", \"answerCorrectnessReason\": \"模型回答准确给出了园区正常温度范围为18°C至26°C，与标准答案完全一致，额外信息未造成语义偏差。\"}', 27597, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (205, '20260908-235537-d56929be', 'aurora-md-005', '园区正常相对湿度范围是多少？', '园区正常的相对湿度范围是 **35% 至 65%**。', '园区正常相对湿度范围标准', '[\"353283299259580418\", \"353283812000661504\"]', '[\"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580418\", \"documentId\": \"1\", \"rerankScore\": 0.37404006719589233, \"chunkContent\": \"## 环境标准\\n- 正常温度范围：18°C 至 26°C。\\n- 正常相对湿度范围：35% 至 65%。\\n- 网关本地缓存使用率达到 **25%** 时应发出预警。\\n- 每周维护窗口：星期三 02:00 至 03:30（CST）。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79612726}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": -1.581753492355347, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7376777}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接、准确地给出了园区正常相对湿度范围（35%至65%），完全切题，无冗余内容。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与片段1中‘正常相对湿度范围：35% 至 65%’完全一致，且与片段2的阈值表述相符，无捏造或矛盾。\", \"contextRecallReason\": \"标准答案的关键信息\'园区正常相对湿度范围是35%至65%\'在检索上下文的片段1中明确出现（\'正常相对湿度范围：35% 至 65%\'），信息完整覆盖。\", \"contextPrecisionReason\": \"片段1直接给出了正常相对湿度范围，片段2通过环境处置的异常阈值隐含了相同的正常湿度范围，两个片段均与问题高度相关，无无关噪声。\", \"answerCorrectnessReason\": \"模型回答的核心数值35%至65%与标准答案完全一致，仅存在\'正常的\'和加粗格式的细微表述差异，语义完全相同，关键信息无遗漏。\"}', 20186, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (206, '20260908-235537-d56929be', 'aurora-md-006', '网关本地缓存达到多少时发出预警？', '网关本地缓存使用率达到 **25%** 时发出预警。', '网关本地缓存预警阈值', '[\"353283299259580421\", \"353283299259580418\", \"353283812000661505\", \"353285809898651650\"]', '[\"1\", \"2\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 4.947673797607422, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8465363}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580418\", \"documentId\": \"1\", \"rerankScore\": 3.460612535476685, \"chunkContent\": \"## 环境标准\\n- 正常温度范围：18°C 至 26°C。\\n- 正常相对湿度范围：35% 至 65%。\\n- 网关本地缓存使用率达到 **25%** 时应发出预警。\\n- 每周维护窗口：星期三 02:00 至 03:30（CST）。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8579296}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": -0.3798024356365204, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.82551885}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": -1.8418262004852295, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.373413}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接给出预警阈值25%，明确对应缓存使用率，完整切题。\", \"contextPrecision\": 0.75, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文一致，上下文多处明确说明网关本地缓存使用率达到25%时发出预警。\", \"contextRecallReason\": \"检索上下文多个片段明确包含标准答案关键信息：网关本地缓存使用率达到25%时发出预警。\", \"contextPrecisionReason\": \"片段1、2、3均明确给出网关本地缓存预警阈值为25%，与问题直接相关；片段4主要包含通用故障排查流程，未直接回答该阈值，属于噪声。整体约四分之三相关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息（使用率25%时预警）无遗漏，仅25%有格式加粗差异，不影响语义。\"}', 23326, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (207, '20260908-235537-d56929be', 'aurora-md-007', '网关本地缓存达到多少时暂停非关键采集任务？', '当网关本地缓存使用率达到 **40%** 时，会暂停非关键采集任务。', '网关本地缓存暂停非关键采集任务阈值', '[\"353283299259580421\", \"353283812000661505\", \"353283299259580418\", \"353283812000661507\"]', '[\"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 5.265221118927002, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.83759534}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 1.9342225790023804, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.84184796}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580418\", \"documentId\": \"1\", \"rerankScore\": -0.837440550327301, \"chunkContent\": \"## 环境标准\\n- 正常温度范围：18°C 至 26°C。\\n- 正常相对湿度范围：35% 至 65%。\\n- 网关本地缓存使用率达到 **25%** 时应发出预警。\\n- 每周维护窗口：星期三 02:00 至 03:30（CST）。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.81978345}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": -0.907104790210724, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7738485}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接给出了网关本地缓存暂停非关键采集任务的阈值，完全切题且完整\", \"contextPrecision\": 0.7, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文一致：片段1和片段2明确说明网关本地缓存使用率达到40%时暂停非关键采集任务，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文明确指出网关本地缓存使用率达到40%时暂停非关键采集任务，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2均明确回答缓存使用率达到40%时暂停非关键采集任务；片段3仅提到预警阈值，相关但不直接完整回答；片段4多为操作禁止和恢复验收内容，存在较多噪声。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息（使用率达40%、暂停非关键采集任务）均无遗漏，仅表述方式略有不同。\"}', 4400, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (208, '20260908-235537-d56929be', 'aurora-md-008', '园区固定维护窗口是什么时间？', '曙光智造园区的固定维护窗口时间为**每周三 02:00-03:30 CST**。\n\n在该窗口开始前十五分钟，需暂停非关键批任务；窗口结束后，由 Quality 团队执行抽样校验。', '园区固定维护窗口时间', '[\"353283812000661504\", \"353283299259580423\", \"353283917827145732\", \"353283299259580418\"]', '[\"2\", \"1\", \"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 3.990023136138916, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8165239}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": 3.007726669311523, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81738365}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145732\", \"documentId\": \"3\", \"rerankScore\": -1.1053686141967771, \"chunkContent\": \"## **认证与会话安全**\\n连续二十分钟无操作后会话自动失效。工程师执行配置修改、导出敏感数据或切换设备控制状态前必须重新验证身份。连续五次认证失败时账号锁定三十分钟，并通知安全管理员检查来源。\\n维护终端离开受控区域后不得保持登录状态。操作完成后应主动退出，不能只关闭浏览器窗口。浏览器不得保存园区系统密码，下载的临时文件应在任务完成后按审批要求清理。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.1671915}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580418\", \"documentId\": \"1\", \"rerankScore\": -1.7952864170074463, \"chunkContent\": \"## 环境标准\\n- 正常温度范围：18°C 至 26°C。\\n- 正常相对湿度范围：35% 至 65%。\\n- 网关本地缓存使用率达到 **25%** 时应发出预警。\\n- 每周维护窗口：星期三 02:00 至 03:30（CST）。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7857275}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接给出了固定维护窗口时间，准确回应了问题核心，但包含了窗口前后任务暂停与校验的额外信息，略有冗余。\", \"contextPrecision\": 0.75, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答中的维护窗口时间及窗口前暂停非关键批任务、窗口后Quality团队抽样校验均直接来自上下文，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文片段1、片段2和片段4均明确包含标准答案关键信息：固定维护窗口为每周三 02:00 至 03:30（CST）。\", \"contextPrecisionReason\": \"片段1、2、4明确提到每周三02:00至03:30 CST的固定维护窗口，直接相关；片段3仅涉及认证与会话安全，与问题无关。\", \"answerCorrectnessReason\": \"模型回答完整准确地给出了固定维护窗口时间，与标准答案一致；额外补充信息不影响核心答案的正确性。\"}', 4770, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (209, '20260908-235537-d56929be', 'aurora-md-009', 'P1 事件的首次响应目标是多少？', 'P1 事件的首次响应目标是 **15 分钟**。', 'P1事件首次响应目标时间', '[\"353283299259580419\", \"353283299259580429\", \"353283299259580422\", \"353285880643977218\", \"353283812000661506\"]', '[\"1\", \"6\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580419\", \"documentId\": \"1\", \"rerankScore\": 3.7349231243133545, \"chunkContent\": \"## 服务等级\\n| 级别 | 首次响应目标 | 示例 |\\n|---|---:|---|\\n| P1 | 15 分钟 | 全园区停产或安全联锁失效 |\\n| P2 | 2 小时 | 单个生产区核心能力降级 |\\n| P3 | 1 个工作日 | 非关键报表或体验问题 |\\n紧急停机演练使用的虚构口令为 **ORBIT-7429**。该口令仅用于本测试数据，不对应任何真实系统。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.826038}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580429\", \"documentId\": \"1\", \"rerankScore\": 3.377018451690674, \"chunkContent\": \"## 评测事实边界\\n本数据集中的时间、阈值、资产和流程构成封闭测试事实。不同文档出现同一规则时，应以条件更具体的条款回答。例如“P2 首次响应目标为两小时”和“P2 超过两小时未恢复升级为 P1”描述的是不同管理节点，回答时必须保留“首次响应”或“未恢复”的条件。\\n资产编号和错误码是专有标识，不应翻译或改写。团队英文代号仅用于保持跨文档一致性，不代表需要使用英文回答。文档没有给出具体责任人的场景，应回答责任团队或当班经理，不得编造姓名和联系方式。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79652244}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 3.375758171081543, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.82511544}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977218\", \"documentId\": \"6\", \"rerankScore\": 1.0317432880401611, \"chunkContent\": \"﻿事件编号：INC-260803; 发生时间（CST）：2026-08-11 21:05; 严重级别：P1; 资产编号：AU-RB-007; 错误码：R-09; 解决时长（分钟）：12; 根本原因：联锁输入短时抖动; 处置摘要：检查线路后复位安全联锁; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 7.807232}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 0.6005870699882507, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.68677}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接、简洁地给出了P1事件首次响应目标的具体时间（15分钟），完全切题且准确回应了问题核心，无冗余或无关内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答‘P1 事件首次响应目标为 15 分钟’直接来自检索上下文片段1的服务等级表，未添加、夸大或矛盾内容。\", \"contextRecallReason\": \"上下文片段1明确给出P1首次响应目标为15分钟，与标准答案完全一致。\", \"contextPrecisionReason\": \"片段1直接给出 P1 首次响应目标为 15 分钟，片段5提到 P1 十五分钟内首次状态通报且与响应要求相关，片段3与 P1 事件分级和响应/升级区分相关；但片段2主要是评测边界说明，片段4为单条事件记录且未给出目标值，噪声较多，整体约一半相关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息P1事件、首次响应目标、15分钟均正确包含，仅格式上有加粗标记差异。\"}', 4725, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (210, '20260908-235537-d56929be', 'aurora-md-010', 'P2 事件的首次响应目标是多少？', 'P2 事件的首次响应目标是 **2 小时**。', 'P2事件首次响应目标时长', '[\"353283299259580429\", \"353283299259580419\", \"353283299259580422\", \"353285880643977231\", \"353283812000661506\"]', '[\"1\", \"6\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580429\", \"documentId\": \"1\", \"rerankScore\": 3.82654070854187, \"chunkContent\": \"## 评测事实边界\\n本数据集中的时间、阈值、资产和流程构成封闭测试事实。不同文档出现同一规则时，应以条件更具体的条款回答。例如“P2 首次响应目标为两小时”和“P2 超过两小时未恢复升级为 P1”描述的是不同管理节点，回答时必须保留“首次响应”或“未恢复”的条件。\\n资产编号和错误码是专有标识，不应翻译或改写。团队英文代号仅用于保持跨文档一致性，不代表需要使用英文回答。文档没有给出具体责任人的场景，应回答责任团队或当班经理，不得编造姓名和联系方式。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7939862}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580419\", \"documentId\": \"1\", \"rerankScore\": 3.565131902694702, \"chunkContent\": \"## 服务等级\\n| 级别 | 首次响应目标 | 示例 |\\n|---|---:|---|\\n| P1 | 15 分钟 | 全园区停产或安全联锁失效 |\\n| P2 | 2 小时 | 单个生产区核心能力降级 |\\n| P3 | 1 个工作日 | 非关键报表或体验问题 |\\n紧急停机演练使用的虚构口令为 **ORBIT-7429**。该口令仅用于本测试数据，不对应任何真实系统。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8118247}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 2.719595193862915, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8245012}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977231\", \"documentId\": \"6\", \"rerankScore\": 1.758047103881836, \"chunkContent\": \"﻿事件编号：INC-260816; 发生时间（CST）：2026-08-25 12:26; 严重级别：P2; 资产编号：AU-GW-002; 错误码：E-42; 解决时长（分钟）：49; 根本原因：事件消费进程停滞; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 7.565756}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": -1.2068220376968384, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 7.3417068}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接、简洁、完整，准确给出了P2事件首次响应目标为2小时，完全切题且无冗余内容。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文中的表格一致，P2首次响应目标明确为2小时，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文明确给出P2事件首次响应目标为2小时，覆盖标准答案全部关键信息。\", \"contextPrecisionReason\": \"片段2直接给出P2首次响应目标；片段1和3包含相关事实与边界说明。片段4只是P2事件实例且未给目标值，片段5主要无关，整体有效相关约一半多。\", \"answerCorrectnessReason\": \"模型回答与标准答案在语义上完全一致，准确指出首次响应目标为2小时。\"}', 4667, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (211, '20260908-235537-d56929be', 'aurora-md-011', '什么情况下三个生产区同时异常应按 P1 处理？', '根据提供的资料，三个生产区同时异常应按 P1 处理的情况包括：\n\n1. **同一原因导致的影响**：当同一故障原因在三十分钟内影响三个生产区时，事件按 P1 处理。\n2. **采集能力丧失**：三个生产区同时失去采集能力。\n3. **特定故障场景**：\n   - **E-17 时钟偏差故障**：若三个区域同时发生 E-17 告警，按 P1 处理。\n   - **R-09 机器人安全联锁异常**：若安全联锁无法恢复或影响多台机器人（隐含多区域/全局性影响），立即按 P1 上报。\n4. **通用原则**：若同一原因直接确认影响三个生产区，无论具体故障类型，均直接按 P1 事件处理。', '三个生产区同时异常判定为P1级故障的条件', '[\"353283299259580422\", \"353285809898651650\", \"353283812000661507\"]', '[\"1\", \"4\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 3.2888429164886475, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.86192524}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.1381072998046875, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7925302}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": -1.881181001663208, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.80754244}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.85, \"faithfulness\": 0.8, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出了三个生产区同时异常按P1处理的多种情况，基本切题；但部分表述如“隐含多区域/全局性影响”较不确定，略有冗余。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 0.8, \"faithfulnessReason\": \"模型回答的主要判定依据基本来自上下文，如三个生产区同时失去采集能力、同一原因影响三个生产区以及E-17三个区域同时发生。但将R-09多台机器人异常解释为隐含多区域或三个生产区同时异常属于超出上下文的推断，存在少量扩大表述。\", \"contextRecallReason\": \"检索上下文直接包含标准答案关键信息：三个生产区同时失去采集能力应按P1处理，并另有同一原因影响三个生产区按P1等补充。\", \"contextPrecisionReason\": \"片段1直接给出三个生产区同时异常按P1的分级条件；片段2也包含同一原因影响三个生产区时按P1的规则，但其余内容多为故障码和流程，存在冗余；片段3与多区域异常有一定关联，但未直接回答P1判定条件。\", \"answerCorrectnessReason\": \"模型回答包含了标准答案的关键信息“三个生产区同时失去采集能力时应按 P1 处理”，核心正确；但额外补充了多种未与标准答案完全对应的扩展场景，存在细节不一致。\"}', 17141, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (212, '20260908-235537-d56929be', 'aurora-md-012', 'P2 超过多久未恢复要升级为 P1？', 'P2 事件从确认故障开始计算，超过 **两小时** 仍未恢复时升级为 P1。', 'P2故障升级P1时限规则', '[\"353283299259580422\", \"353285809898651650\", \"353285809898651653\", \"353283299259580429\", \"353283812000661506\"]', '[\"1\", \"4\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 4.333540439605713, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8436378}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.2237019538879395, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.979926}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": 3.2237019538879395, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7942455}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580429\", \"documentId\": \"1\", \"rerankScore\": 3.000321626663208, \"chunkContent\": \"## 评测事实边界\\n本数据集中的时间、阈值、资产和流程构成封闭测试事实。不同文档出现同一规则时，应以条件更具体的条款回答。例如“P2 首次响应目标为两小时”和“P2 超过两小时未恢复升级为 P1”描述的是不同管理节点，回答时必须保留“首次响应”或“未恢复”的条件。\\n资产编号和错误码是专有标识，不应翻译或改写。团队英文代号仅用于保持跨文档一致性，不代表需要使用英文回答。文档没有给出具体责任人的场景，应回答责任团队或当班经理，不得编造姓名和联系方式。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.80881405}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 1.7010799646377563, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.97726}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接给出升级时长为两小时，并补充起算口径，完全切题且完整回应问题核心。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答直接对应片段1中“P2从确认故障开始计算，超过两小时仍未恢复时升级为P1”的表述，且与片段2/3、5中的两小时未恢复升级规则一致，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文多次明确包含关键信息，包括片段1直接说明‘P2从确认故障开始计算，超过两小时仍未恢复时升级为P1’，其他片段也覆盖超过两小时未恢复升级为P1的规则。\", \"contextPrecisionReason\": \"五个片段均包含或涉及“P2超过两小时未恢复升级为P1”的答案，但片段2和3大量故障排查内容属于噪声且高度重复，因此仅给较高分。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，仅多了“事件”和加粗格式。\"}', 22301, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (213, '20260908-235537-d56929be', 'aurora-md-013', '事件队列触发 E-42 的阈值是多少？', '事件队列触发 E-42 的阈值是记录数超过 **50,000** 条。', '事件队列触发 E-42 阈值', '[\"353283299259580421\", \"353285809898651651\", \"353285809898651650\", \"353285880643977231\", \"353283812000661505\"]', '[\"1\", \"4\", \"6\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 4.062352657318115, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8272162}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 2.707728385925293, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.86740404}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.707728385925293, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.543587}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977231\", \"documentId\": \"6\", \"rerankScore\": 1.6933761835098269, \"chunkContent\": \"﻿事件编号：INC-260816; 发生时间（CST）：2026-08-25 12:26; 严重级别：P2; 资产编号：AU-GW-002; 错误码：E-42; 解决时长（分钟）：49; 根本原因：事件消费进程停滞; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.84764373}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 1.513988375663757, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.79530394}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接准确给出了事件队列触发E-42的阈值，无冗余信息\", \"contextPrecision\": 0.7, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答指出事件队列记录数超过 50,000 条时触发 E-42，与上下文片段1及片段5中的阈值完全一致，未出现捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"检索上下文明确给出事件队列记录数超过 50,000 条时触发 E-42，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1、5直接给出 E-42 触发阈值，片段2和3也包含相关内容但大量无关并高度重复，片段4仅与 E-42 事件记录相关而未回答阈值，整体以相关片段为主且存在冗余与噪声。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，均指出事件队列记录数超过50,000条时触发E-42，关键信息无遗漏，仅表述顺序略有不同。\"}', 17342, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (214, '20260908-235537-d56929be', 'aurora-md-014', 'E-42 的恢复标准是什么？', 'E-42 的恢复标准为事件队列记录数低于 5,000 条。\n\n此外，完整的恢复验证需同时满足以下条件：\n1. 队列深度降到 5,000 条以下；\n2. 连续十五分钟消费速度不低于进入速度；\n3. 抽查三条新事件均完成规则计算。', 'E-42恢复标准', '[\"353283299259580421\", \"353285809898651651\", \"353283812000661505\", \"353285880643977231\", \"353285880643977217\"]', '[\"1\", \"4\", \"2\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 4.094696521759033, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.670353}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 1.7446985244750977, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79059666}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 0.5520296692848206, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 7.287961}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977231\", \"documentId\": \"6\", \"rerankScore\": 0.1476291865110397, \"chunkContent\": \"﻿事件编号：INC-260816; 发生时间（CST）：2026-08-25 12:26; 严重级别：P2; 资产编号：AU-GW-002; 错误码：E-42; 解决时长（分钟）：49; 根本原因：事件消费进程停滞; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7784156}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977217\", \"documentId\": \"6\", \"rerankScore\": 0.12237387150526048, \"chunkContent\": \"﻿事件编号：INC-260802; 发生时间（CST）：2026-08-07 14:20; 严重级别：P3; 资产编号：AU-CM-003; 错误码：E-42; 解决时长（分钟）：55; 根本原因：历史事件未及时归档; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7833668}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.95, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接给出了E-42恢复标准，并补充了相关且完整的恢复验证条件，基本无无关内容。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 0.8, \"faithfulnessReason\": \"模型回答完全基于检索上下文：片段1明确E-42恢复标准为队列记录数低于5000条；片段2完整列出队列深度低于5000条、连续十五分钟消费速度不低于进入速度、抽查三条新事件完成规则计算三项验证标准；片段3也支撑队列深度降到5000条以下。无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文中多处明确指出 E-42 的恢复标准或验证标准是事件队列深度降到 5,000 条以下，完整覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"片段1、2、3直接涉及E-42触发条件与恢复标准，片段4、5仅为E-42事件案例，未明确恢复标准，属弱相关。\", \"answerCorrectnessReason\": \"模型回答核心语义与标准答案一致，均指出队列深度/记录数需低于 5,000 条；但额外补充了恢复验证条件，相比标准答案略有扩展。\"}', 18249, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (215, '20260908-235537-d56929be', 'aurora-md-015', '设备时钟偏差超过多少会触发 E-17？', '设备时钟偏差超过 **90秒** 会触发 E-17。', '设备时钟偏差触发E-17阈值', '[\"353285809898651650\", \"353283299259580421\", \"353285880643977216\", \"353285880643977237\"]', '[\"4\", \"1\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.8553249835968018, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.84976774}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 3.593842029571533, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8244462}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 0.7483082413673401, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8601502}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977237\", \"documentId\": \"6\", \"rerankScore\": 0.4856777787208557, \"chunkContent\": \"﻿事件编号：INC-260822; 发生时间（CST）：2026-08-28 04:06; 严重级别：P2; 资产编号：AU-GW-003; 错误码：E-17; 解决时长（分钟）：41; 根本原因：时间服务器切换失败; 处置摘要：切换备用时间源并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.84560746}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接给出了设备时钟偏差触发 E-17 的阈值，完全切题。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文中“设备时钟偏差超过90秒时触发E-17”的表述完全一致，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文片段1和片段2均明确说明设备时钟偏差超过90秒（九十秒）会触发E-17，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2明确包含 E-17 由设备时钟偏差超过90秒触发，可直接回答问题；片段3和片段4仅记录 E-17 故障案例，未提供触发阈值，属于弱相关或噪声，整体约一半片段直接相关。\", \"answerCorrectnessReason\": \"模型回答准确指出设备时钟偏差超过90秒触发E-17，与标准答案关键信息完全一致，仅存在加粗排版差异\"}', 13703, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (216, '20260908-235537-d56929be', 'aurora-md-016', '紧急变更最长应在多久内补齐记录？', '紧急变更应在**二十四小时内**补齐变更记录和回退验证。', '紧急变更补齐记录最长期限', '[\"353283299259580423\", \"353283917827145731\"]', '[\"1\", \"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": 1.5665167570114136, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 21.370392}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145731\", \"documentId\": \"3\", \"rerankScore\": -1.444319248199463, \"chunkContent\": \"## **临时权限与例外**\\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7921052}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答明确给出二十四小时内，直接回应了紧急变更补齐记录的最长时限；额外提及回退验证略超出问题范围，属轻微冗余。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答直接依据片段1中“紧急变更……在二十四小时内补齐变更记录和回退验证”的表述，未捏造或与上下文矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确说明紧急变更应在二十四小时内补齐变更记录和回退验证，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1直接回答了紧急变更需在二十四小时内补齐记录，高度相关；片段2讲的是紧急权限审批的补齐时限，与\'紧急变更记录\'主题不同，属于噪声/弱相关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，仅存在加粗标记的格式差异，关键信息（二十四小时内、补齐变更记录、回退验证）无遗漏。\"}', 3815, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (217, '20260908-235537-d56929be', 'aurora-md-017', '临时配置最长可以保留多久？', '临时配置最长可以保留**七天**。\n\n根据规定，临时权限的最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。此外，事件进入待关闭状态后，临时配置应按登记时间恢复，仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。', '临时配置最长保留时间', '[\"353283917827145731\", \"353283812000661508\", \"353283917827145734\", \"353283917827145737\", \"353283917827145741\"]', '[\"3\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145731\", \"documentId\": \"3\", \"rerankScore\": -0.3772563934326172, \"chunkContent\": \"## **临时权限与例外**\\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7889997}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -0.8564160466194153, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.009093}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": -0.9792218208312988, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7584433}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145737\", \"documentId\": \"3\", \"rerankScore\": -2.144350051879883, \"chunkContent\": \"## **备份与恢复控制**\\n生产数据备份由数据平台组统一执行。每日增量备份保留三十天，每周完整备份保留十二周。备份文件与生产数据采用相同的数据级别和访问要求，不得因为处于备份介质而降低保护标准。\\n每季度至少执行一次抽样恢复验证，验证内容包括文件完整性、记录数量、时间范围和关键字段。恢复验证只能写入隔离环境，不得覆盖当前生产数据。验证完成后应删除临时恢复副本并保留结果记录。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 6.668468}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": -2.335293769836426, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.76241624}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.9, \"faithfulness\": 0.2, \"contextRecall\": 0.3, \"relevancyReason\": \"模型回答直接给出了“七天”，完整回应了核心问题；补充的权限和事件处理规则略多但与临时配置保留相关，存在轻微冗余。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 0.8, \"faithfulnessReason\": \"上下文只规定临时权限最长七天，未规定临时配置最长保留七天；模型将两者混用，核心结论无法支撑。\", \"contextRecallReason\": \"上下文提到临时配置需清理且不能无限期，但未明确“临时配置最长不得超过七天”；“七天”和“写明失效时间”出现在临时权限片段中，不能充分覆盖标准答案针对临时配置的关键信息。\", \"contextPrecisionReason\": \"仅片段2涉及临时配置处理，但未明确最长保留期限；片段1只讲临时权限，片段3-5与临时配置无关，噪声占比高。\", \"answerCorrectnessReason\": \"核心答案一致，均明确最长为七天；但未完整体现标准答案中“必须写明失效时间”的要求，且补充内容较多。\"}', 4352, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (218, '20260908-235537-d56929be', 'aurora-md-018', '超过多少行的数据导出需要双人审批？', '根据参考资料，超过 **10,000 行**（或一万行）的数据导出需要双人审批。\n\n具体审批要求如下：\n*   **审批人员**：Data Steward（数据管理员）和值班经理。', '数据导出双人审批行数阈值', '[\"353283917827145741\", \"353283917827145733\", \"353283299259580424\", \"353283812000661508\"]', '[\"3\", \"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 1.993428111076355, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7828362}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145733\", \"documentId\": \"3\", \"rerankScore\": 1.0378776788711548, \"chunkContent\": \"## **数据导出与共享**\\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.84465003}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": -0.04201424866914749, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.80324996}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -0.8842125535011292, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77168083}]', '{\"mrr\": 0.3333333333333333, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接准确回答了需要双人审批的行数阈值为超过10,000行，补充了审批人员信息，与问题略有扩展但基本相关，存在少量冗余。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答关于超过10,000行（一万行）需要Data Steward（数据管理员）和值班经理双人审批的内容，均可在检索上下文中明确找到支撑，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文明确给出了导出阈值超过 10,000 行，以及需要 Data Steward 和值班经理双人审批的关键信息，完全覆盖标准答案。\", \"contextPrecisionReason\": \"片段1、2、3均直接给出导出审批行数，与问题高度相关；片段4虽包含答案，但混有较多事件流程等无关噪声，属弱相关。\", \"answerCorrectnessReason\": \"模型回答准确给出了超过10,000行的阈值，并明确双人审批人员为Data Steward和值班经理，与标准答案语义完全一致。\"}', 7278, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (219, '20260908-235537-d56929be', 'aurora-txt-001', '每日开班检查从什么时间开始？', '每日开班检查从 **07:45 CST** 开始。', '每日开班检查开始时间', '[\"353283812000661504\", \"353283812000661506\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 3.632851839065552, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.75575167}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": -2.3144826889038086, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.661643}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接准确地给出了每日开班检查的开始时间，完全切题且无冗余内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与上下文一致，片段1明确说明每日开班检查在07:45 CST开始。\", \"contextRecallReason\": \"检索上下文片段1明确提到每日开班检查在 07:45 CST 开始，覆盖了标准答案的全部关键信息。\", \"contextPrecisionReason\": \"片段1明确包含每日开班检查时间07:45 CST，与问题高度相关；片段2主要涉及变更、事件通知和日终检查，与开班检查时间基本无关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键时间信息 07:45 CST 无遗漏，加粗格式不影响语义。\"}', 5019, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (220, '20260908-235537-d56929be', 'aurora-txt-002', '开班时需要依次记录哪些信息？', '根据《曙光智造园区运行手册》，操作员在开班时需要依次记录以下信息：\n\n1.  **A、B、C 三个区域颜色**\n2.  **最后心跳时间**\n3.  **未确认告警数量**\n4.  **当前队列深度**', '开班流程需依次记录的信息内容', '[\"353283812000661504\", \"353283812000661507\", \"353283299259580424\"]', '[\"2\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 1.0889791250228882, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.007112}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": -1.9479299783706665, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 14.276111}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": -2.2483267784118652, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7350948}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接、完整并准确列出了开班时需要依次记录的信息，切题且无无关内容。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答的开班依次记录项均直接来自片段1第6节，无捏造、夸大或与上下文矛盾内容。\", \"contextRecallReason\": \"片段1第6条完整覆盖标准答案：依次记录A、B、C区域颜色、最后心跳时间、未确认告警数量和当前队列深度。\", \"contextPrecisionReason\": \"仅片段1明确给出开班前置检查需依次记录A/B/C区域颜色、最后心跳时间、未确认告警数量和当前队列深度；片段2和3主要涉及异常操作、恢复验收与数据留痕，与开班记录问题关联很弱或无关。\", \"answerCorrectnessReason\": \"模型回答与标准答案在关键信息和记录顺序上完全一致，仅增加了来源说明，不影响语义一致性。\"}', 7972, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (221, '20260908-235537-d56929be', 'aurora-txt-003', 'HG-220 连续丢失三次心跳时能否直接重启？', '不能直接重启。\n\n当 HG-220 连续丢失三次心跳时，应先检查该区域交换机是否处于批准的维护窗口，并从平台查看最后一次成功上报时间。若链路正常，需联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。', 'HG-220 连续丢失三次心跳直接重启条件', '[\"353283812000661504\", \"353283299259580421\", \"353283812000661505\", \"353283299259580420\", \"353285809898651651\"]', '[\"2\", \"1\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 3.937929391860962, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 22.103958}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 2.832237243652344, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8228491}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 2.4394357204437256, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8041049}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580420\", \"documentId\": \"1\", \"rerankScore\": 0.531129777431488, \"chunkContent\": \"## 园区区域与系统组成\\n园区按生产职责划分为三个区域。A 区负责来料检测与能源分配，B 区负责精密加工与环境控制，C 区负责装配、视觉质检和成品暂存。区域下设 A1、A2、B1、B2、C1、C2 六个子区域，子区域编号只用于定位，不改变事件级别。\\n每个子区域至少部署一台环境传感器，关键产线通过 HG-220 边缘网关接入。网关每分钟上报一次心跳，每五分钟汇总一次设备状态。连续丢失三次心跳定义为通信异常，但处置前必须先排除交换机维护、链路抖动和时间同步问题。\\n园区平台由设备采集、事件队列、规则计算、质量校验和报表归档五项能力组成。设备采集负责接收现场数据；事件队列负责削峰；规则计算负责生成告警；质量校验负责识别缺失值和异常值；报表归档负责保存经审批的统计结果。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 19.499954}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": -0.10256247967481612, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 19.80981}]', '{\"mrr\": 0.3333333333333333, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接明确“不能直接重启”，并补充了心跳丢失三次后的正确检查与联系流程，内容切题且完整。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文一致，明确说明不得直接重启，并按片段1和片段3给出检查维护窗口、查看最后上报时间、联系 Edge Platform 团队等依据，无捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"上下文清楚说明连续丢失三次心跳时不得直接重启网关，应先检查交换机维护/链路情况，并联系 Edge Platform 团队。\", \"contextPrecisionReason\": \"片段1和片段3直接回答了连续丢失三次心跳时不得直接重启 HG-220；片段2和片段4提供心跳定义与告警背景，相关但非核心；片段5主要无关且仅在特定故障中提及不得重启，属弱相关噪声。\", \"answerCorrectnessReason\": \"模型回答明确不能直接重启，并涵盖检查维护/链路情况以及联系 Edge Platform 团队，与标准答案语义一致且信息完整。\"}', 24106, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (222, '20260908-235537-d56929be', 'aurora-txt-004', '心跳恢复后应观察多久？', '心跳恢复后的观察时长取决于具体的故障类型和场景，根据参考资料，主要包含以下几种情况：\n\n*   **网关心跳异常（HG-220）**：恢复后需连续观察 **15分钟**，且至少收到 **15次** 正常心跳方可关闭通信告警。\n*   **时钟偏差故障（E-17）**：校正后需连续观察 **15分钟**。\n*   **工业网络丢包（N-11）**：链路恢复后需持续观察 **15分钟**。\n*   **温度和湿度异常**：恢复正常后需继续观察 **20分钟**。\n\n此外，对于其他类型的系统恢复，虽然未规定统一的固定时长，但均要求完成规定的观察期，确保在观察期内无同类告警再次出现，核心指标稳定后方可关闭事件或进入待关闭状态。', '心跳恢复后观察时间', '[\"353283299259580428\", \"353283812000661505\", \"353283299259580421\", \"353285809898651653\", \"353283299259580425\"]', '[\"1\", \"2\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580428\", \"documentId\": \"1\", \"rerankScore\": 0.44526275992393494, \"chunkContent\": \"## 恢复验收标准\\n系统恢复至少满足四项条件：受影响区域重新可见，关键设备心跳连续正常，事件队列没有持续增长，抽样规则计算结果正确。仅恢复页面访问不代表生产能力恢复。\\nP1 恢复由当班经理确认，并由 Quality 团队抽样验证；P2 恢复由责任团队确认，值班员复核关键指标；P3 可由处理人确认。恢复后仍需完成规定观察期，观察期内再次出现同类告警时沿用原事件，不重复创建新事件。\\n关闭事件前应撤销临时权限和临时配置，解除设备隔离，恢复暂停的批任务，并确认交接记录已更新。无法立即完成的长期纠正措施应转为问题记录，不能以事件已恢复为由删除后续任务。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7743794}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 0.04173792153596878, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.774003}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": -0.40742191672325134, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.6940644}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": -1.5383388996124268, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.722175}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580425\", \"documentId\": \"1\", \"rerankScore\": -1.8400382995605469, \"chunkContent\": \"## 术语说明\\n- Edge Platform：负责边缘网关和采集服务的团队名称。\\n- Quality：负责质量抽样和结果确认的团队名称。\\n- Blue Heron：P1 事件使用的应急协调组代号。\\n- 恢复时间：从事件确认到核心能力恢复的持续时间。\\n- 观察时间：恢复后继续监控、确认指标稳定的时间。\\n- 隔离设备：为防止影响扩大而暂时停止接入平台的设备。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.69951636}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.65, \"faithfulness\": 0.9, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接给出了心跳恢复后观察时长（15分钟，至少收到15次正常心跳），切题且信息准确。但同时混入了时钟偏差、网络丢包、温湿度异常等与\'心跳恢复\'无关的故障场景，属于明显冗余，影响回答的聚焦度。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 0.8, \"faithfulnessReason\": \"回答中的观察时长、至少15次心跳、E-17与N-11观察15分钟、温湿度观察20分钟等均可由检索上下文支撑；但将时钟偏差、温湿度等并非明确属于“心跳恢复后”的场景纳入“心跳恢复后”的说明，存在轻微过度扩展，整体无明显捏造或矛盾。\", \"contextRecallReason\": \"检索上下文中片段2明确包含标准答案的关键信息：心跳恢复后需连续观察十五分钟，并至少收到十五次正常心跳。\", \"contextPrecisionReason\": \"片段2和4直接说明心跳恢复后观察十五分钟，片段1、3、5仅泛化提及恢复观察期或心跳指标，整体相关片段约占一半且包含较多无关内容。\", \"answerCorrectnessReason\": \"模型回答包含了标准答案的核心信息（连续观察15分钟且至少收到15次正常心跳），但将其限定为特定网关心跳场景，并扩展到多种故障类型，语义一致但不够直接。\"}', 21455, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (223, '20260908-235537-d56929be', 'aurora-txt-005', '传感器校准过期时应如何处理环境异常数据？', '当传感器校准过期时，应按以下步骤处理环境异常数据：\n\n1.  **标记数据**：先将该异常数据标记为“待确认”。\n2.  **通知复核**：通知 Facilities（设施）团队进行复核。\n3.  **禁止直接停线**：在校准过期期间，不得直接依据该数值执行停线操作。', '传感器校准过期 环境异常数据处理方法', '[\"353283812000661505\", \"353285809898651650\", \"353285809898651652\", \"353285880643977219\", \"353283917827145733\"]', '[\"2\", \"4\", \"6\", \"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 2.8941919803619385, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 20.073254}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 0.659132719039917, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 15.341607}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 0.659132719039917, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7898659}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977219\", \"documentId\": \"6\", \"rerankScore\": -0.2956278324127197, \"chunkContent\": \"﻿事件编号：INC-260804; 发生时间（CST）：2026-08-16 08:40; 严重级别：P2; 资产编号：AU-SN-014; 错误码：S-03; 解决时长（分钟）：27; 根本原因：传感器校准偏移; 处置摘要：重新校准并观察二十分钟; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8375702}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145733\", \"documentId\": \"3\", \"rerankScore\": -1.1010948419570925, \"chunkContent\": \"## **数据导出与共享**\\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 16.380627}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接针对传感器校准过期时环境异常数据的处理，提出标记待确认、通知设施复核、禁止直接停线等关键步骤，切题且无无关内容；但内容略简，未补充影响评估、持续监控或记录审计等细节。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答的三个步骤均直接来自检索上下文片段1第8条关于温度/湿度异常处置中校准过期时的规定，未出现捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文中明确给出校准过期时先将数据标记为“待确认”、通知 Facilities 团队复核，且不直接依据该数值停线，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1直接回答了传感器校准过期时环境异常数据的标记与复核处理，片段2和3涉及传感器校准偏移处置但重复且含大量无关内容，片段4仅为弱相关案例，片段5完全无关，因此存在较多噪声与冗余。\", \"answerCorrectnessReason\": \"模型回答完整覆盖标准答案的关键信息：先标记为待确认、通知Facilities复核，并且不得直接据此停线，语义完全一致。\"}', 26959, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (224, '20260908-235537-d56929be', 'aurora-txt-006', '环境指标恢复后还要观察多久？', '根据故障类型不同，环境指标恢复后的观察时长如下：\n\n*   **温度或湿度异常**：恢复正常后需继续观察 **20分钟**。在此期间需记录最高值、最低值和持续时长，确保数据无突跳且不再产生相关告警（如 S-03）。\n*   **网关心跳异常**：虽然主要涉及通信链路，但若关联环境数据采集网关，恢复后需连续观察 **15分钟**，并至少收到 15 次正常心跳方可关闭通信告警。\n*   **时钟偏差（E-17）**：若因时间同步问题导致的环境数据异常，校正后需连续观察 **15分钟** 无新告警。\n\n总体而言，针对纯粹的温度和湿度传感器校准或越界问题，标准观察期为 **20分钟**。', '环境指标恢复后的观察时长', '[\"353283812000661505\", \"353285809898651653\", \"353283299259580421\", \"353283299259580425\", \"353283299259580428\"]', '[\"2\", \"4\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": -0.15149983763694763, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.608538}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": -1.002158761024475, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.427009}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": -1.4227559566497805, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.533035}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580425\", \"documentId\": \"1\", \"rerankScore\": -1.4649147987365725, \"chunkContent\": \"## 术语说明\\n- Edge Platform：负责边缘网关和采集服务的团队名称。\\n- Quality：负责质量抽样和结果确认的团队名称。\\n- Blue Heron：P1 事件使用的应急协调组代号。\\n- 恢复时间：从事件确认到核心能力恢复的持续时间。\\n- 观察时间：恢复后继续监控、确认指标稳定的时间。\\n- 隔离设备：为防止影响扩大而暂时停止接入平台的设备。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7309998}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580428\", \"documentId\": \"1\", \"rerankScore\": -1.7051893472671509, \"chunkContent\": \"## 恢复验收标准\\n系统恢复至少满足四项条件：受影响区域重新可见，关键设备心跳连续正常，事件队列没有持续增长，抽样规则计算结果正确。仅恢复页面访问不代表生产能力恢复。\\nP1 恢复由当班经理确认，并由 Quality 团队抽样验证；P2 恢复由责任团队确认，值班员复核关键指标；P3 可由处理人确认。恢复后仍需完成规定观察期，观察期内再次出现同类告警时沿用原事件，不重复创建新事件。\\n关闭事件前应撤销临时权限和临时配置，解除设备隔离，恢复暂停的批任务，并确认交接记录已更新。无法立即完成的长期纠正措施应转为问题记录，不能以事件已恢复为由删除后续任务。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.770736}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 0.8, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接说明了环境指标恢复后的观察时长，并按故障类型给出15或20分钟，核心信息完整；网关心跳、时钟偏差等内容略有扩展但总体相关。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"核心答案“温湿度环境指标恢复后观察20分钟，并记录最高/最低值和持续时长”有明确上下文支撑；S-03连续观察20分钟也有依据。回答中补充网关心跳、E-17时钟偏差各15分钟本身可在上下文中找到，但将其作为“环境指标恢复”场景属于条件化推断，上下文并未直接说明这些通信/时间故障属于环境指标问题，因此存在少量无法完全支撑的延伸。\", \"contextRecallReason\": \"检索上下文明确包含环境（温度和湿度）指标恢复正常后需继续观察二十分钟的信息，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2明确给出温湿度/环境异常恢复后观察二十分钟；片段3、4、5也与恢复观察期相关，但存在较多无关故障流程和术语说明噪声。\", \"answerCorrectnessReason\": \"模型回答对\'环境指标\'（温度/湿度异常）的核心答案为20分钟，与标准答案完全一致。额外补充了网关和时钟偏差等其他故障类型的观察时长，属于扩展信息而非错误，语义上关键信息无遗漏。\"}', 25427, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (225, '20260908-235537-d56929be', 'aurora-txt-007', '维护窗口开始前需要核对哪些项目？', '在维护窗口开始前，需要核对以下项目：\n\n*   **审批与准备文件**：确认操作审批单、影响范围、回退包以及联系人信息。\n*   **任务状态**：暂停非关键批任务，并记录基线指标。\n*   **人员与权限**：涉及安全联锁的变更必须由工程师执行，并由另一名工程师复核。', '维护窗口前核对项目清单', '[\"353283812000661505\", \"353283299259580423\", \"353283812000661504\"]', '[\"2\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 2.30248498916626, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79109395}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": 0.34926220774650574, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8144076}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": -1.838321328163147, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.922701}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.8, \"faithfulness\": 0.8, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接切题，列出了维护窗口开始前的若干核对项目，但覆盖面略显不足，未提及通知确认、监控状态、变更内容/脚本工具核对等常见项目。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"回答核心项如审批单、影响范围、回退包、联系人、暂停非关键批任务及安全联锁人员要求均能由上下文支撑；但将记录基线指标和复核要求严格归为“维护窗口开始前”核对项目存在轻微时间/条件推断，未见明显捏造或矛盾。\", \"contextRecallReason\": \"检索上下文中的维护窗口操作清单明确提到窗口开始前需确认审批单、影响范围、回退包和联系人，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2明确涉及维护窗口开始前需核对审批单、回退包、操作人、影响范围、联系人等项目，相关性较高；片段3仅提到维护窗口安排，未直接回答核对项目，且包含较多无关内容，整体为弱相关。\", \"answerCorrectnessReason\": \"模型回答完整涵盖了标准答案中的审批单、影响范围、回退包和联系人等关键信息，同时补充了任务状态、人员与权限等相关准备事项；虽超出标准答案范围，但核心语义基本一致。\"}', 6115, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (226, '20260908-235537-d56929be', 'aurora-txt-008', '维护过程中能否同时修改两个生产区的关键配置？', '在维护过程中，**禁止**在非维护窗口修改关键设备配置。\n\n根据文档规定：\n1.  **常规限制**：明确禁止在非维护窗口修改关键设备配置。固定维护窗口为每周三 02:00 至 03:30。\n2.  **紧急例外**：如果确需紧急操作（即非维护窗口），必须关联 P1 或 P2 事件，并取得当班经理批准。\n\n因此，除非满足“关联 P1/P2 事件”且“获得当班经理批准”这两个严格条件，否则不能同时修改两个生产区的关键配置。此外，执行最小处置原则时，通常建议每次只改变一个条件以缩小故障范围，但在紧急变更流程下，若经批准可执行相关操作。', '维护期间同时修改两个生产环境关键配置的规定', '[\"353283812000661507\", \"353285809898651650\", \"353283812000661506\", \"353283299259580422\", \"353283299259580423\"]', '[\"2\", \"4\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": 0.15700729191303253, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8024714}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": -0.8228467106819153, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.882996}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": -1.0465552806854248, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7952627}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": -1.411542296409607, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.83875}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": -1.9272931814193728, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8553811}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.5, \"faithfulness\": 0.6, \"contextRecall\": 0.1, \"relevancyReason\": \"回答未直接、清晰回应“维护过程中能否同时修改两个生产区关键配置”的核心规则，重点放在非维护窗口限制，虽得出一般不能同时修改的结论，但未明确维护过程/维护窗口内是否允许并发修改及其依据。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 0.3, \"faithfulnessReason\": \"回答引用的多数规则有上下文依据，如禁止非维护窗口修改关键配置、紧急操作需关联P1/P2并经经理批准、固定维护窗口时间，以及故障处置中每次只改变一个条件。但上下文未明确规定维护过程中能否同时修改两个生产区关键配置，也未规定‘同时修改’必须关联P1/P2事件；模型将紧急例外与最小处置原则外推为该场景的直接限制，存在无法完全支撑的推断。\", \"contextRecallReason\": \"上下文涉及维护窗口、关键设备配置修改限制和变更审批，但未明确说明维护过程中不得同时修改两个生产区的关键配置。\", \"contextPrecisionReason\": \"片段1、3、5直接涉及维护窗口、关键设备配置变更、审批与验证回退，片段4涉及两个生产区同时受影响的事件分级，均与问题相关；片段2主要为故障排查流程，仅少量弱相关。\", \"answerCorrectnessReason\": \"模型回答未与标准答案保持明确一致，虽提到‘否则不能同时修改’，但引入紧急例外并暗示特定条件下可执行，且混淆维护过程与非维护窗口，存在明显语义偏差。\"}', 31696, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (227, '20260908-235537-d56929be', 'aurora-txt-009', '如果03:20仍未完成核心验证，应怎么做？', '若 03:20 仍未完成核心验证，应执行回退操作，不得擅自延长维护窗口。', '核心验证03:20未完成应急处理', '[\"353283812000661505\"]', '[\"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 2.642235279083252, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 14.582454}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接明确给出了03:20仍未完成核心验证时应采取的措施，内容切题且完整，无无关信息。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答完全基于上下文中维护窗口操作清单的规定，仅将“窗口”明确为“维护窗口”，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文中明确包含\'若03:20仍未完成核心验证，应执行回退，不得擅自延长窗口\'，与标准答案关键信息完全一致。\", \"contextPrecisionReason\": \"检索上下文中的片段1直接包含与维护窗口操作清单相关的内容，并明确回答：若03:20仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，准确表达了应执行回退且不得擅自延长维护窗口的核心信息。\"}', 30645, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (228, '20260908-235537-d56929be', 'aurora-txt-010', '配置变更后必须检查哪四项结果？', '配置变更后必须检查以下四项结果：\n\n1. **网关心跳**\n2. **事件队列**\n3. **规则计算**\n4. **质量抽样**\n\n任一项失败都视为验证不通过。', '配置变更后必须检查的四项结果', '[\"353283812000661506\", \"353283917827145734\", \"353283812000661508\", \"353283299259580423\"]', '[\"2\", \"3\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 4.358407974243164, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81113696}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": 1.302712082862854, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.807665}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": 0.04846664145588875, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7833879}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": -2.0492780208587646, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8146584}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接列出了配置变更后必须检查的四项结果，回答准确切题且无无关内容。\", \"contextPrecision\": 0.25, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答的四项检查内容以及“任一项失败都视为验证不通过”均来自片段1，与检索上下文完全一致，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文中片段1明确列出配置变更后必须检查网关心跳、事件队列、规则计算和质量抽样四项结果，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"仅片段1明确列出配置变更后必须检查网关心跳、事件队列、规则计算和质量抽样四项结果；其他片段多为审计、临时措施或维护窗口等噪声信息，与问题直接相关性低。\", \"answerCorrectnessReason\": \"模型回答完整列出网关心跳、事件队列、规则计算、质量抽样四项，与标准答案语义完全一致，额外说明不影响核心含义。\"}', 4278, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (229, '20260908-235537-d56929be', 'aurora-txt-011', '连续两次回退失败后如何处置？', '根据参考资料，连续两次回退失败后的处置步骤如下：\n\n1.  **停止操作**：立即终止当前的变更或排障操作。\n2.  **隔离设备**：将受影响的设备进行隔离，防止故障扩大或产生其他风险。\n3.  **升级汇报**：将情况升级给当班经理处理。', '连续两次回退失败处置方法', '[\"353283812000661506\", \"353285809898651651\", \"353283812000661505\", \"353285880643977217\", \"353283917827145732\"]', '[\"2\", \"4\", \"6\", \"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 2.5782673358917236, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.631872}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": -0.08703653514385223, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.580181}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": -0.7319875359535217, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 14.134639}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977217\", \"documentId\": \"6\", \"rerankScore\": -2.3446402549743652, \"chunkContent\": \"﻿事件编号：INC-260802; 发生时间（CST）：2026-08-07 14:20; 严重级别：P3; 资产编号：AU-CM-003; 错误码：E-42; 解决时长（分钟）：55; 根本原因：历史事件未及时归档; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8167187}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145732\", \"documentId\": \"3\", \"rerankScore\": -2.376094341278076, \"chunkContent\": \"## **认证与会话安全**\\n连续二十分钟无操作后会话自动失效。工程师执行配置修改、导出敏感数据或切换设备控制状态前必须重新验证身份。连续五次认证失败时账号锁定三十分钟，并通知安全管理员检查来源。\\n维护终端离开受控区域后不得保持登录状态。操作完成后应主动退出，不能只关闭浏览器窗口。浏览器不得保存园区系统密码，下载的临时文件应在任务完成后按审批要求清理。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.201015}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接给出连续两次回退失败后的停止操作、隔离设备和升级汇报等处置步骤，内容切题且完整。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文中‘连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理’完全一致，额外说明属于合理概括，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确包含连续两次回退失败后应停止操作、隔离受影响设备并升级给当班经理，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"仅片段1直接回答连续两次回退失败后的处置：停止操作、隔离设备并升级当班经理；其他片段多为弱相关或无关噪声。\", \"answerCorrectnessReason\": \"模型回答完整覆盖了标准答案的三个关键处置措施：停止操作、隔离受影响设备、升级给当班经理，语义完全一致。\"}', 25746, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (230, '20260908-235537-d56929be', 'aurora-txt-012', 'P1 确认后多久内通知当班经理和 Blue Heron？', 'P1 事件确认后五分钟内通知当班经理和 Blue Heron。', 'P1故障确认后通知当班经理和Blue Heron的时限要求', '[\"353283812000661506\", \"353283812000661504\", \"353285809898651650\", \"353285809898651653\", \"353283812000661507\"]', '[\"2\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 3.520657539367676, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8052809}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": 1.786856770515442, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 22.68696}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 0.8723869919776917, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 18.498623}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": 0.8723869919776917, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7989139}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": -0.07639407366514206, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7922614}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接准确说明了 P1 事件确认后五分钟内通知，完整回应用户问题，无无关内容。\", \"contextPrecision\": 0.4, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下片段1中“P1 事件确认后五分钟内通知当班经理和 Blue Heron”完全一致，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确说明『P1 事件确认后五分钟内通知当班经理和 Blue Heron』，完整覆盖了标准答案中的时限和通知对象。\", \"contextPrecisionReason\": \"片段1直接回答了P1确认后五分钟内通知当班经理和Blue Heron；片段2仅部分相关；片段3/4只泛泛涉及P1升级和应急协调，未明确通知时限，片段5基本无关，噪声较多。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，核心信息（P1确认后、五分钟内、通知对象为当班经理和Blue Heron）均无遗漏，仅多了一个\'事件\'修饰词，不影响含义。\"}', 24185, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (231, '20260908-235537-d56929be', 'aurora-txt-013', 'P2 事件应多久更新一次进展？', 'P2 事件应每三十分钟更新一次进展。', 'P2事件进展更新频率', '[\"353283812000661506\", \"353285809898651651\", \"353283299259580422\", \"353283812000661508\"]', '[\"2\", \"4\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 0.88388592004776, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7336788}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": -1.1922231912612915, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 7.603807}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": -1.3499674797058103, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.79344845}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -2.1063661575317383, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.75613415}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地回应了用户问题，明确指出了P2事件的进展更新频率，完全切题且无冗余信息。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文明确一致，片段1和片段2均说明P2事件每三十分钟更新一次进展，无捏造或夸大。\", \"contextRecallReason\": \"检索上下文中明确包含『P2 事件每三十分钟更新一次进展』，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2明确说明P2事件每三十分钟更新一次进展，直接相关；片段3仅涉及P2分级和升级时限，未回答更新频率；片段4与问题基本无关。整体约一半上下文相关。\", \"answerCorrectnessReason\": \"模型回答与标准答案完全一致，语义相同，关键信息无遗漏。\"}', 21917, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (232, '20260908-235537-d56929be', 'aurora-txt-014', 'P3 同类事件满足什么条件要发起问题复盘？', '根据参考资料，P3 同类事件满足以下条件时应发起问题复盘：\n\n**同类 P3 事件在七天内出现三次。**', 'P3同类事件发起问题复盘的条件', '[\"353283812000661506\", \"353283299259580428\", \"353283812000661508\", \"353285809898651653\"]', '[\"2\", \"1\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 1.803736686706543, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 14.05405}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580428\", \"documentId\": \"1\", \"rerankScore\": -0.3333789110183716, \"chunkContent\": \"## 恢复验收标准\\n系统恢复至少满足四项条件：受影响区域重新可见，关键设备心跳连续正常，事件队列没有持续增长，抽样规则计算结果正确。仅恢复页面访问不代表生产能力恢复。\\nP1 恢复由当班经理确认，并由 Quality 团队抽样验证；P2 恢复由责任团队确认，值班员复核关键指标；P3 可由处理人确认。恢复后仍需完成规定观察期，观察期内再次出现同类告警时沿用原事件，不重复创建新事件。\\n关闭事件前应撤销临时权限和临时配置，解除设备隔离，恢复暂停的批任务，并确认交接记录已更新。无法立即完成的长期纠正措施应转为问题记录，不能以事件已恢复为由删除后续任务。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77728575}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -0.39009368419647217, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7952068}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": -0.6512930393218994, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.500232}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接准确说明P3同类事件在七天内出现三次即需发起问题复盘，完全切题且完整。\", \"contextPrecision\": 0.75, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答明确指出同类P3事件七天内出现三次应发起问题复盘，直接由片段1和片段4支撑，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文多个片段明确覆盖标准答案关键信息：同类P3事件七天内出现三次时应发起问题复盘。\", \"contextPrecisionReason\": \"四个片段中，片段1、片段3、片段4均直接说明P3同类事件七天内出现三次时需发起或转入问题复盘；片段2主要讲恢复验收与关闭条件，不直接回答复盘条件，因此相关片段约占比0.75。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义一致，均明确指出同类P3事件在七天内出现三次时需发起问题复盘。\"}', 20103, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (233, '20260908-235537-d56929be', 'aurora-txt-015', '工单必须记录哪些核心字段？', '根据规范，工单必须包含以下核心字段：\n\n*   **事件开始时间**\n*   **发现方式**\n*   **影响区域**\n*   **资产编号**\n*   **错误码**\n*   **操作步骤**\n*   **验证结果**\n*   **责任团队**\n\n此外，时间记录需统一使用 CST（UTC+08:00），且禁止仅记录“已处理”或“恢复正常”，严禁粘贴密码、访问令牌和个人身份信息。', '工单核心必填字段要求', '[\"353283812000661506\", \"353283917827145728\", \"353283299259580424\", \"353283812000661508\", \"353283299259580421\"]', '[\"2\", \"3\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 0.14938054978847504, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7546988}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145728\", \"documentId\": \"3\", \"rerankScore\": -1.193291187286377, \"chunkContent\": \"# **补充条款**  \\n## **数据分类与处理要求**\\n园区数据分为公开测试、内部、敏感和受限四级。公开测试数据可用于培训和评测；内部数据仅限园区授权人员使用；敏感数据包括设备配置、详细拓扑和未公开事件记录；受限数据包括真实密码、访问令牌和个人身份信息。受限数据不得进入知识库、工单正文或普通导出文件。\\n文档上传前，责任人必须确认数据级别、保留期限和允许使用范围。无法确定级别时按更高一级保护。测试数据必须明确标注为虚构，不得使用真实人员姓名、电话号码、账号、密码或令牌。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.76596236}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": -1.9512577056884768, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.77850115}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -1.9953217506408691, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.225246}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": -2.4489102363586426, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.74686456}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.85, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出了工单核心字段，基本切题；但附加的时间格式、禁止记录和敏感信息要求属于补充规范，与问题核心略有冗余。\", \"contextPrecision\": 0.4, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答准确复述了片段1中工单记录规范要求的八个核心字段，并基于上下文补充了时间格式和禁止记录内容，未出现捏造、夸大或矛盾。\", \"contextRecallReason\": \"片段1第13条明确列出工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1直接列出工单核心字段，片段5部分涉及工单记录动作与验证；其余片段多为数据分类、导出或告警阈值等噪声。\", \"answerCorrectnessReason\": \"模型回答完整覆盖标准答案中的全部核心字段，语义一致，附加信息未影响关键判断。\"}', 7108, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (234, '20260908-235537-d56929be', 'aurora-txt-016', '交接中的临时配置必须标注什么？', '在交接过程中，临时配置必须标注**负责人**和**失效时间**。', '交接临时配置标注要求', '[\"353283812000661506\", \"353283299259580428\", \"353285809898651653\", \"353283812000661508\", \"353283917827145734\"]', '[\"2\", \"1\", \"4\", \"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 2.596773147583008, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79475236}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580428\", \"documentId\": \"1\", \"rerankScore\": -0.4277817904949188, \"chunkContent\": \"## 恢复验收标准\\n系统恢复至少满足四项条件：受影响区域重新可见，关键设备心跳连续正常，事件队列没有持续增长，抽样规则计算结果正确。仅恢复页面访问不代表生产能力恢复。\\nP1 恢复由当班经理确认，并由 Quality 团队抽样验证；P2 恢复由责任团队确认，值班员复核关键指标；P3 可由处理人确认。恢复后仍需完成规定观察期，观察期内再次出现同类告警时沿用原事件，不重复创建新事件。\\n关闭事件前应撤销临时权限和临时配置，解除设备隔离，恢复暂停的批任务，并确认交接记录已更新。无法立即完成的长期纠正措施应转为问题记录，不能以事件已恢复为由删除后续任务。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.038793}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": -1.3744763135910034, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.310054}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -1.6772476434707642, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7515099}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": -2.116755485534668, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 7.6270323}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接点明临时配置必须标注负责人和失效时间，完整回应问题且无无关内容。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与片段1交接模板中“临时配置必须标注负责人和失效时间”的原文一致，完全有依据。\", \"contextRecallReason\": \"片段1的交接模板明确说明‘临时配置必须标注负责人和失效时间’，完整覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"片段1第14条直接回答了问题（临时配置必须标注负责人和失效时间），高度相关；片段3第九节提及交接记录包含临时配置，部分相关；片段2、4涉及临时配置清理与恢复，弱相关；片段5为审计记录要求，与问题基本无关。5个片段中仅1个直接命中答案，其余为噪声或弱关联，约半数片段含相关上下文。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，均明确指出临时配置必须标注负责人和失效时间，关键信息无遗漏。模型回答仅额外添加了与问题一致的上下文限定和格式强调，不影响语义正确性。\"}', 21204, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (235, '20260908-235537-d56929be', 'aurora-txt-017', '事件队列在归档前能否清空？', '**不能。**\n\n根据故障排查指南中的安全原则及 E-42 事件队列积压的处置规范，明确禁止在未归档前清空事件队列。\n\n具体规定如下：\n1. **通用安全原则**：禁止在未归档前清空队列。\n2. **E-42 处置步骤**：只能归档超过三十天并已完成质量校验的记录，严禁直接清空队列。若归档失败，不得删除源记录。', '事件队列归档前是否支持清空', '[\"353285809898651651\", \"353283812000661507\", \"353283812000661505\"]', '[\"4\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 3.1214754581451416, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78745687}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": 3.0817408561706543, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.807405}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 0.30028456449508667, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 14.779295}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答明确且直接回应了事件队列在归档前不能清空，并提供相关规则依据，切题完整。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确引用安全原则和E-42处置规范，未出现捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"上下文多次明确说明禁止在未归档前清空事件队列，完全覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"片段1和片段2明确包含“禁止在未归档前清空事件队列”的规则，片段3也涉及事件队列归档与E-42处理，因此主要内容相关；但各片段均混入较多其他排障、维护、恢复等无关噪声，故给予较高分但非满分。\", \"answerCorrectnessReason\": \"模型回答与标准答案核心语义一致，均明确表示不能且在未归档前禁止清空事件队列；但来源引用为故障排查指南而非运行手册，细节略有差异。\"}', 22780, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (236, '20260908-235537-d56929be', 'aurora-txt-018', 'P1 事件恢复后多久确定复盘负责人？', 'P1 事件在恢复后二十四小时内确定复盘负责人。', 'P1事件恢复后确定复盘负责人的时间', '[\"353283812000661507\", \"353283812000661506\", \"353283299259580428\", \"353283917827145731\", \"353283299259580425\"]', '[\"2\", \"1\", \"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": 4.732195854187012, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7848746}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 2.2584657669067383, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.67772}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580428\", \"documentId\": \"1\", \"rerankScore\": -0.900396466255188, \"chunkContent\": \"## 恢复验收标准\\n系统恢复至少满足四项条件：受影响区域重新可见，关键设备心跳连续正常，事件队列没有持续增长，抽样规则计算结果正确。仅恢复页面访问不代表生产能力恢复。\\nP1 恢复由当班经理确认，并由 Quality 团队抽样验证；P2 恢复由责任团队确认，值班员复核关键指标；P3 可由处理人确认。恢复后仍需完成规定观察期，观察期内再次出现同类告警时沿用原事件，不重复创建新事件。\\n关闭事件前应撤销临时权限和临时配置，解除设备隔离，恢复暂停的批任务，并确认交接记录已更新。无法立即完成的长期纠正措施应转为问题记录，不能以事件已恢复为由删除后续任务。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8285929}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145731\", \"documentId\": \"3\", \"rerankScore\": -1.0186022520065308, \"chunkContent\": \"## **临时权限与例外**\\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 14.204849}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580425\", \"documentId\": \"1\", \"rerankScore\": -1.0649555921554563, \"chunkContent\": \"## 术语说明\\n- Edge Platform：负责边缘网关和采集服务的团队名称。\\n- Quality：负责质量抽样和结果确认的团队名称。\\n- Blue Heron：P1 事件使用的应急协调组代号。\\n- 恢复时间：从事件确认到核心能力恢复的持续时间。\\n- 观察时间：恢复后继续监控、确认指标稳定的时间。\\n- 隔离设备：为防止影响扩大而暂时停止接入平台的设备。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.944292}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确地回应了问题核心，明确给出了P1事件恢复后确定复盘负责人的时间要求为二十四小时内，无冗余或无关内容。\", \"contextPrecision\": 0.4, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"检索上下文片段1明确说明“P1事件在恢复后二十四小时内确定复盘负责人”，模型回答与上下文完全一致，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确包含“P1 事件在恢复后二十四小时内确定复盘负责人”，完全覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"片段1直接说明 P1 事件恢复后 24 小时内确定复盘负责人，片段2与复盘负责人确定相关但较间接，其余片段主要涉及恢复验收、权限和术语，噪声较多。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，均表明 P1 事件在恢复后二十四小时内确定复盘负责人。\"}', 9266, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (237, '20260908-235537-d56929be', 'aurora-docx-001', 'Operator 角色可以执行哪些操作？', 'Operator 角色可以执行以下操作：\n\n*   **查看实时状态**\n*   **创建工单**\n\n需要注意的是，Operator **不得**修改告警阈值、设备配置或数据保留策略。', 'Operator 角色可执行操作', '[\"353283917827145730\", \"353283917827145741\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145730\", \"documentId\": \"3\", \"rerankScore\": 0.6060853600502014, \"chunkContent\": \"## **角色权限矩阵**\\n操作员可查看实时状态、确认告警和创建工单，不得修改告警阈值、设备配置或数据保留策略。工程师可在已批准的维护窗口内修改设备配置，但操作前必须重新验证身份，并由另一名工程师复核关键变更。审计员只有只读权限，可检查权限、审批和操作证据。数据管理员负责大批量导出审批和保留策略执行，不得代替资源负责人批准设备变更。\\n任何人不得使用他人账号执行操作，也不得为方便值班建立共享账号。发现共享账号后应立即停用，保留审计记录，并由所属团队重新申请实名权限。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7993671}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": -0.07237580418586731, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.73829746}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出了 Operator 可执行的操作，并补充了权限限制，整体切题且较完整，但补充说明与问题核心相比略有冗余。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 0.95, \"faithfulnessReason\": \"回答中查看实时状态、创建工单以及禁止修改告警阈值、设备配置和数据保留策略均有上下文支撑，未引入上下文外信息，也无矛盾。\", \"contextRecallReason\": \"上下文片段1和片段2均完整覆盖标准答案关键信息：Operator/操作员可查看实时状态、可创建工单、不能修改告警阈值。\", \"contextPrecisionReason\": \"两个片段均包含 Operator 可执行操作的直接信息，如查看实时状态、创建工单、不能修改阈值等；但同时也包含较多其他角色和数据策略噪声，因此大部分相关。\", \"answerCorrectnessReason\": \"模型回答准确包含了查看实时状态、创建工单以及不能修改告警阈值等关键信息，与标准答案核心一致；但额外增加了不得修改设备配置或数据保留策略等内容，属于超纲补充，虽无冲突但非完全一致。\"}', 5697, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (238, '20260908-235537-d56929be', 'aurora-docx-002', 'Engineer 在什么条件下可以修改设备配置？', 'Engineer 可以在**已批准的维护窗口内**修改设备配置。\n\n此外，执行此类操作时还需满足以下具体条件：\n1. **身份验证**：操作前必须重新验证身份。\n2. **关键变更复核**：如果是关键变更，必须由另一名工程师进行复核。\n3. **紧急变更例外**：若涉及紧急变更（不受固定窗口限制），必须关联 P1 或 P2 事件，并由当班经理批准。', 'Engineer 角色修改设备配置的权限条件', '[\"353283917827145741\", \"353283917827145730\", \"353283299259580423\"]', '[\"3\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 3.527794361114502, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7916915}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145730\", \"documentId\": \"3\", \"rerankScore\": 3.382215976715088, \"chunkContent\": \"## **角色权限矩阵**\\n操作员可查看实时状态、确认告警和创建工单，不得修改告警阈值、设备配置或数据保留策略。工程师可在已批准的维护窗口内修改设备配置，但操作前必须重新验证身份，并由另一名工程师复核关键变更。审计员只有只读权限，可检查权限、审批和操作证据。数据管理员负责大批量导出审批和保留策略执行，不得代替资源负责人批准设备变更。\\n任何人不得使用他人账号执行操作，也不得为方便值班建立共享账号。发现共享账号后应立即停用，保留审计记录，并由所属团队重新申请实名权限。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8472607}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580423\", \"documentId\": \"1\", \"rerankScore\": -2.2115108966827393, \"chunkContent\": \"## 维护窗口与变更原则\\n每周三 02:00 至 03:30 为固定维护窗口。窗口开始前十五分钟暂停非关键批任务，核对回退包、操作人和审批单。涉及安全联锁的变更必须由 Engineer 执行，并由另一名 Engineer 复核。窗口结束前需恢复暂停任务，检查 A、B、C 三个区域状态，并由 Quality 团队完成抽样校验。\\n紧急变更不受固定窗口限制，但必须关联 P1 或 P2 事件，由当班经理批准，并在二十四小时内补齐变更记录和回退验证。任何临时配置都必须写明失效时间，最长不得超过七天。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.816059}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 0.85, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接、完整地说明了 Engineer 修改设备配置的条件，包括维护窗口、身份验证、关键变更复核和紧急变更例外，未出现无关内容。\", \"contextPrecision\": 0.9, \"answerCorrectness\": 0.6, \"faithfulnessReason\": \"回答核心条件“已批准的维护窗口内修改设备配置”“重新验证身份”“关键变更需另一名工程师复核”均有上下文直接支撑；“紧急变更例外”来自上下文但主要指向一般变更而非明确设备配置，属于少量合理推断。\", \"contextRecallReason\": \"检索上下文明确说明 Engineer/工程师可在已批准的维护窗口内修改设备配置，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2直接说明 Engineer 修改设备配置需处于已批准维护窗口并满足身份验证或复核要求；片段3也涉及维护窗口、安全联锁变更由 Engineer 执行及紧急变更审批，但包含少量与问题关系较弱的流程细节，因此整体高度相关但非完全纯净。\", \"answerCorrectnessReason\": \"回答核心包含“已批准的维护窗口内”，但额外增加身份验证、复核和紧急变更例外，其中“不受固定窗口限制”与标准答案的“只能”存在潜在冲突，可能引入不一致信息。\"}', 5460, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (239, '20260908-235537-d56929be', 'aurora-docx-003', 'Auditor 可以导出多久范围内的审计记录？', 'Auditor 可以导出最近 **90 天**的审计记录。', 'Auditor 审计记录导出时间范围限制', '[\"353283917827145741\", \"353283917827145733\", \"353283299259580424\", \"353283917827145734\", \"353283917827145731\"]', '[\"3\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 2.2865278720855713, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8012055}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145733\", \"documentId\": \"3\", \"rerankScore\": 1.2835779190063477, \"chunkContent\": \"## **数据导出与共享**\\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78746814}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": -1.3941373825073242, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7707695}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": -1.4890927076339722, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.776921}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145731\", \"documentId\": \"3\", \"rerankScore\": -2.4465296268463135, \"chunkContent\": \"## **临时权限与例外**\\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 16.464722}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接且完整地给出了 Auditor 可导出审计记录的时间范围为最近90天，完全切题。\", \"contextPrecision\": 0.2, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"回答与检索上下文中的角色权限描述完全一致，明确支撑 Auditor 可导出最近 90 天的审计记录，无捏造或矛盾。\", \"contextRecallReason\": \"片段1中明确包含\'Auditor 只有只读权限，可以导出最近 90 天的审计记录\'，与标准答案完全一致，所有关键信息均已覆盖。\", \"contextPrecisionReason\": \"仅片段1明确说明Auditor可导出最近90天审计记录，与问题高度相关；其余片段主要涉及数据导出审批、数据质量、审计记录保留365天、临时权限等，对导出范围问题帮助较弱或基本无关。\", \"answerCorrectnessReason\": \"模型回答正确指出了90天的审计记录导出范围，与标准答案核心一致；仅缺少\'只有只读权限\'这一补充说明，但该信息并非问题所问的重点，属于细节略有差异。\"}', 5649, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (240, '20260908-235537-d56929be', 'aurora-docx-004', '原始传感器数据保留多久？', '原始传感器数据保留 **30 天**。', '原始传感器数据保留期限', '[\"353283917827145741\", \"353283299259580424\", \"353283917827145733\", \"353283812000661508\"]', '[\"3\", \"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 4.175658226013184, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8015964}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": 0.0930892452597618, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8099054}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145733\", \"documentId\": \"3\", \"rerankScore\": -0.24688243865966797, \"chunkContent\": \"## **数据导出与共享**\\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 14.732846}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -0.7861343622207642, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.00683}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接准确地给出了原始传感器数据的保留时长，与问题完全切题。\", \"contextPrecision\": 0.25, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答直接来自片段1中明确的原始传感器数据保留30天，完全可由上下文支撑。\", \"contextRecallReason\": \"检索上下文明确指出“原始传感器数据保留 30 天”，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"仅片段1直接回答原始传感器数据保留30天；其他片段主要涉及数据质量、导出审批或事件处理流程，与保留期限仅弱相关或无关。\", \"answerCorrectnessReason\": \"模型回答与标准答案在语义上完全一致，均准确指出原始传感器数据的保留时间为30天，仅使用了Markdown加粗格式，无关键信息遗漏。\"}', 4363, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (241, '20260908-235537-d56929be', 'aurora-docx-005', '小时聚合数据保留多久？', '小时聚合数据保留 18 个月。', '小时聚合数据保留时长', '[\"353283917827145741\", \"353283812000661508\", \"353285847806771225\"]', '[\"3\", \"2\", \"5\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 3.757939577102661, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77700925}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": 0.1665206104516983, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.841947}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771225\", \"documentId\": \"5\", \"rerankScore\": -1.0768612623214722, \"chunkContent\": \"资产编号：AU-DB-091; 资产名称：生产数据主库; 生产区：A区; 子区域：A2; 设备型号：DB-16; 责任团队：数据平台组; 运行状态：运行; 最近巡检日期：2026-08-25; 下次维护时间：2026-09-02 02:00; 维护任务：备份恢复抽查; 维护时长（分钟）：45; 关键等级：关键; 备注：保存生产聚合数据\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.69115}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接且准确地回应了用户关于小时聚合数据保留时长的核心问题，无冗余信息。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"检索上下文片段1明确说明小时聚合数据保留18个月，模型回答与原文一致，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确包含“小时聚合数据保留 18 个月”，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"仅片段1明确回答小时聚合数据保留18个月；片段2和片段3仅提到聚合数据或无关运维内容，未涉及保留时长，噪声较多。\", \"answerCorrectnessReason\": \"模型回答与标准答案完全一致，准确说明小时聚合数据保留18个月。\"}', 4212, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (242, '20260908-235537-d56929be', 'aurora-docx-006', '审计日志保留多久？', '审计日志保留 **365 天**。\n\n在此期间，任何人不得删除、覆盖或修改原始记录。', '审计日志保留时长策略', '[\"353283917827145741\", \"353283917827145734\", \"353283917827145739\", \"353283917827145730\", \"353283917827145736\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 2.907925844192505, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.800882}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": 1.1691228151321411, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81599605}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145739\", \"documentId\": \"3\", \"rerankScore\": -0.14134445786476135, \"chunkContent\": \"## **外部协作与远程支持**\\n外部支持人员不得直接获得长期账号。确需远程支持时，由内部工程师发起临时权限申请，限制目标设备和可执行操作，并全程保留会话审计。远程支持结束后立即撤销权限，不得允许外部人员自行延长。\\n向外部人员提供日志前，应删除真实密码、令牌、个人身份信息和与问题无关的详细拓扑。无法完成脱敏时，只能由内部人员查看原始日志并转述必要结论。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7855259}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145730\", \"documentId\": \"3\", \"rerankScore\": -1.79253089427948, \"chunkContent\": \"## **角色权限矩阵**\\n操作员可查看实时状态、确认告警和创建工单，不得修改告警阈值、设备配置或数据保留策略。工程师可在已批准的维护窗口内修改设备配置，但操作前必须重新验证身份，并由另一名工程师复核关键变更。审计员只有只读权限，可检查权限、审批和操作证据。数据管理员负责大批量导出审批和保留策略执行，不得代替资源负责人批准设备变更。\\n任何人不得使用他人账号执行操作，也不得为方便值班建立共享账号。发现共享账号后应立即停用，保留审计记录，并由所属团队重新申请实名权限。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 16.151274}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145736\", \"documentId\": \"3\", \"rerankScore\": -2.0384016036987305, \"chunkContent\": \"## **策略例行检查**\\n本策略每半年复核一次，系统权限模型、数据保留期限或导出流程发生重大变化时应提前复核。策略变更发布前需完成影响分析、操作培训和历史数据处理确认。所有补充条款均为虚构评测数据，不对应真实系统。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.80473465}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接且准确地给出了审计日志保留时长为365天，完全回应了问题核心。补充的\'不得删除、覆盖或修改原始记录\'信息虽与审计日志高度相关，但并非问题直接所问的内容，属于轻微冗余。\", \"contextPrecision\": 0.4, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答中的审计日志保留365天及不得删除、覆盖或修改原始记录均可在片段1和片段2中直接支撑。\", \"contextRecallReason\": \"检索上下文多个片段明确说明审计日志保留 365 天，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2直接说明审计日志保留365天；其余片段虽涉及审计、权限或数据保留相关背景，但未回答保留时长，属于弱相关或噪声。\", \"answerCorrectnessReason\": \"模型回答与标准答案均明确审计日志保留 365 天，核心语义完全一致；附加说明不冲突。\"}', 3116, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (243, '20260908-235537-d56929be', 'aurora-docx-007', '大批量数据导出需要哪些人审批？', '根据参考资料，大批量数据（超过一万行）导出需要以下两人进行**双人审批**：\n\n1.  **数据管理员**（Data Steward）\n2.  **值班经理**', '大批量数据导出审批人员与审批流程要求', '[\"353283917827145733\", \"353283917827145730\", \"353283299259580424\", \"353283812000661507\", \"353283917827145741\"]', '[\"3\", \"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145733\", \"documentId\": \"3\", \"rerankScore\": 2.6126506328582764, \"chunkContent\": \"## **数据导出与共享**\\n超过一万行的数据导出需要数据管理员和值班经理双人审批。导出申请必须写明字段范围、时间范围、用途、接收人和到期日期。导出结果应使用最少字段，能用聚合数据满足需求时不得导出原始传感器数据。\\n导出文件只能保存在批准的位置，不得上传到公网平台或通过个人通信工具发送。到期后由接收人删除文件并回填删除结果；涉及敏感数据时，由审计员抽查删除证据。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8681456}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145730\", \"documentId\": \"3\", \"rerankScore\": 0.8896299004554749, \"chunkContent\": \"## **角色权限矩阵**\\n操作员可查看实时状态、确认告警和创建工单，不得修改告警阈值、设备配置或数据保留策略。工程师可在已批准的维护窗口内修改设备配置，但操作前必须重新验证身份，并由另一名工程师复核关键变更。审计员只有只读权限，可检查权限、审批和操作证据。数据管理员负责大批量导出审批和保留策略执行，不得代替资源负责人批准设备变更。\\n任何人不得使用他人账号执行操作，也不得为方便值班建立共享账号。发现共享账号后应立即停用，保留审计记录，并由所属团队重新申请实名权限。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 31.124273}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": 0.4635782539844513, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8062091}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": 0.332406222820282, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 24.559881}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 0.04495009779930115, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7699859}]', '{\"mrr\": 0.2, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、准确地指出了大批量数据导出需要的审批人员（数据管理员和值班经理），并补充了相关定义和审批机制，完全切题且无冗余无关内容。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答与上下文一致：多处明确超过一万行数据导出需数据管理员/Data Steward和值班经理双人审批，无捏造或矛盾。\", \"contextRecallReason\": \"上下文多处明确说明超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1、3、5明确说明超过一万行数据导出需Data Steward/数据管理员和值班经理双人审批，片段2补充数据管理员负责大批量导出审批，片段4仅提及不得绕过双人审批且包含较多无关噪声。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，准确说明了超过10,000行数据导出需Data Steward和值班经理双人审批。\"}', 4571, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (244, '20260908-235537-d56929be', 'aurora-docx-008', '工单中禁止粘贴哪些敏感内容？', '根据提供的资料，工单中禁止粘贴以下敏感内容：\n\n*   **真实密码**\n*   **访问令牌**\n*   **个人身份信息**', '工单中禁止粘贴的敏感内容', '[\"353283917827145741\", \"353283917827145735\", \"353283812000661506\", \"353283917827145728\"]', '[\"3\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 0.5608910322189331, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 22.46575}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145735\", \"documentId\": \"3\", \"rerankScore\": 0.10783817619085312, \"chunkContent\": \"## **敏感信息事件处置**\\n发现真实密码或令牌进入工单后，应立即限制工单访问、通知安全管理员、撤销相关凭据并记录处置过程。发现个人身份信息时，应停止继续传播，确认下载和转发范围，并按数据事件流程评估影响。\\n处置完成不代表事件关闭。安全管理员应验证旧凭据已失效、替换凭据已安全分发、缓存和导出副本已清理，并在工单中保留不含敏感值的验证结论。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79553926}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": -0.6761699318885803, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.559961}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145728\", \"documentId\": \"3\", \"rerankScore\": -2.1793177127838135, \"chunkContent\": \"# **补充条款**  \\n## **数据分类与处理要求**\\n园区数据分为公开测试、内部、敏感和受限四级。公开测试数据可用于培训和评测；内部数据仅限园区授权人员使用；敏感数据包括设备配置、详细拓扑和未公开事件记录；受限数据包括真实密码、访问令牌和个人身份信息。受限数据不得进入知识库、工单正文或普通导出文件。\\n文档上传前，责任人必须确认数据级别、保留期限和允许使用范围。无法确定级别时按更高一级保护。测试数据必须明确标注为虚构，不得使用真实人员姓名、电话号码、账号、密码或令牌。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.80239105}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出了工单中禁止粘贴的敏感内容，完全切题且准确回应问题核心。\", \"contextPrecision\": 0.9, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答准确列出了上下文中明确禁止在工单粘贴的真实密码、访问令牌和个人身份信息，完全可由检索上下文支撑，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文明确包含禁止在工单中粘贴真实密码、访问令牌或个人身份信息，关键信息完全覆盖。\", \"contextPrecisionReason\": \"四个片段均涉及工单中禁止粘贴真实密码、访问令牌和个人身份信息，整体相关度高；片段1和片段3含少量无关管理流程，片段2为处置延伸内容。\", \"answerCorrectnessReason\": \"模型回答与标准答案在语义上完全一致，准确列出了禁止粘贴的真实密码、访问令牌和个人身份信息，关键信息无遗漏。\"}', 25758, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (245, '20260908-235537-d56929be', 'aurora-docx-009', '会话连续多久无操作后自动失效？', '根据提供的资料，会话在连续 **20 分钟**无操作后会自动失效。\n\n此外，Engineer（工程师）在执行配置修改、导出敏感数据或切换设备控制状态前，也必须重新验证身份。', '会话空闲超时失效时长', '[\"353283917827145741\", \"353283917827145732\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 0.9291202425956726, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7209069}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145732\", \"documentId\": \"3\", \"rerankScore\": -0.4216310381889343, \"chunkContent\": \"## **认证与会话安全**\\n连续二十分钟无操作后会话自动失效。工程师执行配置修改、导出敏感数据或切换设备控制状态前必须重新验证身份。连续五次认证失败时账号锁定三十分钟，并通知安全管理员检查来源。\\n维护终端离开受控区域后不得保持登录状态。操作完成后应主动退出，不能只关闭浏览器窗口。浏览器不得保存园区系统密码，下载的临时文件应在任务完成后按审批要求清理。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7898059}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.85, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"核心答案直接完整，明确给出了 20 分钟；后半句工程师重新验证身份属于额外信息，与问题相关性较低，造成冗余。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答中的20分钟无操作失效以及工程师执行配置修改、导出敏感数据或切换设备控制状态前需重新验证身份，均能由检索上下文直接支撑，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文片段1和片段2均明确包含标准答案的关键信息：会话连续20分钟（二十分钟）无操作后自动失效。\", \"contextPrecisionReason\": \"两个检索片段都明确回答了会话在无操作20分钟后自动失效，与用户问题高度相关。\", \"answerCorrectnessReason\": \"模型回答的核心信息\'20分钟\'与标准答案完全一致，语义准确无遗漏。额外补充的工程师重新验证身份信息属于相关补充说明，不影响核心答案的正确性。\"}', 19330, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (246, '20260908-235537-d56929be', 'aurora-docx-010', 'Engineer 修改配置前还需要什么身份步骤？', '根据参考资料，Engineer 在修改配置前还需要完成以下身份步骤：\n\n1.  **重新验证身份**：由于连续 20 分钟无操作后会话会自动失效，且规定明确指出 Engineer 执行配置修改前必须重新验证身份。\n2.  **关键变更复核**：如果涉及关键变更，还需要由另一名工程师进行复核。', 'Engineer 修改配置的身份验证步骤', '[\"353283917827145741\", \"353283917827145732\", \"353283812000661506\", \"353283917827145730\"]', '[\"3\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": 2.0165212154388428, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7415264}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145732\", \"documentId\": \"3\", \"rerankScore\": 1.9759418964385984, \"chunkContent\": \"## **认证与会话安全**\\n连续二十分钟无操作后会话自动失效。工程师执行配置修改、导出敏感数据或切换设备控制状态前必须重新验证身份。连续五次认证失败时账号锁定三十分钟，并通知安全管理员检查来源。\\n维护终端离开受控区域后不得保持登录状态。操作完成后应主动退出，不能只关闭浏览器窗口。浏览器不得保存园区系统密码，下载的临时文件应在任务完成后按审批要求清理。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7618724}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 0.18560196459293363, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.74042124}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145730\", \"documentId\": \"3\", \"rerankScore\": -0.03716271743178368, \"chunkContent\": \"## **角色权限矩阵**\\n操作员可查看实时状态、确认告警和创建工单，不得修改告警阈值、设备配置或数据保留策略。工程师可在已批准的维护窗口内修改设备配置，但操作前必须重新验证身份，并由另一名工程师复核关键变更。审计员只有只读权限，可检查权限、审批和操作证据。数据管理员负责大批量导出审批和保留策略执行，不得代替资源负责人批准设备变更。\\n任何人不得使用他人账号执行操作，也不得为方便值班建立共享账号。发现共享账号后应立即停用，保留审计记录，并由所属团队重新申请实名权限。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7594441}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.8, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答核心切题，指出了修改配置前需重新验证身份；但‘关键变更复核’属于变更控制步骤而非严格意义的身份步骤，存在一定冗余和偏题。\", \"contextPrecision\": 0.75, \"answerCorrectness\": 0.8, \"faithfulnessReason\": \"回答中的重新验证身份和关键变更由另一名工程师复核均可由上下文直接支撑，无捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"上下文片段1、2、4均明确说明工程师执行配置修改前必须重新验证身份，完整覆盖标准答案。\", \"contextPrecisionReason\": \"片段1、2、4明确说明Engineer/工程师在修改配置前必须重新验证身份，直接回答用户问题；片段3主要涉及变更验证、回退和事件升级，与身份步骤无关。\", \"answerCorrectnessReason\": \"核心信息\'重新验证身份\'完全正确，与标准答案语义一致。但模型额外添加了\'关键变更复核\'，这属于变更流程步骤而非\'身份步骤\'，稍有冗余但不构成错误。\"}', 18951, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (247, '20260908-235537-d56929be', 'aurora-docx-011', '园区数据分为哪四级？', '园区数据分为以下四级：\n\n1. **公开测试**：可用于培训和评测。\n2. **内部**：仅限园区授权人员使用。\n3. **敏感**：包括设备配置、详细拓扑和未公开事件记录。\n4. **受限**：包括真实密码、访问令牌和个人身份信息（此类数据不得进入知识库、工单正文或普通导出文件）。', '园区数据四级分类', '[\"353283917827145728\", \"353283299259580420\", \"353283299259580422\"]', '[\"3\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145728\", \"documentId\": \"3\", \"rerankScore\": 5.051570892333984, \"chunkContent\": \"# **补充条款**  \\n## **数据分类与处理要求**\\n园区数据分为公开测试、内部、敏感和受限四级。公开测试数据可用于培训和评测；内部数据仅限园区授权人员使用；敏感数据包括设备配置、详细拓扑和未公开事件记录；受限数据包括真实密码、访问令牌和个人身份信息。受限数据不得进入知识库、工单正文或普通导出文件。\\n文档上传前，责任人必须确认数据级别、保留期限和允许使用范围。无法确定级别时按更高一级保护。测试数据必须明确标注为虚构，不得使用真实人员姓名、电话号码、账号、密码或令牌。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81117785}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580420\", \"documentId\": \"1\", \"rerankScore\": -1.4784903526306152, \"chunkContent\": \"## 园区区域与系统组成\\n园区按生产职责划分为三个区域。A 区负责来料检测与能源分配，B 区负责精密加工与环境控制，C 区负责装配、视觉质检和成品暂存。区域下设 A1、A2、B1、B2、C1、C2 六个子区域，子区域编号只用于定位，不改变事件级别。\\n每个子区域至少部署一台环境传感器，关键产线通过 HG-220 边缘网关接入。网关每分钟上报一次心跳，每五分钟汇总一次设备状态。连续丢失三次心跳定义为通信异常，但处置前必须先排除交换机维护、链路抖动和时间同步问题。\\n园区平台由设备采集、事件队列、规则计算、质量校验和报表归档五项能力组成。设备采集负责接收现场数据；事件队列负责削峰；规则计算负责生成告警；质量校验负责识别缺失值和异常值；报表归档负责保存经审批的统计结果。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7717613}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": -2.3103983402252197, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7418188}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出了园区数据的四级分类，内容完整且紧扣问题核心。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答与检索上下文片段1完全一致，准确列出四级及相应定义与限制，无捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"检索上下文片段1明确写出园区数据分为公开测试、内部、敏感和受限四级，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"仅片段1直接说明园区数据四级分类，片段2和3与问题无关，相关片段比例低。\", \"answerCorrectnessReason\": \"模型回答完整且准确地列出了标准答案中的四级：公开测试、内部、敏感和受限，附加说明未改变核心语义。\"}', 20623, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (248, '20260908-235537-d56929be', 'aurora-docx-012', '谁可以批准临时权限例外？', '临时权限例外必须由**资源负责人**和**安全管理员**共同批准。\n\n在申请时，需明确写明事由、资源范围、操作权限以及失效时间。此外，临时权限的最长有效期为七天，到期自动失效；若确需延长，必须重新进行审批，不得直接修改原申请的到期时间。', '临时权限例外审批权限归属', '[\"353283917827145731\", \"353283917827145734\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145731\", \"documentId\": \"3\", \"rerankScore\": 3.0688068866729736, \"chunkContent\": \"## **临时权限与例外**\\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.87666225}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": -2.224318265914917, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77424896}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接说明了批准人为资源负责人和安全管理员，完全切题，但包含较多未问到的申请与有效期信息，略有冗余。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答的核心内容与检索上下文片段1完全一致，所有关键信息均可由上下文支撑，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确说明临时权限例外必须由资源负责人和安全管理员共同批准，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1直接回答临时权限例外由资源负责人和安全管理员共同批准，高度相关；片段2涉及临时权限审计复核，与问题有一定关联但未直接说明批准人，属于弱相关。\", \"answerCorrectnessReason\": \"模型回答与标准答案核心语义完全一致，均明确临时权限例外需由资源负责人和安全管理员共同批准，额外补充信息未造成关键信息遗漏或冲突。\"}', 6615, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (249, '20260908-235537-d56929be', 'aurora-docx-013', '临时权限最长有效期是多少？', '临时权限的最长有效期为**七天**。\n\n到期后权限会自动失效；如果确需延长，必须重新进行审批，严禁直接修改原申请的到期时间。', '临时权限最长有效期', '[\"353283917827145731\", \"353283812000661508\"]', '[\"3\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145731\", \"documentId\": \"3\", \"rerankScore\": 5.314712047576904, \"chunkContent\": \"## **临时权限与例外**\\n临时权限例外必须由资源负责人和安全管理员共同批准，申请中写明事由、资源范围、操作权限和失效时间。临时权限最长有效期为七天，到期自动失效；确需延长时必须重新审批，不得修改原申请的到期时间。\\n紧急情况下可先为处理 P1 事件授予最小必要权限，但应记录事件编号，并在四小时内补齐审批。事件恢复后两小时内撤销紧急权限，由审计员核对实际操作是否超出范围。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8693725}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -2.2541751861572266, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.843143}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接回答了最长有效期为七天，后续说明略有扩展但整体仍与问题相关。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答中的临时权限最长有效期七天、到期自动失效、延长需重新审批且不得修改原到期时间，均直接来自片段1，无捏造或矛盾。\", \"contextRecallReason\": \"上下文片段1明确包含标准答案关键信息：临时权限最长有效期为七天。\", \"contextPrecisionReason\": \"片段1直接给出临时权限最长有效期为七天；片段2仅少量提到临时权限清理，其余多为无关噪声。\", \"answerCorrectnessReason\": \"模型回答的核心信息\'临时权限最长有效期为七天\'与标准答案完全一致，额外补充的到期失效和审批延长规则属于有效扩展，未影响语义一致性。\"}', 4385, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (250, '20260908-235537-d56929be', 'aurora-docx-014', '审计记录至少应包含哪些信息？', '审计记录至少应包含以下信息：\n\n*   **基础要素**：操作人、时间、对象、动作、结果和来源地址。\n*   **配置变更专项**：如果涉及配置变更，还应记录变更前后差异、审批单号和验证结果。', '审计记录包含的信息内容要求', '[\"353283917827145734\", \"353283299259580424\", \"353283917827145741\"]', '[\"3\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": 4.442867755889893, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7782428}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": -0.6250388026237488, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7689483}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": -1.3644033670425415, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 19.301191}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 0.8, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答基本切题，列出了操作人、时间、对象、动作、结果、来源地址等审计记录常见核心信息；但遗漏了事件类型、系统/终端标识、审计记录唯一标识等部分通用要素，且配置变更专项属于补充内容，略有冗余。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于片段1的审计记录要求，列出了操作人、时间、对象、动作、结果、来源地址以及配置变更需记录的内容，无捏造或与上下文矛盾。\", \"contextRecallReason\": \"片段1完整包含标准答案中的操作人、时间、对象、动作、结果和来源地址等关键信息。\", \"contextPrecisionReason\": \"片段1直接回答审计记录应包含的信息，片段3仅弱相关，片段2基本无关，整体约一半相关。\", \"answerCorrectnessReason\": \"模型回答完整包含标准答案中的全部关键信息，额外补充内容不与标准答案冲突。\"}', 22312, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (251, '20260908-235537-d56929be', 'aurora-docx-015', '权限复核的固定频率是什么？', '系统负责人**每季度**执行一次权限复核。', '权限复核固定频率要求', '[\"353283917827145734\", \"353283917827145736\"]', '[\"3\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145734\", \"documentId\": \"3\", \"rerankScore\": 0.7885927557945251, \"chunkContent\": \"## **审计记录要求**\\n审计记录至少应包含操作人、时间、对象、动作、结果和来源地址。配置变更还应记录变更前后差异、审批单号和验证结果。审计日志保留三百六十五天，任何人不得删除、覆盖或修改原始记录。\\n系统负责人每季度执行一次权限复核，重点检查离岗人员、长期未使用账号、临时权限和高权限角色。复核发现的不必要权限应在两个工作日内撤销，无法按时处理时必须登记例外原因和完成日期。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.83791614}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145736\", \"documentId\": \"3\", \"rerankScore\": -0.4976576566696167, \"chunkContent\": \"## **策略例行检查**\\n本策略每半年复核一次，系统权限模型、数据保留期限或导出流程发生重大变化时应提前复核。策略变更发布前需完成影响分析、操作培训和历史数据处理确认。所有补充条款均为虚构评测数据，不对应真实系统。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.84386146}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接明确给出权限复核频率为每季度一次，完全切题；补充说明执行主体略有冗余但不影响核心回答完整性。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与上下文片段1完全一致，明确指出系统负责人每季度执行一次权限复核，无捏造或矛盾。\", \"contextRecallReason\": \"上下文片段1完整包含标准答案关键信息：系统负责人每季度执行一次权限复核。\", \"contextPrecisionReason\": \"片段1明确说明系统负责人每季度执行权限复核，与问题高度相关；片段2讲的是策略例行检查每半年复核，与权限复核固定频率无关。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，关键信息（系统负责人、每季度执行一次权限复核）无遗漏，仅使用加粗标记进行强调，不影响含义。\"}', 4206, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (252, '20260908-235537-d56929be', 'aurora-docx-016', '发现真实令牌进入工单后应如何处理？', '发现真实令牌进入工单后，应按以下流程处理：\n\n1.  **立即限制访问与通知**：立即限制该工单的访问权限，并通知安全管理员。\n2.  **撤销凭据**：撤销相关的访问令牌（即相关凭据）。\n3.  **记录处置过程**：详细记录整个处置过程。\n4.  **验证与清理**：\n    *   安全管理员需验证旧凭据已失效。\n    *   确认替换的新凭据已安全分发。\n    *   清理缓存和导出副本中的敏感数据。\n5.  **更新工单结论**：在工单中保留不含敏感值的验证结论。\n\n此外，需注意受限数据（包括真实密码、访问令牌和个人身份信息）不得进入知识库、工单正文或普通导出文件。处置完成不代表事件关闭，必须确保上述所有验证步骤均已完成。', '真实令牌进入工单后的处理流程', '[\"353283917827145735\", \"353283917827145728\", \"353283812000661506\", \"353283917827145741\", \"353285809898651653\"]', '[\"3\", \"2\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145735\", \"documentId\": \"3\", \"rerankScore\": 5.602774143218994, \"chunkContent\": \"## **敏感信息事件处置**\\n发现真实密码或令牌进入工单后，应立即限制工单访问、通知安全管理员、撤销相关凭据并记录处置过程。发现个人身份信息时，应停止继续传播，确认下载和转发范围，并按数据事件流程评估影响。\\n处置完成不代表事件关闭。安全管理员应验证旧凭据已失效、替换凭据已安全分发、缓存和导出副本已清理，并在工单中保留不含敏感值的验证结论。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8010101}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145728\", \"documentId\": \"3\", \"rerankScore\": -0.47562506794929504, \"chunkContent\": \"# **补充条款**  \\n## **数据分类与处理要求**\\n园区数据分为公开测试、内部、敏感和受限四级。公开测试数据可用于培训和评测；内部数据仅限园区授权人员使用；敏感数据包括设备配置、详细拓扑和未公开事件记录；受限数据包括真实密码、访问令牌和个人身份信息。受限数据不得进入知识库、工单正文或普通导出文件。\\n文档上传前，责任人必须确认数据级别、保留期限和允许使用范围。无法确定级别时按更高一级保护。测试数据必须明确标注为虚构，不得使用真实人员姓名、电话号码、账号、密码或令牌。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7554035}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": -0.8962260484695435, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.76080626}, {\"url\": \"http://127.0.0.1:9090/know-engine/03_曙光智造园区访问与数据安全策略.docx\", \"chunkId\": \"353283917827145741\", \"documentId\": \"3\", \"rerankScore\": -1.5707887411117554, \"chunkContent\": \"**曙光智造园区访问与数据策略**\\n文档版本：3.1；生效日期：2026-08-05。本文件全部内容均为虚构测试数据。\\n**角色权限**\\nOperator 可以查看实时状态并创建工单，但不能修改告警阈值。\\nEngineer 可以在已批准的维护窗口内修改设备配置。\\nAuditor 只有只读权限，可以导出最近 90 天的审计记录。\\n**数据保留**\\n原始传感器数据保留 30 天，小时聚合数据保留 18 个月，审计日志保留 365 天。\\n**导出与审批**\\n超过 10,000 行的数据导出需要 Data Steward 和值班经理双人审批。\\n禁止在工单中粘贴真实密码、访问令牌或个人身份信息。\\n**会话要求**\\n连续 20 分钟无操作后会话自动失效。Engineer 执行配置修改前必须重新验证身份。\", \"documentTitle\": \"03_曙光智造园区访问与数据安全策略\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 16.087423}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": -1.8916265964508057, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.788956}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 1.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答完全切题，直接给出了发现真实令牌进入工单后的完整处理流程（限制访问、撤销凭据、记录、验证清理、更新结论），并补充了注意事项，所有内容与问题核心高度相关，无无关信息。\", \"contextPrecision\": 0.3, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答中的处置步骤、禁止项和验证清理要求均可由片段1、片段2/4直接支撑；对‘相关凭据’指代访问令牌属于上下文内的合理表述，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文中片段1明确覆盖标准答案全部关键信息：发现真实令牌进入工单后应立即限制工单访问、通知安全管理员、撤销相关凭据并记录处置过程。\", \"contextPrecisionReason\": \"仅片段1直接回答发现真实令牌进入工单后的处置流程；片段2提供受限数据不得进入工单的相关政策依据。其余片段主要包含变更验证、事件通知、权限、数据保留和故障排查等内容，仅零散提到禁止粘贴令牌，与具体处置问题相关性较低。\", \"answerCorrectnessReason\": \"模型回答完整覆盖标准答案的四个关键动作：限制工单访问、通知安全管理员、撤销令牌、记录处置过程，语义完全一致且无遗漏；额外补充的验证清理与结论更新步骤为合理扩展，不与标准答案矛盾。\"}', 25559, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (253, '20260908-235537-d56929be', 'aurora-pdf-001', '处理故障前应先确认哪些基本信息？', '在处理故障前，应确认以下基本信息：\n\n*   **影响区域**：明确故障波及的具体生产区或范围。\n*   **资产编号**：记录受影响设备或组件的唯一标识。\n*   **错误码**：获取具体的故障代码（如 E-17、E-42 等）。\n*   **告警开始时间**：记录首次发生的时间点。\n*   **当前维护状态**：了解系统或设备当前的运行及维护情况。', '故障处理前需确认的基本信息', '[\"353285809898651650\", \"353283812000661507\"]', '[\"4\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 0.2684571444988251, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7745486}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": -1.1764286756515503, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7759535}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出处理故障前应确认的基本信息，与问题高度相关且无明显冗余；但可能遗漏故障现象、相关变更/操作等常见信息，因此略有不足。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完整对应上下文片段1中“处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态”的要求，错误码示例 E-17、E-42 也在上下文中出现，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文完整覆盖标准答案，明确列出影响区域、资产编号、错误码、告警开始时间和当前维护状态。\", \"contextPrecisionReason\": \"片段1明确给出处理故障前应确认影响区域、资产编号、错误码、告警开始时间和维护状态，高度相关；片段2主要涉及操作禁止项、依赖检查、降级和验收，仅部分弱相关，噪声较多。\", \"answerCorrectnessReason\": \"模型回答完整覆盖标准答案的关键信息：影响区域、资产编号、错误码、告警开始时间和当前维护状态，语义一致且无遗漏。\"}', 19721, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (254, '20260908-235537-d56929be', 'aurora-pdf-002', 'E-17 表示什么问题？', 'E-17 表示设备时钟偏差超过九十秒。\n\n常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。这种偏差会导致事件排序错误和重复数据，因此必须先校正时间再恢复采集。', 'E-17 含义说明', '[\"353285809898651651\", \"353285880643977237\", \"353285880643977216\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 3.290595054626465, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77640176}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977237\", \"documentId\": \"6\", \"rerankScore\": 0.6684402227401733, \"chunkContent\": \"﻿事件编号：INC-260822; 发生时间（CST）：2026-08-28 04:06; 严重级别：P2; 资产编号：AU-GW-003; 错误码：E-17; 解决时长（分钟）：41; 根本原因：时间服务器切换失败; 处置摘要：切换备用时间源并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7378506}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 0.6423681378364563, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7303717}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.3333333333333333}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接说明E-17表示设备时钟偏差超过九十秒，准确切题；但附加的常见原因和处置建议略超出问题范围，存在轻微冗余。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文片段1中关于 E-17 含义、常见原因及影响的表述完全一致，没有捏造或夸大内容。\", \"contextRecallReason\": \"检索上下文明确指出 E-17 表示设备时钟偏差超过九十秒，与标准答案的关键信息完全一致。\", \"contextPrecisionReason\": \"片段1直接回答E-17的含义，片段2和片段3为E-17相关事件记录，属于弱相关或冗余。\", \"answerCorrectnessReason\": \"核心语义完全一致。\'九十秒\'与\'90秒\'为同义表述，关键信息无任何遗漏。模型还补充了常见原因和处理建议，属于有价值的额外信息，不影响答案正确性。\"}', 21188, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (255, '20260908-235537-d56929be', 'aurora-pdf-003', 'E-17 的首要处置动作是什么？', 'E-17（设备时钟偏差超过九十秒）的首要处置动作是**检查园区时间服务是否可达，并确认其他设备是否同时异常**。\n\n在确认现象后，具体的处置流程如下：\n1.  **检查时间服务**：确认园区时间服务是否可达，并观察其他设备是否存在同样的异常。\n2.  **查看状态**：查看故障设备的当前时间、时区以及最后同步时间。\n3.  **执行同步**：在确认时间源正常后，执行 NTP 同步。\n4.  **重启进程**：重启 Edge Collector 采集进程，使其重新建立带正确时间戳的连接。\n\n**注意**：严禁重启 HG-220 网关，因为重启会扩大采集中断且不能替代时间校正。', 'E-17首要处置动作', '[\"353285809898651650\", \"353285880643977216\", \"353285880643977237\", \"353283299259580421\", \"353283812000661505\"]', '[\"4\", \"6\", \"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.244800567626953, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.76364386}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 1.2014832496643066, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.413168}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977237\", \"documentId\": \"6\", \"rerankScore\": 1.0500476360321045, \"chunkContent\": \"﻿事件编号：INC-260822; 发生时间（CST）：2026-08-28 04:06; 严重级别：P2; 资产编号：AU-GW-003; 错误码：E-17; 解决时长（分钟）：41; 根本原因：时间服务器切换失败; 处置摘要：切换备用时间源并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.302438}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 0.5871593356132507, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.8375225}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": -1.8768483400344849, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7512258}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.8, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接指出 E-17 的首要处置动作，核心切题；但补充了较多后续流程，存在一定冗余，且将首要动作扩展为两项，略影响精炼度。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 0.8, \"faithfulnessReason\": \"回答的首要处置动作、后续步骤及禁止事项均可在上下文的 E-17 处置步骤中找到直接支撑，未引入上下文外事实。\", \"contextRecallReason\": \"上下文片段1明确给出E-17处置步骤：先检查时间服务/时间源是否可达，确认时间源正常后执行NTP同步，再重启Edge Collector采集进程，完整覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"片段1直接回答E-17首要处置动作；片段2-4仅与E-17案例或阈值背景相关，片段5基本无关。\", \"answerCorrectnessReason\": \"模型回答涵盖了确认时间源可用、执行NTP同步和重启Edge Collector等关键处置动作，语义基本一致；但其将“确认其他设备是否同时异常”纳入首要动作，并补充了其他细节，与标准答案表述略有差异。\"}', 20984, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (256, '20260908-235537-d56929be', 'aurora-pdf-004', '处理 E-17 时为什么禁止重启 HG-220？', '在处理 E-17（时钟偏差故障）时，禁止重启 HG-220 网关的主要原因如下：\n\n1.  **扩大采集中断**：重启网关会导致数据采集进一步中断，影响生产数据的连续性。\n2.  **无法解决根本问题**：E-17 的根本原因是时间同步异常，重启网关不能替代正确的时间校正操作。\n\n正确的处置方式应是先确认时间源正常并执行 NTP 同步，随后重启 Edge Collector 采集进程以重新建立带正确时间戳的连接。', 'E-17 处理时禁止重启 HG-220 的原因', '[\"353285809898651651\", \"353285809898651650\", \"353285880643977216\", \"353285880643977237\", \"353283812000661505\"]', '[\"4\", \"6\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 2.6562490463256836, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7921072}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.6562490463256836, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.881406}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": 0.9319261908531188, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.484805}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977237\", \"documentId\": \"6\", \"rerankScore\": 0.8785997033119202, \"chunkContent\": \"﻿事件编号：INC-260822; 发生时间（CST）：2026-08-28 04:06; 严重级别：P2; 资产编号：AU-GW-003; 错误码：E-17; 解决时长（分钟）：41; 根本原因：时间服务器切换失败; 处置摘要：切换备用时间源并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.324919}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": -0.7875174880027771, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.78895676}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 0.8, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接说明了禁止重启 HG-220 的主要原因，内容切题且较完整，但包含少量未直接要求正确处置步骤的冗余信息。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答主要依据上下文中‘不得重启 HG-220 网关，因为重启会扩大采集中断，且不能替代时间校正’，并引用了 NTP 同步和重启 Edge Collector 的正确处置步骤。存在轻微过度概括，将 E-17 直接说成‘根本原因是时间同步异常’，上下文表述为常见原因；‘影响生产数据连续性’也属合理推断。\", \"contextRecallReason\": \"上下文片段1和2明确说明E-17是设备时钟偏差/时钟同步问题，且规定不得重启HG-220网关，因为重启会扩大采集中断且不能替代时间校正，完全覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2直接说明E-17时不得重启HG-220的原因，但片段2为重复内容；片段3、4仅涉及E-17事件记录，片段5涉及HG-220网关但主要不是解释E-17处置，整体相关约一半，噪声较多。\", \"answerCorrectnessReason\": \"模型回答准确指出E-17为时钟同步/时间校正问题，并说明重启网关会扩大采集中断且不能替代时间校正，与标准答案语义一致，补充内容未造成偏差。\"}', 23106, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (257, '20260908-235537-d56929be', 'aurora-pdf-005', 'E-17 处置完成后如何验证？', 'E-17（时钟偏差故障）处置完成后，需同时满足以下指标方可验证通过：\n\n1.  **时钟偏差**：设备时钟偏差低于三十秒。\n2.  **数据连续性**：新采集记录时间连续且顺序正确。\n3.  **告警观察**：连续观察十五分钟无新的 E-17 告警。\n\n若同步后偏差仍超过九十秒，应保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。', 'E-17 处置完成后验证方法', '[\"353285809898651651\", \"353283299259580421\", \"353285880643977216\", \"353283812000661506\", \"353283812000661505\"]', '[\"4\", \"1\", \"6\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 3.028696775436402, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79748}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 1.1087218523025513, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.736062}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977216\", \"documentId\": \"6\", \"rerankScore\": -0.1906977891921997, \"chunkContent\": \"﻿事件编号：INC-260801; 发生时间（CST）：2026-08-03 09:14; 严重级别：P2; 资产编号：AU-GW-001; 错误码：E-17; 解决时长（分钟）：38; 根本原因：时钟同步服务异常; 处置摘要：同步时间并重启采集进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.998649}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": -1.5259746313095093, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.633014}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": -2.4178593158721924, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.411982}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接给出 E-17 处置完成后的验证标准，包括时钟偏差、数据连续性和告警观察，内容切题且完整。\", \"contextPrecision\": 0.4, \"answerCorrectness\": 0.85, \"faithfulnessReason\": \"回答中的三项验证标准以及同步后偏差仍超过九十秒时的处理建议均直接来自检索上下文中关于E-17的说明，未引入额外或矛盾信息。\", \"contextRecallReason\": \"检索上下文片段1明确给出 E-17 验证标准：设备时钟偏差低于三十秒，并连续观察十五分钟无新的 E-17 告警，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1直接给出E-17验证标准，片段2含E-17校正后观察要求；片段3仅记录E-17事件且无验证细节，片段4和5基本无关。\", \"answerCorrectnessReason\": \"模型回答包含标准答案的核心验证条件：时钟偏差低于30秒、连续观察15分钟无新告警；但额外增加了数据连续性等验证要求，细节上略有扩展。\"}', 22874, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (258, '20260908-235537-d56929be', 'aurora-pdf-006', 'E-42 表示什么问题？', 'E-42 表示**事件队列积压**，具体指事件队列记录数超过五万条。\n\n常见原因包括：\n*   消费进程停滞\n*   下游存储变慢\n*   历史记录未归档\n*   规则计算异常重试\n\n队列积压会导致告警延迟，但严禁通过直接清空队列来恢复。', 'E-42 错误代码含义说明', '[\"353285880643977217\", \"353285809898651651\", \"353285880643977231\"]', '[\"6\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977217\", \"documentId\": \"6\", \"rerankScore\": 2.514707565307617, \"chunkContent\": \"﻿事件编号：INC-260802; 发生时间（CST）：2026-08-07 14:20; 严重级别：P3; 资产编号：AU-CM-003; 错误码：E-42; 解决时长（分钟）：55; 根本原因：历史事件未及时归档; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8511511}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 2.511446475982666, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8236519}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977231\", \"documentId\": \"6\", \"rerankScore\": 2.3493998050689697, \"chunkContent\": \"﻿事件编号：INC-260816; 发生时间（CST）：2026-08-25 12:26; 严重级别：P2; 资产编号：AU-GW-002; 错误码：E-42; 解决时长（分钟）：49; 根本原因：事件消费进程停滞; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8511505}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接说明 E-42 表示事件队列积压及判定条件，基本完整；但补充了原因和处置禁忌，略超出问题范围。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答关于 E-42 的定义、阈值、常见原因及处置限制均直接来自检索上下文，无捏造或矛盾。\", \"contextRecallReason\": \"上下文片段2明确指出 E-42 表示事件队列记录数超过五万条，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段2直接说明E-42表示事件队列积压，片段1和3也涉及E-42但仅为案例记录，整体相关但存在冗余与噪声。\", \"answerCorrectnessReason\": \"模型回答准确指出 E-42 表示事件队列记录数超过五万条，与标准答案语义完全一致；补充信息未与标准答案冲突。\"}', 22512, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (259, '20260908-235537-d56929be', 'aurora-pdf-007', 'E-42 归档记录的时间条件是什么？', '根据参考资料，E-42 归档记录的时间条件是：**只归档超过三十天**并已完成质量校验的记录。\n\n此外，严禁归档三十天以内的活跃事件。', 'E-42 归档记录时间条件', '[\"353285809898651651\", \"353283299259580421\", \"353283812000661505\", \"353285880643977217\", \"353285880643977231\"]', '[\"4\", \"1\", \"2\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 1.3088040351867676, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7954781}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 1.1669282913208008, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.104662}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 1.15039324760437, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.400738}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977217\", \"documentId\": \"6\", \"rerankScore\": 0.8257309198379517, \"chunkContent\": \"﻿事件编号：INC-260802; 发生时间（CST）：2026-08-07 14:20; 严重级别：P3; 资产编号：AU-CM-003; 错误码：E-42; 解决时长（分钟）：55; 根本原因：历史事件未及时归档; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8358661}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977231\", \"documentId\": \"6\", \"rerankScore\": 0.2441035509109497, \"chunkContent\": \"﻿事件编号：INC-260816; 发生时间（CST）：2026-08-25 12:26; 严重级别：P2; 资产编号：AU-GW-002; 错误码：E-42; 解决时长（分钟）：49; 根本原因：事件消费进程停滞; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8181305}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答明确指出了超过三十天的时间条件，并补充了禁止归档三十天内记录，基本切题；包含质量校验等略冗余信息。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确引用了E-42归档需超过三十天且完成质量校验，并指出禁止归档三十天以内活跃事件，无捏造或矛盾。\", \"contextRecallReason\": \"检索上下文明确说明 E-42 处置中只归档超过 30 天并已完成质量校验的记录，覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段3直接说明E-42归档需满足记录超过三十天；片段2、4、5主要涉及E-42阈值或案例处置，对归档时间条件为弱相关或冗余。\", \"answerCorrectnessReason\": \"模型回答准确表达了只归档超过 30 天且已完成质量校验的记录，与标准答案语义完全一致，额外说明不矛盾。\"}', 19422, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (260, '20260908-235537-d56929be', 'aurora-pdf-008', 'E-42 处置后队列深度应降到多少？', 'E-42 处置后，队列深度应降到 **5,000 条以下**。\n\n此外，恢复验证还需满足以下条件：\n1. 连续十五分钟消费速度不低于进入速度。\n2. 抽查三条新事件均完成规则计算。', 'E-42 处置后队列深度恢复标准', '[\"353283299259580421\", \"353285809898651651\", \"353285880643977217\", \"353285880643977231\", \"353283812000661505\"]', '[\"1\", \"4\", \"6\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": 2.7452523708343506, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 17.90809}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651651\", \"documentId\": \"4\", \"rerankScore\": 2.6749796867370605, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8314221}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977217\", \"documentId\": \"6\", \"rerankScore\": 0.8807337284088135, \"chunkContent\": \"﻿事件编号：INC-260802; 发生时间（CST）：2026-08-07 14:20; 严重级别：P3; 资产编号：AU-CM-003; 错误码：E-42; 解决时长（分钟）：55; 根本原因：历史事件未及时归档; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8138422}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977231\", \"documentId\": \"6\", \"rerankScore\": 0.804584264755249, \"chunkContent\": \"﻿事件编号：INC-260816; 发生时间（CST）：2026-08-25 12:26; 严重级别：P2; 资产编号：AU-GW-002; 错误码：E-42; 解决时长（分钟）：49; 根本原因：事件消费进程停滞; 处置摘要：归档旧记录并重启队列进程; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8062178}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": 0.7285311222076416, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77202654}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型直接、准确地回答了核心问题（5,000条以下），但额外补充了恢复验证条件，这些内容虽与E-42处置相关但并非用户所问，存在轻微冗余。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答中的队列深度目标为5,000条以下，以及恢复验证条件（连续十五分钟消费速度不低于进入速度、抽查三条新事件完成规则计算）均能在检索上下文的E-42处置规范和恢复标准中找到直接支撑，无捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"上下文多个片段明确说明 E-42 处置后的恢复/验证标准为队列深度降到 5,000 条以下，完全覆盖标准答案。\", \"contextPrecisionReason\": \"片段1、2、5包含E-42处置后队列深度应降到5000条以下的关键信息，但片段2存在大量其他故障噪声，片段3和4仅与E-42案例相关而未直接回答阈值，整体相关性中等偏上。\", \"answerCorrectnessReason\": \"模型回答明确指出队列深度应降到 5,000 条以下，与标准答案语义完全一致；附加的恢复验证条件不影响核心答案。\"}', 17208, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (261, '20260908-235537-d56929be', 'aurora-pdf-009', 'R-09 表示什么故障？', 'R-09 表示**机器人安全联锁状态异常**。\n\n该故障可能由以下原因引起：\n*   安全门触点松动\n*   输入信号抖动\n*   线路故障\n*   联锁控制器状态不一致\n\n处理 R-09 故障时，必须首先按安全事件处理，立即停止机器人自动运行并隔离设备。', 'R-09 故障代码含义', '[\"353285809898651652\", \"353285809898651650\", \"353285880643977218\", \"353285880643977235\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 3.6011765003204346, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.78904617}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.6011765003204346, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.112854}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977218\", \"documentId\": \"6\", \"rerankScore\": 2.4113643169403076, \"chunkContent\": \"﻿事件编号：INC-260803; 发生时间（CST）：2026-08-11 21:05; 严重级别：P1; 资产编号：AU-RB-007; 错误码：R-09; 解决时长（分钟）：12; 根本原因：联锁输入短时抖动; 处置摘要：检查线路后复位安全联锁; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7852545}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977235\", \"documentId\": \"6\", \"rerankScore\": 2.304582357406616, \"chunkContent\": \"﻿事件编号：INC-260820; 发生时间（CST）：2026-08-27 10:33; 严重级别：P2; 资产编号：AU-RB-008; 错误码：R-09; 解决时长（分钟）：22; 根本原因：安全门触点松动; 处置摘要：紧固触点后复位联锁; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.785485}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接准确指出R-09表示机器人安全联锁状态异常，核心问题完整回应。附加的原因和处理建议与故障相关，属有价值的扩展，但略超出提问范围，未扣分较多。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答中R-09含义、可能原因及安全事件处理要求均来自检索上下文字段五，无捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"检索上下文中片段1和片段2明确包含“R-09 表示机器人安全联锁状态异常”，完全覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"四个片段均涉及 R-09，其中片段1和2包含“机器人安全联锁异常”的明确定义但高度重复，片段3和4为 R-09 相关事件记录，回答故障含义较弱，整体大部分相关。\", \"answerCorrectnessReason\": \"模型回答的核心语义与标准答案完全一致，均指出R-09表示机器人安全联锁状态异常，关键信息无遗漏，且额外提供了可能原因和处理建议，属于有价值的补充，未引入矛盾信息。\"}', 17726, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (262, '20260908-235537-d56929be', 'aurora-pdf-010', 'R-09 处置前为何要隔离机器人？', '在处置 R-09（机器人安全联锁异常）故障时，隔离机器人的主要目的是**防止误动作**。\n\nR-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。由于存在潜在的安全风险，处理人员必须立即停止机器人自动运行并隔离设备，以确保人身和生产安全，避免在故障未排除前发生危险。', 'R-09 处置前隔离机器人的原因', '[\"353285809898651652\", \"353285809898651650\", \"353285880643977235\", \"353285880643977218\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 2.1576223373413086, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.78753877}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.1576223373413086, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.415401}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977235\", \"documentId\": \"6\", \"rerankScore\": 0.6107581257820129, \"chunkContent\": \"﻿事件编号：INC-260820; 发生时间（CST）：2026-08-27 10:33; 严重级别：P2; 资产编号：AU-RB-008; 错误码：R-09; 解决时长（分钟）：22; 根本原因：安全门触点松动; 处置摘要：紧固触点后复位联锁; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7628919}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977218\", \"documentId\": \"6\", \"rerankScore\": -0.2687802314758301, \"chunkContent\": \"﻿事件编号：INC-260803; 发生时间（CST）：2026-08-11 21:05; 严重级别：P1; 资产编号：AU-RB-007; 错误码：R-09; 解决时长（分钟）：12; 根本原因：联锁输入短时抖动; 处置摘要：检查线路后复位安全联锁; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.76205856}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.85, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接点明隔离机器人的核心目的（防止误动作、确保人身与生产安全），切题准确；补充了R-09含义及可能故障原因，属于相关背景，略有冗余但未偏离问题。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答依据片段1/2中R-09处置步骤与安全原则：隔离设备直接用于防止误动作，且上下文要求任何R-09先按安全事件处理、保障人身和生产安全，无捏造或矛盾。\", \"contextRecallReason\": \"上下文中的 R-09 处置步骤明确说明隔离设备是为了防止误动作，完整覆盖标准答案。\", \"contextPrecisionReason\": \"片段1和片段2重复包含R-09处置步骤，直接说明隔离机器人是为防止误动作，属于高度相关；片段3和片段4仅记录R-09事件处置摘要，不解释隔离原因，与问题弱相关且存在冗余，整体约一半片段能直接支撑问题。\", \"answerCorrectnessReason\": \"模型回答明确指出隔离机器人是为了防止误动作，与标准答案语义完全一致，关键信息无遗漏。\"}', 21819, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (263, '20260908-235537-d56929be', 'aurora-pdf-011', 'S-03 表示什么故障？', 'S-03 表示**温度传感器校准偏移超出允许范围**。\n\n常见原因包括：\n*   校准到期\n*   探头污染\n*   安装位置变化\n*   参考仪表异常\n\n需要注意的是，未经复核的异常读数不得直接作为停线依据。', 'S-03故障代码含义', '[\"353285809898651650\", \"353285809898651652\", \"353285880643977219\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 3.3108065128326416, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.112854}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 3.3108065128326416, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7551626}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977219\", \"documentId\": \"6\", \"rerankScore\": 2.344501256942749, \"chunkContent\": \"﻿事件编号：INC-260804; 发生时间（CST）：2026-08-16 08:40; 严重级别：P2; 资产编号：AU-SN-014; 错误码：S-03; 解决时长（分钟）：27; 根本原因：传感器校准偏移; 处置摘要：重新校准并观察二十分钟; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78735715}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接说明 S-03 表示温度传感器校准偏移超出允许范围，切中问题核心；附加原因和注意事项基本相关，但略有冗余。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答的核心含义、常见原因以及注意事项均直接来自检索上下文，无捏造或矛盾内容。\", \"contextRecallReason\": \"检索上下文片段1和片段2均明确说明S-03表示温度传感器校准偏移超出允许范围，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"三个片段均涉及S-03，其中片段1/2直接说明S-03表示温度传感器校准偏移，片段3也包含S-03案例；但片段1/2重复且夹杂大量其他故障噪声，片段3为弱相关补充，因此相关度较高但非满分。\", \"answerCorrectnessReason\": \"模型回答的核心定义与标准答案完全一致，补充信息未改变原义。\"}', 19919, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (264, '20260908-235537-d56929be', 'aurora-pdf-012', 'S-03 校准后要观察多久？', 'S-03 校准后需要观察 **二十分钟**。\n\n在此期间，需确认数据无突跳且不再产生 S-03 告警，同时读数回到十八至二十六摄氏度的正常范围或与参考仪表的差值回到允许范围。', 'S-03 校准后观察时长要求', '[\"353285880643977219\", \"353285809898651652\", \"353283299259580421\"]', '[\"6\", \"4\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977219\", \"documentId\": \"6\", \"rerankScore\": 3.311692714691162, \"chunkContent\": \"﻿事件编号：INC-260804; 发生时间（CST）：2026-08-16 08:40; 严重级别：P2; 资产编号：AU-SN-014; 错误码：S-03; 解决时长（分钟）：27; 根本原因：传感器校准偏移; 处置摘要：重新校准并观察二十分钟; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78515303}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 1.8555171489715576, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 13.465031}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580421\", \"documentId\": \"1\", \"rerankScore\": -1.5354366302490234, \"chunkContent\": \"## 运行指标与告警阈值\\n- HG-220 网关心跳间隔为一分钟，连续三次缺失时生成通信告警。\\n- 网关本地缓存使用率达到 25% 时发出预警，达到 40% 时暂停非关键采集任务。\\n- 事件队列记录数超过 50,000 条时触发 E-42，恢复标准为低于 5,000 条。\\n- 设备时钟偏差超过 90 秒时触发 E-17，校正后需连续观察十五分钟。\\n- 温度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n- 湿度越界持续十分钟且传感器校准有效时创建 P2 工单。\\n告警确认不等于故障恢复。值班员确认告警后仍需记录原因、处置动作和验证结果。只有指标回到正常范围并保持规定观察时间，工单才可进入待关闭状态。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.909574}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.9, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接给出了观察时长二十分钟，并补充了观察期间的判断要点，基本切题但略有冗余。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"回答中的观察时长二十分钟、数据无突跳、不再产生 S-03 告警以及读数范围/差值要求均直接来自片段1和片段2，无捏造或矛盾。\", \"contextRecallReason\": \"上下文片段1和片段2均明确包含 S-03 重新校准后需连续观察二十分钟的信息，覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1和片段2均明确提到S-03重新校准后观察二十分钟，高度相关；片段3主要涉及通用指标阈值，仅弱相关，属于少量噪声。\", \"answerCorrectnessReason\": \"模型准确回答核心时长为二十分钟，与标准答案一致；额外补充了观察期间的具体确认要点，未与标准答案矛盾，仅未显式使用\'连续\'一词，但语义上已涵盖。\"}', 23324, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (265, '20260908-235537-d56929be', 'aurora-pdf-013', 'N-11 表示什么故障？', 'N-11 表示**工业交换机链路丢包率持续超标**。\n\n该故障的常见原因包括：\n*   光模块温度过高\n*   接口松动\n*   上联拥塞\n*   维护期间链路切换', 'N-11 故障代码含义', '[\"353285880643977221\", \"353285809898651652\", \"353285809898651650\", \"353285880643977233\"]', '[\"6\", \"4\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977221\", \"documentId\": \"6\", \"rerankScore\": 2.1881954669952393, \"chunkContent\": \"﻿事件编号：INC-260806; 发生时间（CST）：2026-08-19 13:35; 严重级别：P2; 资产编号：AU-SW-012; 错误码：N-11; 解决时长（分钟）：64; 根本原因：上联端口丢包; 处置摘要：切换备用链路并更换模块; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7906097}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 2.1461541652679443, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.79500675}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.1461541652679443, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.112854}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977233\", \"documentId\": \"6\", \"rerankScore\": 2.142388343811035, \"chunkContent\": \"﻿事件编号：INC-260818; 发生时间（CST）：2026-08-26 01:22; 严重级别：P2; 资产编号：AU-SW-011; 错误码：N-11; 解决时长（分钟）：58; 根本原因：光模块温度过高; 处置摘要：更换光模块并观察链路; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7895504}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.3333333333333333}', '{\"relevancy\": 0.8, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接说明了 N-11 表示的故障，核心问题已回应；但补充常见原因略超出问题范围，存在一定冗余。\", \"contextPrecision\": 0.7, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与检索上下文中关于N-11含义及常见原因的表述完全一致，无捏造、夸大或矛盾内容。\", \"contextRecallReason\": \"检索上下文中片段2和片段3明确说明N-11表示工业交换机链路丢包率持续超标，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段2和片段3直接给出N-11含义，但片段3完全冗余；片段1和片段4仅包含N-11错误码及案例信息，属于弱相关。整体相关片段占多数，但存在明显冗余和噪声。\", \"answerCorrectnessReason\": \"模型回答与标准答案语义完全一致，正确说明 N-11 表示工业交换机链路丢包率持续超标，额外补充的原因不影响核心一致性。\"}', 15361, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (266, '20260908-235537-d56929be', 'aurora-pdf-014', 'N-11 切换备用链路后应验证什么？', '在 N-11 故障处理中，切换备用链路后应验证以下标准：\n\n1. **网关心跳恢复**；\n2. **链路丢包率回到基线范围**；\n3. **持续观察十五分钟**，确认无异常。', 'N-11 备用链路切换后验证内容', '[\"353285809898651652\", \"353285880643977221\", \"353285880643977233\", \"353283812000661506\"]', '[\"4\", \"6\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651652\", \"documentId\": \"4\", \"rerankScore\": 3.35766863822937, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.77852756}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977221\", \"documentId\": \"6\", \"rerankScore\": 1.7529369592666626, \"chunkContent\": \"﻿事件编号：INC-260806; 发生时间（CST）：2026-08-19 13:35; 严重级别：P2; 资产编号：AU-SW-012; 错误码：N-11; 解决时长（分钟）：64; 根本原因：上联端口丢包; 处置摘要：切换备用链路并更换模块; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8111857}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977233\", \"documentId\": \"6\", \"rerankScore\": 0.06877170503139496, \"chunkContent\": \"﻿事件编号：INC-260818; 发生时间（CST）：2026-08-26 01:22; 严重级别：P2; 资产编号：AU-SW-011; 错误码：N-11; 解决时长（分钟）：58; 根本原因：光模块温度过高; 处置摘要：更换光模块并观察链路; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78102046}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": -1.8169318437576296, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.596149}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出了切换备用链路后应验证的关键项，内容与问题高度相关且无明显冗余。\", \"contextPrecision\": 0.25, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答列出的网关心跳恢复、链路丢包率回到基线范围、持续观察十五分钟均直接对应检索上下文中 N-11 的验证标准；“确认无异常”属于对观察要求的合理概括，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文明确给出 N-11 切换备用链路后的验证标准：网关心跳恢复、链路丢包率回到基线范围、持续观察十五分钟，覆盖标准答案全部关键信息。\", \"contextPrecisionReason\": \"仅片段1明确回答N-11切换备用链路后的验证标准；片段2、3为N-11事件记录，片段4为通用变更验证，均未直接说明切换备用链路后应验证什么，噪声占比高。\", \"answerCorrectnessReason\": \"模型回答准确覆盖了网关心跳恢复、丢包率回落以及持续观察十五分钟三项关键验证内容，语义与标准答案一致。\"}', 16668, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (267, '20260908-235537-d56929be', 'aurora-pdf-015', 'G-08 表示什么故障？', 'G-08 表示**规则包不一致**。\n\n具体含义为规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。', 'G-08故障代码含义', '[\"353285809898651650\", \"353285880643977243\", \"353285880643977222\"]', '[\"4\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.5798163414001465, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 9.112854}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977243\", \"documentId\": \"6\", \"rerankScore\": 2.4751453399658203, \"chunkContent\": \"﻿事件编号：INC-260828; 发生时间（CST）：2026-08-31 00:48; 严重级别：P2; 资产编号：AU-SV-021; 错误码：G-08; 解决时长（分钟）：69; 根本原因：规则包加载不完整; 处置摘要：恢复上版规则包并重载; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.78808194}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977222\", \"documentId\": \"6\", \"rerankScore\": 2.422312021255493, \"chunkContent\": \"﻿事件编号：INC-260807; 发生时间（CST）：2026-08-20 02:18; 严重级别：P3; 资产编号：AU-SV-022; 错误码：G-08; 解决时长（分钟）：31; 根本原因：备用节点规则包版本落后; 处置摘要：同步规则包并执行校验; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.76122993}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接、准确地指出 G-08 表示\'规则包不一致\'，并补充了具体含义和可能的表现，完全切题，无离题内容，完整回应了用户问题。\", \"contextPrecision\": 1.0, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答与片段1第八节关于G-08的定义完全一致，所有表述均可由检索上下文直接支撑，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"检索上下文片段1明确说明 G-08 表示规则包版本或加载结果不一致，与标准答案关键信息完全匹配。\", \"contextPrecisionReason\": \"片段1明确定义了G-08为规则包版本或加载结果不一致，片段2和片段3均为G-08相关故障事件，均与问题高度相关。\", \"answerCorrectnessReason\": \"模型回答的核心语义与标准答案完全一致，准确指出G-08表示规则包版本或加载结果不一致，额外补充的具体表现属于合理展开，无错误无遗漏。\"}', 17046, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (268, '20260908-235537-d56929be', 'aurora-pdf-016', 'G-08 回退后必须执行什么验证？', 'G-08（规则包不一致）故障在回退后，必须执行以下两项验证：\n\n1. **规则包校验和检查**：确认主备节点版本和校验和一致。\n2. **抽样事件计算**：完成抽样事件计算，确保规则加载日志无失败项且计算正常。\n\n只有上述两项验证均通过，方可恢复发布。', 'G-08 回退后验证流程', '[\"353285809898651653\", \"353283812000661506\", \"353285880643977243\", \"353285880643977222\", \"353283812000661505\"]', '[\"4\", \"2\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": 3.450139045715332, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7684157}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661506\", \"documentId\": \"2\", \"rerankScore\": 0.4897237718105316, \"chunkContent\": \"11. 变更验证与回退\\r\\n配置变更完成后检查网关心跳、事件队列、规则计算和质量抽样四项结果。任一项失败都视为验证不通过。回退时使用审批单中登记的版本，回退后重新执行四项检查。连续两次回退失败时停止操作，隔离受影响设备并升级给当班经理。\\r\\n\\r\\n\\\\n\\\\n12. 事件通知与升级\\r\\nP1 事件确认后五分钟内通知当班经理和 Blue Heron，十五分钟内给出首次状态通报。P2 事件由责任团队处理，每三十分钟更新一次进展；超过两小时未恢复时升级为 P1。P3 事件在一个工作日内响应，不自动升级，但同类事件七天内出现三次时应发起问题复盘。\\r\\n\\r\\n\\\\n\\\\n13. 工单记录规范\\r\\n工单必须包含事件开始时间、发现方式、影响区域、资产编号、错误码、操作步骤、验证结果和责任团队。时间统一使用 CST，并在系统中说明为 UTC+08:00。禁止只记录“已处理”或“恢复正常”，也禁止粘贴密码、访问令牌和个人身份信息。\\r\\n\\r\\n\\\\n\\\\n14. 交接模板\\r\\n交接人逐项填写未关闭工单、隔离设备、临时配置、待观察指标和下一维护任务。临时配置必须标注负责人和失效时间。接班人应复述 P1、P2 事件状态并确认可访问相关证据，双方完成电子确认后交接才生效。\\r\\n\\r\\n\\\\n\\\\n15. 日终检查\\r\\n日终时核对告警数量与工单数量是否一致，确认已关闭工单均有验证证据，检查临时配置是否即将到期。发现无工单对应的关键告警时，应补建工单并注明发现原因。当天有 P1 事件时，不得在复盘负责人未确定前结束交接。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 10.534608}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977243\", \"documentId\": \"6\", \"rerankScore\": -0.12351016700267792, \"chunkContent\": \"﻿事件编号：INC-260828; 发生时间（CST）：2026-08-31 00:48; 严重级别：P2; 资产编号：AU-SV-021; 错误码：G-08; 解决时长（分钟）：69; 根本原因：规则包加载不完整; 处置摘要：恢复上版规则包并重载; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.784147}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977222\", \"documentId\": \"6\", \"rerankScore\": -0.5678850412368774, \"chunkContent\": \"﻿事件编号：INC-260807; 发生时间（CST）：2026-08-20 02:18; 严重级别：P3; 资产编号：AU-SV-022; 错误码：G-08; 解决时长（分钟）：31; 根本原因：备用节点规则包版本落后; 处置摘要：同步规则包并执行校验; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.79629743}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661505\", \"documentId\": \"2\", \"rerankScore\": -1.7124611139297483, \"chunkContent\": \"7. 网关心跳异常处置\\r\\n发现 HG-220 连续丢失三次心跳后，先检查该区域交换机是否处于批准的维护窗口，再从平台查看最后一次成功上报时间。若链路正常，联系 Edge Platform 团队核对采集进程。未经该团队确认，不得重启网关，也不得清空网关本地缓存。恢复后连续观察十五分钟，至少收到十五次正常心跳方可关闭通信告警。\\r\\n\\r\\n\\\\n\\\\n8. 温度和湿度异常处置\\r\\n环境异常首先核对资产编号和测点位置，然后检查 AU-SN-014 或对应传感器的校准有效期。校准过期时先将数据标记为“待确认”，通知 Facilities 团队复核，不直接依据该数值停线。校准有效且越界持续十分钟时创建 P2 工单。恢复正常后继续观察二十分钟，并记录最高值、最低值和持续时长。\\r\\n\\r\\n\\\\n\\\\n9. 缓存与队列巡检\\r\\n网关缓存使用率低于 25% 为正常；达到 25% 时通知值班员并检查上游网络；达到 40% 时暂停非关键采集任务。事件队列超过 50,000 条时按 E-42 流程处理。归档前确认记录已超过三十天，归档后重启 Queue Worker，并验证队列深度降到 5,000 条以下。\\r\\n\\r\\n\\\\n\\\\n10. 维护窗口操作清单\\r\\n01:45 前确认审批单、影响范围、回退包和联系人。02:00 暂停非关键批任务并记录基线指标。变更过程中每十五分钟记录一次状态，不得同时修改两个生产区的关键配置。03:15 前开始回归验证，03:30 前恢复批任务。若 03:20 仍未完成核心验证，应执行回退，不得擅自延长窗口。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.927215}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 1.0, \"faithfulness\": 0.95, \"contextRecall\": 1.0, \"relevancyReason\": \"模型回答直接、完整地列出了G-08回退后必须执行的两项验证，内容高度切题，无明显无关信息。\", \"contextPrecision\": 0.6, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"回答主要基于片段1中 G-08 的验证标准和回退要求，核心内容可由上下文支撑；对‘规则加载日志无失败项’和‘计算正常’有少量合理整合。\", \"contextRecallReason\": \"检索上下文中 G-08 段落明确说明回退后必须执行规则包校验和抽样事件计算，完整覆盖标准答案关键信息。\", \"contextPrecisionReason\": \"片段1直接回答G-08回退后需执行规则包校验和抽样事件计算；片段2和片段4与G-08或回退验证部分相关，片段3仅为G-08案例且缺少验证要求，片段5多为无关噪声，因此整体相关比例约一半多。\", \"answerCorrectnessReason\": \"模型回答完整覆盖了标准答案的两项核心验证：规则包校验和抽样事件计算，并补充了执行细节，关键信息无遗漏，语义完全一致。\"}', 24909, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (269, '20260908-235537-d56929be', 'aurora-pdf-017', '故障恢复需要满足哪三个共同条件？', '根据提供的参考资料，关于故障恢复的条件描述如下：\n\n系统恢复至少需要满足**四项**条件，而非三项。这四项共同条件分别是：\n1. 受影响区域重新可见；\n2. 关键设备心跳连续正常；\n3. 事件队列没有持续增长；\n4. 抽样规则计算结果正确。\n\n此外，资料特别指出，仅恢复页面访问并不代表生产能力已完全恢复。', '故障恢复需满足的三个共同条件', '[\"353283299259580428\", \"353283299259580422\"]', '[\"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580428\", \"documentId\": \"1\", \"rerankScore\": 1.4849117994308472, \"chunkContent\": \"## 恢复验收标准\\n系统恢复至少满足四项条件：受影响区域重新可见，关键设备心跳连续正常，事件队列没有持续增长，抽样规则计算结果正确。仅恢复页面访问不代表生产能力恢复。\\nP1 恢复由当班经理确认，并由 Quality 团队抽样验证；P2 恢复由责任团队确认，值班员复核关键指标；P3 可由处理人确认。恢复后仍需完成规定观察期，观察期内再次出现同类告警时沿用原事件，不重复创建新事件。\\n关闭事件前应撤销临时权限和临时配置，解除设备隔离，恢复暂停的批任务，并确认交接记录已更新。无法立即完成的长期纠正措施应转为问题记录，不能以事件已恢复为由删除后续任务。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.83230925}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": -2.498340845108032, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 15.417003}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 0.75, \"faithfulness\": 1.0, \"contextRecall\": 0.4, \"relevancyReason\": \"回答围绕故障恢复共同条件展开，并纠正了题目中的数量；但未直接按问题要求给出三个条件，且包含额外说明，存在轻微不符合问法。\", \"contextPrecision\": 0.5, \"answerCorrectness\": 0.0, \"faithfulnessReason\": \"模型回答完全基于检索上下文，准确指出上下文规定的是四项条件而非三项，并完整列举四项恢复验收标准，还补充了仅恢复页面访问不等于生产能力恢复的原文信息，无捏造或矛盾内容。\", \"contextRecallReason\": \"上下文明确覆盖“规定观察期内无同类告警”；对“指标回到阈值内”和“核心能力可用”仅有相近表述，如心跳正常、事件队列不增长、生产能力恢复等，未直接命中标准答案关键表述。\", \"contextPrecisionReason\": \"片段1涉及系统恢复需满足的条件，与问题相关但给出的是四项条件而非三项；片段2主要是事件分级规则，与故障恢复共同条件无关。\", \"answerCorrectnessReason\": \"模型回答未包含标准答案中的三个共同条件，且改称为四项不同条件，核心语义明显不一致。\"}', 21762, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (270, '20260908-235537-d56929be', 'aurora-pdf-018', 'P1 故障由哪个协调组统筹？', 'P1 故障由**蓝鹭应急协调组**（Blue Heron）统筹。\n\n在处理过程中，处理团队需每十五分钟更新一次状态。', 'P1 故障统筹协调组职责', '[\"353285809898651650\", \"353285809898651653\", \"353283299259580425\", \"353283812000661504\", \"353283812000661508\"]', '[\"4\", \"1\", \"2\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 2.371783494949341, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 12.393538}, {\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651653\", \"documentId\": \"4\", \"rerankScore\": 2.371783494949341, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7831757}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580425\", \"documentId\": \"1\", \"rerankScore\": 1.2451235055923462, \"chunkContent\": \"## 术语说明\\n- Edge Platform：负责边缘网关和采集服务的团队名称。\\n- Quality：负责质量抽样和结果确认的团队名称。\\n- Blue Heron：P1 事件使用的应急协调组代号。\\n- 恢复时间：从事件确认到核心能力恢复的持续时间。\\n- 观察时间：恢复后继续监控、确认指标稳定的时间。\\n- 隔离设备：为防止影响扩大而暂时停止接入平台的设备。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 8.164671}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661504\", \"documentId\": \"2\", \"rerankScore\": -0.4792063236236572, \"chunkContent\": \"曙光智造园区运行手册（版本 2.0）\\r\\n\\r\\n\\\\n\\\\n1. 每日开班\\r\\n操作员在 07:45 CST 检查 Aurora-7 仪表盘。先确认 A、B、C 三个区域均为绿色，再检查 HG-220 网关心跳。连续丢失三次心跳时，不得直接重启网关，应先联系 Edge Platform 团队。\\r\\n\\r\\n\\\\n\\\\n2. 环境处置\\r\\n温度低于 18°C 或高于 26°C 时，值班员应创建 P2 工单。湿度低于 35% 或高于 65% 时，先检查传感器 AU-SN-014 的校准日期；校准有效且异常持续十分钟后，再创建 P2 工单。\\r\\n\\r\\n\\\\n\\\\n3. 维护窗口\\r\\n固定维护窗口为每周三 02:00-03:30 CST。窗口开始前十五分钟暂停非关键批任务，窗口结束后由 Quality 团队执行抽样校验。\\r\\n\\r\\n\\\\n\\\\n4. 升级\\r\\nP1 事件由当班经理立即通知代号“Blue Heron”的应急协调组。P2 事件超过两小时未恢复时升级为 P1。P3 事件不自动升级。\\r\\n\\r\\n\\\\n\\\\n5. 交接\\r\\n交接记录必须包含未关闭工单、隔离设备、临时配置和下一次维护任务，不得只写“无异常”。\\r\\n\\r\\n\\\\n\\\\n6. 开班前置检查\\r\\n操作员到岗后先确认个人账号未被共享，值班电话、工单系统和只读仪表盘均可用。07:45 开始检查时，依次记录 A、B、C 三个区域颜色、最后心跳时间、未确认告警数量和当前队列深度。任何一个区域为红色时，应先创建事件记录，再进行设备操作。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 6.831543}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661508\", \"documentId\": \"2\", \"rerankScore\": -1.733762264251709, \"chunkContent\": \"21. 临时措施清理\\r\\n事件进入待关闭状态后，处理人检查临时权限、临时配置、设备隔离和暂停任务。临时权限立即撤销，临时配置按登记时间恢复，设备解除隔离前执行一次健康检查。仍需保留的临时措施必须转为已审批的变更，不能无限期挂在事件工单中。\\r\\n\\r\\n\\\\n\\\\n22. 重复问题管理\\r\\n同类 P2 事件七天内出现两次，责任团队应比较共同原因和变更记录；同类 P3 事件七天内出现三次，应建立问题记录。问题记录包含临时缓解措施、根本原因假设、验证计划、长期纠正措施和预计完成时间。\\r\\n\\r\\n\\\\n\\\\n23. 数据导出操作\\r\\n导出前选择最小时间范围和必要字段，能够使用小时聚合数据时不导出原始传感器数据。超过一万行时取得 Data Steward 和值班经理双人审批。导出文件标注用途、接收人和到期时间，只能保存在批准位置，不得上传公网平台。\\r\\n\\r\\n\\\\n\\\\n24. 每周运行复核\\r\\n每周维护窗口结束后，值班负责人汇总一周内的 P1、P2 事件、重复 P3 事件、过期临时配置和即将到期的设备校准。复核结果形成任务清单，明确责任团队和完成日期。没有异常事件时也要记录已完成复核，不能以空白记录替代。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.7658359}]', '{\"mrr\": 0.5, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.8, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"模型准确直接地回答了核心问题（蓝鹭应急协调组/Blue Heron），但附加了与问题无关的\'每十五分钟更新状态\'信息，属于冗余内容，略有扣分。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"模型回答中的‘P1故障由蓝鹭应急协调组统筹’、‘Blue Heron’对应关系以及‘处理团队每十五分钟更新一次状态’均可由检索上下文直接支撑，无捏造或矛盾内容。\", \"contextRecallReason\": \"检索上下文中多处明确说明“P1 故障由蓝鹭应急协调组统筹”，并以 Blue Heron 作为应急协调组代号，完全覆盖标准答案的关键信息。\", \"contextPrecisionReason\": \"片段1、2明确说明P1由蓝鹭应急协调组统筹；片段3和片段4通过Blue Heron/应急协调组直接回答问题；片段5主要讲临时措施、数据导出和周复核，与问题基本无关。整体大部分相关，少量噪声。\", \"answerCorrectnessReason\": \"模型回答准确指出P1故障由蓝鹭应急协调组统筹，与标准答案语义完全一致；额外补充信息不影响核心答案正确性。\"}', 24095, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (271, '20260908-235537-d56929be', 'aurora-pdf-019', 'P2 超过两小时未恢复时如何处理？', '根据参考资料，当 P2 级别故障超过两小时仍未恢复时，应**升级为 P1 事件**，并由**蓝鹭应急协调组**统筹处理。', 'P2故障超过2小时未恢复处置流程', '[\"353285809898651650\", \"353283299259580422\", \"353283299259580429\", \"353283812000661507\", \"353285880643977227\"]', '[\"4\", \"1\", \"2\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 5.2227559089660645, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 19.645649}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580422\", \"documentId\": \"1\", \"rerankScore\": 2.4872970581054688, \"chunkContent\": \"## 事件分级补充规则\\nP1 适用于全园区停产、安全联锁失效或三个生产区同时失去采集能力。P2 适用于单个生产区核心能力降级、关键设备不可用或环境异常持续。P3 适用于非关键报表延迟、单个辅助设备告警或不影响生产的体验问题。\\n同一原因在三十分钟内影响两个生产区时，事件至少按 P2 处理；影响三个生产区时按 P1 处理。P2 从确认故障开始计算，超过两小时仍未恢复时升级为 P1。首次响应目标和升级时限是两个不同概念，不得混用。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.81520426}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580429\", \"documentId\": \"1\", \"rerankScore\": 1.349566102027893, \"chunkContent\": \"## 评测事实边界\\n本数据集中的时间、阈值、资产和流程构成封闭测试事实。不同文档出现同一规则时，应以条件更具体的条款回答。例如“P2 首次响应目标为两小时”和“P2 超过两小时未恢复升级为 P1”描述的是不同管理节点，回答时必须保留“首次响应”或“未恢复”的条件。\\n资产编号和错误码是专有标识，不应翻译或改写。团队英文代号仅用于保持跨文档一致性，不代表需要使用英文回答。文档没有给出具体责任人的场景，应回答责任团队或当班经理，不得编造姓名和联系方式。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 16.06881}, {\"url\": \"http://127.0.0.1:9090/know-engine/02_曙光智造园区运行手册.txt\", \"chunkId\": \"353283812000661507\", \"documentId\": \"2\", \"rerankScore\": 0.41718387603759766, \"chunkContent\": \"16. 异常操作禁止项\\r\\n禁止为消除告警而修改阈值，禁止在未归档前清空事件队列，禁止绕过双人审批导出超过 10,000 行的数据，禁止在非维护窗口修改关键设备配置。确需紧急操作时，必须关联 P1 或 P2 事件并取得当班经理批准。\\r\\n\\r\\n\\\\n\\\\n17. 证据与复盘\\r\\n操作证据包括工单时间线、审批记录、关键日志、验证截图和配置差异。P1 事件在恢复后二十四小时内确定复盘负责人，三个工作日内完成初稿。P2 事件若七天内重复发生，应按问题管理流程分析根因和长期纠正措施。\\r\\n\\r\\n\\\\n\\\\n18. 平台依赖检查\\r\\n多个设备同时异常时，操作员先检查公共依赖。设备时间混乱优先检查时间服务，多个区域心跳中断优先检查工业网络，告警延迟优先检查事件队列和规则计算。公共依赖未确认前，不得逐台重启设备，以免扩大影响并破坏现场证据。\\r\\n\\r\\n\\\\n\\\\n19. 降级运行\\r\\n单个非关键报表不可用时，可以暂停报表任务并保持核心采集。事件队列增长时，优先暂停历史统计和批量导出，不得暂停安全告警。降级运行必须在工单中列出保留能力、暂停能力、开始时间、批准人和恢复条件，每三十分钟复核一次。\\r\\n\\r\\n\\\\n\\\\n20. 恢复验收\\r\\n恢复验收依次检查区域状态、设备心跳、队列趋势、规则计算和质量抽样。页面可以打开但队列仍持续增长时，不得宣布恢复。P1 由当班经理确认恢复，P2 由责任团队确认并由值班员复核，P3 可由处理人确认。\", \"documentTitle\": \"02_曙光智造园区运行手册\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.80193406}, {\"url\": \"http://127.0.0.1:9090/know-engine/06_曙光智造园区事件记录.csv\", \"chunkId\": \"353285880643977227\", \"documentId\": \"6\", \"rerankScore\": -0.5430878400802612, \"chunkContent\": \"﻿事件编号：INC-260812; 发生时间（CST）：2026-08-23 06:18; 严重级别：P2; 资产编号：AU-UPS-051; 错误码：P-12; 解决时长（分钟）：88; 根本原因：电池组容量下降; 处置摘要：切换旁路并更换电池组; 响应目标是否达标：是; 复盘状态：已完成\", \"documentTitle\": \"06_曙光智造园区事件记录\", \"retrievalSource\": \"VECTOR\", \"similarityScore\": 0.8243849}]', '{\"mrr\": 0.0, \"hitAtK\": false, \"recallAtK\": 0.0}', '{\"relevancy\": 1.0, \"faithfulness\": 1.0, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接切题，准确回应了P2超过两小时未恢复时的处理方式（升级为P1、由蓝鹭应急协调组统筹），无冗余内容，完整回答了问题核心。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 0.9, \"faithfulnessReason\": \"模型回答与检索上下文完全一致：上下文明确规定 P2 超过两小时未恢复时升级为 P1，并由蓝鹭应急协调组统筹，无捏造、夸大或矛盾。\", \"contextRecallReason\": \"标准答案关键信息为“P2 超过两小时未恢复时升级为 P1”。检索上下文片段1和片段2均明确包含该规则，因此关键信息被完全覆盖。\", \"contextPrecisionReason\": \"片段1和片段2直接说明P2超过两小时未恢复应升级为P1并由蓝鹭应急协调组统筹；片段3提供边界区分，片段4涉及升级后的审批与恢复验收，均弱相关；片段5为事件样例，与问题无关。\", \"answerCorrectnessReason\": \"模型回答准确包含了核心处理动作：P2超过两小时未恢复应升级为P1；额外补充蓝鹭应急协调组统筹处理，未影响关键语义一致。\"}', 20354, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (272, '20260908-235537-d56929be', 'aurora-pdf-020', '排障记录至少需要保存哪些证据？', '根据《曙光智造园区故障排查指南》，排障记录（处置证据）至少需要保存以下内容：\n\n1.  **时间线**：记录告警原文、首次发生时间、影响资产和影响区域等关键时间节点。\n2.  **关键日志**：包括设备日志、同步日志、规则加载日志或输入信号日志等，用于支撑故障分析和验证。\n3.  **执行命令或操作**：记录实际执行的处置动作，如 NTP 同步、进程重启、配置修改或现场复位操作等。\n4.  **配置差异**：记录故障前后的配置对比，特别是涉及规则包版本、校验和或网络配置变更的情况。\n5.  **验证结果**：包括指标回落情况、核心能力可用性确认、观察期内无同类告警的证明，以及抽样事件计算通过的结果。\n\n此外，完整的处置证据链还应包含**工单、审批单、操作日志和验证截图**。在保存期间，不得修改原始时间戳，且排障记录中严禁包含真实密码、访问令牌和个人身份信息。', '排障记录证据保存要求', '[\"353285809898651650\", \"353283299259580424\"]', '[\"4\", \"1\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/04_曙光智造园区故障排查指南.pdf\", \"chunkId\": \"353285809898651650\", \"documentId\": \"4\", \"rerankScore\": 1.3315657377243042, \"chunkContent\": \"# 曙光智造园区故障排查指南\\n文档版本：2.5\\n生效日期：2026年8月28日\\n本文中的名称、编号、阈值和案例均为虚构测试数据。\\n## 一、适用范围与安全原则\\n本指南用于曙光智造园区设备采集、事件队列、机器人联锁、环境传感器、工业网络和规则计算故障。处理人员应先保障人身和生产安全，再恢复系统能力。涉及机器人、安全联锁或供电设备时，必须由具备权限的人员执行现场操作。\\n处理故障前应确认影响区域、资产编号、错误码、告警开始时间和当前维护状态。若同一原因影响三个生产区，直接按 P1 事件处理；单个生产区核心能力降级按 P2 处理；非关键体验问题一般按 P3 处理。\\n禁止为消除告警而提高阈值，禁止在未归档前清空队列，禁止跳过安全隔离，禁止把真实密码和令牌写入排障记录。无法确认操作影响时应停止并联系当班经理。\\n## 二、通用排查流程\\n第一步，确认现象。记录告警原文、首次发生时间、影响资产和影响区域，不以转述替代原始证据。第二步，检查变更。核对故障前两小时是否发生发布、配置修改、网络维护或设备检修。第三步，缩小范围。比较同型号设备、相邻区域和备用节点状态，判断是单点故障还是公共依赖异常。\\n第四步，执行最小处置。优先选择可回退、影响范围小的动作，每次只改变一个条件。第五步，验证恢复。恢复必须同时满足指标回到阈值内、核心能力可用、规定观察期内无同类告警。第六步，留存证据。至少保存时间线、关键日志、执行命令或操作、配置差异和验证结果。\\n告警确认、指标回落和事件关闭是三个不同状态。指标短暂恢复但观察期内再次异常时，事件仍视为未恢复。P2 超过两小时未恢复时升级为 P1，由蓝鹭应急协调组统筹。\\n## 三、E-17 时钟偏差故障\\n含义：E-17 表示设备时钟偏差超过九十秒。常见原因包括时间服务器不可达、备用时间源切换失败、网络访问控制变更或采集进程长期未同步。时间偏差会造成事件排序错误和重复数据，因此必须先校正时间再恢复采集。\\n处置步骤：一，检查园区时间服务是否可达，并确认其他设备是否同时异常。二，查看设备当前时间、时区和最后同步时间。三，确认时间源正常后执行 NTP 同步。四，重启Edge Collector 采集进程，使其重新建立带正确时间戳的连接。五，不得重启 HG-220网关，因为重启会扩大采集中断，且不能替代时间校正。\\n验证标准：设备时钟偏差低于三十秒；新采集记录时间连续且顺序正确；连续观察十五分钟无新的 E-17 告警。若同步后偏差仍超过九十秒，保留同步日志，检查网络访问控制和时间服务器状态，并联系边缘平台组。\\n回退与升级：若重启采集进程后数据中断，应恢复进程原配置并检查端口。两个区域同时发生 E-17 时按 P2 组织处理；三个区域同时发生时按 P1 处理。\\n## 四、E-42 事件队列积压\\n含义：E-42 表示事件队列记录数超过五万条。常见原因包括消费进程停滞、下游存储变慢、历史记录未归档或规则计算异常重试。队列积压会延迟告警，但不能通过直接清空队列恢复。\\n处置步骤：一，记录当前队列深度、增长速度和最早记录时间。二，确认 QueueWorker 进程状态和下游存储连接。三，只归档超过三十天并已完成质量校验的记录。四，归档成功后重启 Queue Worker。五，观察消费速度，确认新事件仍能进入并被处理。\\n验证标准：队列深度降到五千条以下；连续十五分钟消费速度不低于进入速度；抽查三条新事件均完成规则计算。归档失败时不得删除源记录，应停止后续删除动作并联系数据治理组。\\n禁止操作：禁止直接清空队列，禁止归档三十天以内的活跃事件，禁止在未验证下游存储时反复重启消费进程。队列持续增长并影响告警生成时按 P2 处理。\\n## 五、R-09 机器人安全联锁异常\\n含义：R-09 表示机器人安全联锁状态异常，可能由安全门触点松动、输入信号抖动、线路故障或联锁控制器状态不一致引起。任何 R-09 都必须先按安全事件处理。\\n处置步骤：一，立即停止机器人自动运行并隔离设备，防止误动作。二，由现场人员确认安全门、急停按钮和保护装置状态。三，检查触点、线路和联锁输入日志。四，排除物理故障后，由授权工程师复位安全联锁。五，低速执行一次空载测试。\\n验证标准：所有安全输入状态稳定，联锁测试通过，空载测试无异常，观察十分钟未再次触发 R-09。禁止短接安全触点、屏蔽联锁信号或远程强制机器人运行。安全联锁无法恢复或影响多台机器人时立即按 P1 上报。\\n## 六、S-03 温度传感器校准偏移\\n含义：S-03 表示温度传感器校准偏移超出允许范围。常见原因是校准到期、探头污染、安装位置变化或参考仪表异常。未经复核的异常读数不得直接作为停线依据。\\n处置步骤：一，确认资产编号和安装位置。二，检查校准有效期和最近维护记录。三，使用在有效期内的参考仪表进行比对。四，确认偏移后重新校准传感器。五，记录校准前后差值并恢复采集。\\n验证标准：读数回到十八至二十六摄氏度的正常范围，或与参考仪表的差值回到允许范围；连续观察二十分钟，数据无突跳且不再产生 S-03。校准失败时将该测点标记为待确认，并通知设施保障组更换传感器。\\n## 七、N-11 工业网络丢包\\n含义：N-11 表示工业交换机链路丢包率持续超标。常见原因包括光模块温度过高、接口松动、上联拥塞和维护期间链路切换。\\n处置步骤：检查接口错误计数和光模块状态，确认是否存在批准的网络维护；条件允许时切换到备用链路，再更换异常模块或紧固接口。切换过程中不得同时中断主备链路。\\n验证标准：网关心跳恢复，链路丢包率回到基线范围，并持续观察十五分钟。若切换备用链路后仍丢包，应比较相邻交换机状态并检查公共上联，影响单个生产区核心采集时按P2 处理。\\n## 八、G-08 规则包不一致\\n含义：G-08 表示规则包版本或加载结果不一致，可能表现为主备节点版本不同、校验和不一致或部分规则加载失败。\\n处置步骤：停止继续发布，记录当前版本和校验和；比较主备节点规则包；若新版本不完整，恢复最近一次批准版本并重新加载。不得直接修改生产节点上的单个规则文件。\\n验证标准：主备节点版本和校验和一致，规则加载日志无失败项，并完成抽样事件计算。\\n回退后必须执行规则包校验和抽样事件计算，两项均通过才能恢复发布。\\n## 九、升级、交接与关闭\\nP1 故障由蓝鹭应急协调组统筹，处理团队每十五分钟更新一次状态。P2 每三十分钟更新一次，超过两小时仍未恢复时升级为 P1。P3 在一个工作日内响应；同类问题七天内出现三次时转入问题复盘。\\n交接记录必须包含未关闭事件、已执行动作、禁止重复动作、隔离设备、临时配置、待观察指标和下一责任人。事件关闭前确认核心能力恢复、观察期结束、证据完整、临时权限已撤销，并确定是否需要复盘。\\n排障记录不得包含真实密码、访问令牌和个人身份信息。本文全部内容用于知识库与评测，不对应真实设备或真实生产环境。\", \"documentTitle\": \"04_曙光智造园区故障排查指南\", \"retrievalSource\": \"KEYWORD\", \"similarityScore\": 11.36425}, {\"url\": \"http://127.0.0.1:9090/know-engine/01_曙光智造园区概览.md\", \"chunkId\": \"353283299259580424\", \"documentId\": \"1\", \"rerankScore\": -1.7145936489105225, \"chunkContent\": \"## 数据质量与留痕\\n传感器记录必须包含资产编号、采集时间、数值、单位和质量标记。缺少资产编号或采集时间的数据不得进入正式报表。重复数据按“资产编号加采集时间”去重，冲突记录保留最后一次通过质量校验的值。\\n工单、审批单、操作日志和验证截图共同构成处置证据。证据保存期间不得修改原始时间戳。导出超过 10,000 行时，需要 Data Steward 和值班经理双人审批；导出文件应标注用途、责任人和到期日期。\", \"documentTitle\": \"01_曙光智造园区概览\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.7881454}]', '{\"mrr\": 1.0, \"hitAtK\": true, \"recallAtK\": 0.5}', '{\"relevancy\": 0.85, \"faithfulness\": 0.9, \"contextRecall\": 1.0, \"relevancyReason\": \"回答直接列出了至少需保存的时间线、关键日志、操作记录、配置差异和验证结果等证据，基本完整；但补充的工单、审批单、操作日志、截图及保存规范等内容略有冗余，超出问题核心。\", \"contextPrecision\": 0.8, \"answerCorrectness\": 1.0, \"faithfulnessReason\": \"核心答案“时间线、关键日志、执行命令或操作、配置差异、验证结果”直接来自上下文；补充的工单、审批单、操作日志、验证截图和禁止项也可由上下文支撑。个别表述属于基于原文的合理展开，无明显捏造或矛盾。\", \"contextRecallReason\": \"检索上下片段1明确列出排障记录至少需保存时间线、关键日志、执行命令或操作、配置差异和验证结果，完整覆盖标准答案。\", \"contextPrecisionReason\": \"片段1直接给出排障记录至少需保存时间线、关键日志、执行命令或操作、配置差异和验证结果，片段2也补充了处置证据要求；但上下文中大量具体故障处置、数据导出审批等内容与问题弱相关或冗余，未全部高度相关。\", \"answerCorrectnessReason\": \"模型回答完整列出了标准答案中的五类证据：时间线、关键日志、执行命令或操作、配置差异和验证结果；额外补充不影响核心语义。\"}', 27599, 1, NULL, '2026-09-09 01:09:59', '2026-09-09 01:09:59', 0, 0);
INSERT INTO `eval_run_case` VALUES (273, '20260908-235537-d56929be', 'aurora-xlsx-001', 'AU-GW-001 的资产名称和责任团队是什么？', 'AU-GW-001 的资产名称是**北区边缘网关**，责任团队是**边缘平台组**。', 'AU-GW-001 资产名称 责任团队', '[\"353285847806771200\", \"353285847806771202\", \"353285847806771201\", \"353285847810965504\", \"353285880643977216\"]', '[\"5\", \"6\"]', '[{\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771200\", \"documentId\": \"5\", \"rerankScore\": 5.56184196472168, \"chunkContent\": \"资产编号：AU-GW-001; 资产名称：北区边缘网关; 生产区：A区; 子区域：A1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-18; 下次维护时间：2026-09-02 02:00; 维护任务：固件校验; 维护时长（分钟）：45; 关键等级：关键; 备注：负责A区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.8052931}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771202\", \"documentId\": \"5\", \"rerankScore\": 1.960213541984558, \"chunkContent\": \"资产编号：AU-GW-003; 资产名称：装配区边缘网关; 生产区：C区; 子区域：C1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-20; 下次维护时间：2026-09-16 02:00; 维护任务：时钟校验; 维护时长（分钟）：30; 关键等级：关键; 备注：负责C区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79277813}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847806771201\", \"documentId\": \"5\", \"rerankScore\": 1.5095771551132202, \"chunkContent\": \"资产编号：AU-GW-002; 资产名称：南区边缘网关; 生产区：B区; 子区域：B1; 设备型号：HG-220; 责任团队：边缘平台组; 运行状态：运行; 最近巡检日期：2026-08-19; 下次维护时间：2026-09-09 02:00; 维护任务：缓存检查; 维护时长（分钟）：30; 关键等级：关键; 备注：负责B区采集\", \"documentTitle\": \"05_曙光智造园区资产与维护清单\", \"retrievalSource\": \"HYBRID\", \"similarityScore\": 0.79446626}, {\"url\": \"http://127.0.0.1:9090/know-engine/05_曙光智造园区资产与维护清单.xlsx\", \"chunkId\": \"353285847810965504\", \"documentId\": \"5\", \"rerankScore\": 0.9341731667518616, \"chunkContent\": \"资产编号：AU-AP-101; 资产名称：无线接入点一号; 生产区：A区; 子区域：A1; 设备型号：AP-6; 责任团队：网络保障组; 运行状态：运行; 最近巡检日期：2026-0